{"assumptions":[],"created_at":"2026-10-26T19:49:02.093034+00:00","domain":"probability theory","id":"claim_c10ec5ee69faba1a3685325161c80e6cb15418ea2a37771249a43a0933e9748e","kind":"lemma","schema_version":1,"statement":"[Lem 7 of arXiv:2604.25964, 'Strong convergence rate of Euler-Maruyama approximations in temporal-spatial H\"older-norm'] For $s\in [0, T],$ $t, \widetilde{t} \in [s, T],$ $ \delta \in \widetilde{\mathbb{S}}$ and $ x\in \bR,$ let $(X^{\delta,x}_{s,t})_{t\in[s,T]}:[s,T]  \times\Omega\to\mathbb{R} $ 
be an $(\mf_t)_{t\in[s,T]}$-adapted stochastic process with c\`adl\`ag  sample paths satisfying equation \eqref{y01}. 

Then, 
\begin{enumerate}
   \item [\textup{(i)}] we have
\begin{align*}
\mathbb{E}\left[V(X^{\delta, x}_{s,t})\right] \leq e^{2.5 \overline{c}|t-s|}V(x).
\end{align*} 

\item [\textup{(ii)}] for all $p\ge 2,$ there exists a positive constant $C_p=C_p(T, m_2, m_p)$ such that \begin{align*}
\left[\mathbb{E}\left[\left|X^{\delta, x}_{s,\widetilde{t}}-X^{\delta, x}_{s,t}\right|^p\right]\right]^{1/p} 
 \leq C_p |\widetilde{t} -t|^{1/p} (e^{2.5\overline{c}T}V(x))^{1/p}.
\end{align*} 
\end{enumerate}
Here, the constant $\overline{c}$ is given in {\bf A3, A4, A5}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:55:37.875270+00:00","domain":"probability theory","id":"claim_c1146f68a28daba27971412edcf82e1145d98e6b5c5b9cabd12af189771fb6e2","kind":"theorem","schema_version":1,"statement":"[Thm admissibilitycond of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] A sequence $\{\varepsilon_n\}_n$ is admissible for $[a,b]$ if and only if the normalized sequence $\{\gamma_n\}_n$ given by
    \begin{equation*}
        \gamma_n = \frac{n! \varepsilon_n}{(b-a)^n}, \qquad n \geq 0
    \end{equation*}
    has $\gamma_0 = 1$ and is completely monotone --- that is,
    \[
    (-1)^k (\Delta^k \gamma)_n \geq 0, \qquad n,k \geq 0,
    \]
where the forward difference operator $\Delta$ is defined by $(\Delta \gamma)_n = \gamma_{n+1} - \gamma_n$ and $\Delta^k$ denotes its $k$-fold iterate.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:42:47.765509+00:00","domain":"probability theory","id":"claim_c11a26e54370ce423fe4aeac5f8036d89b73f4b0d8544950c7af755815e6d2e2","kind":"concept","schema_version":1,"statement":"[Prop 13 (Randomized measure-valued weak solution) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(\mu_t,I_t,Z_t)_{t\in[0,T]}$ be a limit point of $(\mu^n_t,I^n_t,Z^n_t)_{t\in[0,T]}$. Then, $\mu=(\mu_t)_{t\in[0,T]}$ is a stochastic process taking values in $\mathcal{M}_{\leq 1}(\R^+)$ with $\mu_0=P_0\circ \theta_{a_0}^{-1}$ and it satisfies
\begin{equation}
\di \langle\mu_t,\phi\rangle	=\langle\mu_{t},\tfrac{{1}}{2}\sigma_{A}(t,\cdot)^{2}\partial_{xx}\phi\rangle\dt+\langle\mu_{t}, (b_{A}(t,\cdot)-A^\prime_{t})\partial_{x}\phi\rangle\dt + \di Z^{\phi}_t,
\end{equation}
for all $t\in[0,T]$ and all $\phi \in C^{2}_b(\R)$, almost surely, with 
\begin{equation}
\E\biggl[\int_0^t H_s \di Z_t^{ \phi}\biggr]
= \lim_{\delta \downarrow 0}  \E\biggl[\int_0^t H_s \bigl( \tfrac{1}{2} \partial_x \phi(0) - \phi(0) \gamma(s, C_s) \bigr)\langle \mu_s, \sigma_A(s, \cdot)^2 \psi_\delta  \rangle \ds \biggr],
\end{equation}
for all $t\in[0,T]$, all $\phi\in C_b^2(\R)$, and
all bounded continuous processes $H$ adapted to the filtration \eqref{eq:limit_filtration} generated by $(\mu,I)$, where
\begin{equation}
A_t = a_0 + \alpha\int_{t-\bar{d}}^t \varrho(t-s) I_{s} \ds,\quad C_t = \int_{t-\bar{d}}^t \varrho(t-s) (I_{s} - I_{s-\bar{d
}})\ds,\quad I_t= 1- \mu_t(\R^+).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:51:52.126301+00:00","domain":"probability theory","id":"claim_c126f48bf861f506e7331b4a08439124d0b9a0a2d3f996fbcd88677e8f448ffb","kind":"lemma","schema_version":1,"statement":"[Lemma L:arc-full-annular-decomposition of arXiv:2607.15966, 'Canonical Mandelbrot Cascades on Curves Are Rajchman'] Fix \(K,K_1\in\mathbb{N}\), \(\varepsilon\in\mathbb{Q}_{>0}\), \(j\in\mathbb{N}\), and \(h\in\mathbb{N}_0\).
Then, for every \(n\geq1\) and \(\xi\in\Lambda_n(K,\varepsilon)\), one has
\[
\begin{aligned}
\widehat{\mu_\gamma}(\xi)
&=
\left[
\widehat{\mu_\gamma}(\xi)
-
\sum_{|u|=n+h}
\mu(I_u)\mathrm{e}^{i\phi_\xi(t_u)}
\right]
+
\sum_{|u|=n+h}
A_u
\bigl(Z_\infty^{(u)}-1\bigr)
\mathrm{e}^{i\phi_\xi(t_u)}
\\
&\quad+
\left[
\sum_{|u|=n+h}
A_u\mathrm{e}^{i\phi_\xi(t_u)}
-
\int_0^1
\mathrm{e}^{i\phi_\xi(t)}
\,\mathrm{d}\mu_{n+h}(t)
\right]
+
E_{\xi,n,h,j}^{\mathrm{safe}}
+
D_{\xi,n,j}^{(0)}
+
S_{\xi,j,n,h}.
\end{aligned}
\]

Moreover, almost surely on
\(\Omega_K \cap \mathcal{Z}_{K_1} \cap \{Z_\infty>0\}\), one has
\[
\limsup_{n\to\infty}
\sup_{\xi\in\Lambda_n(K,\varepsilon)}
\left|
\widehat{\mu_\gamma}(\xi)
\right|
\leq
C_\gamma(K+K_1)2^{-h}
+
C_\gamma
\Delta_{C_\gamma2^{-j}}(\mu).
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.487917+00:00","domain":"probability theory","id":"claim_c129a782ade4a04fc07026d6ba75b519431a2f51b1d3f52b322dd228afdf6066","kind":"definition","schema_version":1,"statement":"[Defn Neutrality condition of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] A double divisor $\left(\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right)$ satisfies the neutrality condition $\left(\mathrm{NC}_b\right)$  if 
\begin{equation}
\int\boldsymbol{\sigma}=\int \boldsymbol{\sigma}^{+}+ \int \boldsymbol{\sigma}^{-}=2b.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.489476+00:00","domain":"probability theory","id":"claim_c12ba02dbce9ca9e92bd99a46712961913c7a2f029012e646ae871ca5a93b4f4","kind":"definition","schema_version":1,"statement":"[Definition 210 of arXiv:2601.16377, '2601.16377'] We say that $\boldsymbol{F}(z) = (F_h(z))_{h = 1}^H$ is \emph{tame} if for each $h \in [H]$ there exists a complex neighborhood $\amsmathbb{M}_h$ of $[\alpha_h,\beta_h]$ such that
\begin{itemize}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]$;
\item $F_h(x^{\pm}) = \lim_{\epsilon \rightarrow 0^+} F_h(x \pm \ii \epsilon)$ exists for any $x \in (\alpha_h,\beta_h)$;
\item there exists an integer $m_{\boldsymbol{F}}$, called tameness exponent, and a real number $M_{\boldsymbol{F}}$ such that
\[
\sup_{z \in \amsmathbb{M}_h \setminus [\alpha_h,\beta_h]} \big| \big((z - \alpha_h)(z - \beta_h)\big)^{\frac{1}{2}m_{\boldsymbol{F}}} F_h(z)\big| \leq M_{\boldsymbol{F}};
\]
\item the function $x \mapsto F_h(x^+) + F_h(x^-)$ extends to a meromorphic function in $\amsmathbb{M}_h$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.665638+00:00","domain":"probability theory","id":"claim_c12fc5178c3d3d4359f337c806334b9a05eae14cd790825b15f08db8f505484b","kind":"concept","schema_version":1,"statement":"[Proposition prop:2s5c-result of arXiv:2411.00930, '\bf \Large Asymptotic Product-form Steady-state for Multiclass Queueing Networks: A Reentr'] Under Assumption~(assumption:2s5c-t-moment of the paper) and~(assumption:multi-scale-2s5c of the paper),
there exist a random vector $(Z_1^\ast, Z_4^\ast)\in\mathbb{R}_+^2$ such that
    \begin{equation*}
        (rZ_1^{(r)}, rZ_2^{(r)}, rZ_3^{(r)}, r^2Z_4^{(r)}, rZ_5^{(r)})\Rightarrow (Z_1^\ast, 0, 0, Z_4^\ast,0),\quad\text{as }r\to0,
    \end{equation*}
    where ``$\Rightarrow$'' denotes convergence in distribution.

   Moreover, $Z_1^\ast$ and $Z_4^\ast$ are independent and have the following marginal distributions
   \begin{equation*}
        Z_1^\ast\sim\exp\big(1/d_1\big),\quad\text{and}\quad Z_4^\ast\sim\exp\big(1/d_4\big),
    \end{equation*}
    with
    \begin{align}
        d_1&=\frac{\alpha_1}{2(m_1+m_3-m_5\frac{m_2}{m_4})}\Big((m_1+m_3-m_5\frac{m_2}{m_4})^2c_{e,1}^2+m_1^2c_{s,1}^2+m_3^2c_{s,3}^2+m_5^2c_{s,5}^2\nonumber\\
        &\qquad\qquad\qquad\qquad\qquad\quad+(\frac{m_5}{m_4})^2\big(m_2^2c_{s,2}^2+m_4^2c_{s,4}^2\big)\Big)\\
        d_4&=\frac{\alpha_1}{2m_4}\Big((m_2+m_4)^2c_{e,1}^2+m_2^2c_{s,2}^2+m_4^2c_{s,4}^2\Big).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.597421+00:00","domain":"probability theory","id":"claim_c130dd6c5f0e0a58ca89f7380f196566ffd4a8cd0e46edb635856c694a5f8e25","kind":"concept","schema_version":1,"statement":"[Proposition 15 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] There is a full Harris set $H\in\calX$ such that, for every $x\in H$ and every deterministic sequence $k\to_\lambda\infty$,

