{"assumptions":[],"created_at":"2026-10-27T11:26:52.654091+00:00","domain":"probability theory","id":"claim_c15fc516a72a813373d705d70e038e7427e14e7344bfd00461f82043c8cd8ccf","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $p\in (2d,\infty)$ and consider an initial value
\begin{equation}
    (u^0,w^0)\in W_{p}^{1,+}(\Omega)  \times L_\infty^+(\Omega) \,.
\end{equation}
Then there is a unique couple $(u,w)$ of functions satisfying
\begin{subequations}
\begin{align}
&u \in  C^1\big((0,\infty),L_p(\Omega)\big) \cap  C\big((0,\infty),W_{p,N}^{2}(\Omega)\big)\cap C\big([0,\infty),W_{p}^{1}(\Omega) \big)\,,\\
& w\in C^1 \big([0,\infty),L_\infty(\Omega)\big)\,,\qquad v := \mathcal{K}[w-\langle w\rangle] \in C^1\big([0,\infty),W_{p,N}^{2}(\Omega)\big)\,,
\end{align}
such that $(u,v,w)$ is a global non-negative strong solution to~\eqref{E}.
\end{subequations}
In fact, the mapping 
\begin{equation*}
	\boldsymbol{\Psi}:(u^0,w^0)\mapsto (u,w)
\end{equation*} 
defines a global semiflow on $W_{p}^{1,+}(\Omega) \times L_\infty^+(\Omega)$.  
Moreover, 
\begin{itemize}
    \item  for $t\ge 0$, it holds that
    \begin{equation}
        \|u(t)\|_1 = \|u^0\|_1\,, \quad \|w(t)\|_1 \le \max\big\{ \|w^0\|_1 , \|u^0\|_1 \big\}\,; 
    \end{equation}
	\item  if $u\in L_\infty((0,\infty),L_m(\Omega))$, then $(u,w)\in L_\infty((0,\infty)\times\Omega,\R^2)$;
	\item  if $\Omega=\mathbb{B}_R$  and $(u^0,w^0)$ are radially symmetric, then $(u,v,w)(t)$ are radially symmetric for all $t\ge 0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.092931+00:00","domain":"probability theory","id":"claim_c15fd828a375a981d01a4064e2cba2f5001790d3bc4f716ce7a4abd4fa82d711","kind":"theorem","schema_version":1,"statement":"[Prop eq:strong:Markov:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Let $T$ be a $(\overline{\mathcal{F}}_{t+})$-stopping time such that  $T > 0$, $\mathbf{N}_{x,r}$-a.e. For every non-negative $\overline{\mathcal{F}}_{T+}$-measurable function $\Phi$  and non-negative measurable function $F$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_{f}(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$, we have 
\begin{equation} 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}} \Phi \cdot  F \big( (\rho_{T + s }, \overline{W}_{T + s } : s \geq 0  ) \big)  \big) 
    = 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}}  \Phi \cdot  \mathbb{E}^{\dag}_{\rho_T, \overline{W}_T} [ F ]   \big).  
