{"assumptions":[],"created_at":"2026-10-26T20:55:18.056230+00:00","domain":"probability theory","id":"claim_c1d017033372ddcab37678e70f72d7c2e8707f940cb3c0209cdf44e65dc294d1","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $a\in\R^\sS$ and $b\in \R^\D$, we have
\begin{gather}
    a^\Vec\cdot b = D a \cdot b^\summ, 
    \\
    (a^\Vec)^\avg=a. 
\end{gather}
For every $b\in\R^\D$, we have
\begin{align}
    \nabla_d \xi^\Vec(b) = \nabla_s\xi(b^\summ),\quad\forall d \in \sfM_s\quad\text{and thus}\qquad \nabla\xi^\Vec(b) = \Ll(\nabla\xi(b^\summ)\Rr)^\Vec.
\end{align}
For every $b,b'\in\R^\D$, we have
\begin{align}
    b'\cdot \nabla\xi^\Vec(b) = D b'^\summ\cdot \nabla \xi(b^\summ)\qquad\text{and thus}\qquad \theta^\Vec(b)= D \theta (b^\summ).
\end{align}
For every $t\in\R_+$, $p, q \in  \mcl Q_\infty^\sS$ and $\up,\uq\in \mcl Q_\infty^\D$ satisfying $p=\up^\summ$ and $q^\Vec= \uq$, we have
\begin{align}
    \psi^\Vec\Ll(\uq + t\nabla\xi^\Vec(\up)\Rr) = \D \psi\Ll(q+t\nabla\xi(p)\Rr)\quad\text{and thus}\quad \sP^\Vec_{t,\uq}(\up) = \D\sP_{t,q}(p).
\end{align}
Moreover, 
\begin{align}
    \text{if}\quad  \up= \partial_{\uq}\psi^\Vec\Ll(\uq + t\nabla\xi^\Vec(\up)\Rr),\qquad\text{then}\quad p = \partial_q \psi(q+t\nabla\xi(p)).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:55:18.935704+00:00","domain":"probability theory","id":"claim_c1da13f5dc400f71de1facf46a5a911cffb53114d42aaacbb5e63ae2c1ede811","kind":"lemma","schema_version":1,"statement":"[Lemma lem:A-i-bound of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] For $i\geq 2$, define \[
