\]
For every integer $i\ge 2$,
\[
  A_i \le 4\,i!.
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.628665+00:00","domain":"probability theory","id":"claim_c1dcf0435833e6b9c73b66b9ec49b0c1962db48a5bc19bd9085c2578e79afe8d","kind":"concept","schema_version":1,"statement":"[Proposition prop:small_jump_bound_comonotonic of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let L\'evy processes 
$\bm{X}$ and $\bm{Y}$
have characteristic triplets denoted by $(\bm{\gamma_X},\bm{\Sigma_X}\bm{\Sigma_X}^{\scalebox{0.6}{$\top$}},\nu_{\bm{X}})$ and $(\bm{\gamma_Y},\bm{\Sigma_Y}\bm{\Sigma_Y}^{\scalebox{0.6}{$\top$}},\nu_{\bm{Y}})$, respectively.
Assume that 
 the L\'evy measures of $\nu_{\bm{X}}$ and $\nu_{\bm{Y}}$ admit the radial decomposition in~(equation eq:radial_decomp of the paper)
and construct the processes $(\bm{M^X},\bm{M^Y},\bm{L^X},\bm{L^Y})$ 
by~(equation eq:comono_coupling_1 of the paper) and~(equation eq:comono_coupling_2 of the paper), independent of standard Brownian motions $\bm{B^X}$ and $\bm{B^Y}$ on $\mathbb{R}^d$. Then there exists constants $\bm{\varpi_X},\bm{\varpi_Y}\in\mathbb{R}^d$, such that $\bm{X}_t\overset{d}{=} \bm{\varpi_X}t+\bm{\Sigma_X}\bm{B}^{\bm{X}}_t+\bm{M}^{\bm{X}}_t+\bm{L}^{\bm{X}}_t$ and $\bm{Y}_t\overset{d}{=} \bm{\varpi_Y}t+\bm{\Sigma_Y}\bm{B}^{\bm{Y}}_t+\bm{M}^{\bm{Y}}_t+\bm{L}^{\bm{Y}}_t$ for all $t\in[0,1]$. Moreover, this  coupling of $\bm{X}$ and $\bm{Y}$ satisfies   
\begin{align}
    \mathds{E}\bigg[\sup_{t \in [0,1]}\big|\bm{M^X}_t-\bm{M^Y}_t\big|^2\bigg]&\leqslant 4\int_{[\varepsilon,\infty)\times \mathbb{S}^{d-1}} (\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))^2 \mathrm{d} x \otimes \sigma(\mathrm{d} \bm{v}).
\end{align}
Furthermore, if $\int_{\mathbb{R}^d_{\bm{0}}}|\bm{w}|^2\1_{\mathbb{R}^d \setminus B_{\bm{0}}(1)}(\bm{w})\nu_{\bm{X}}(\mathrm{d}\bm{w})<\infty$ and $\int_{\mathbb{R}^d_{\bm{0}}}|\bm{w}|^2\1_{\mathbb{R}^d \setminus B_{\bm{0}}(1)}(\bm{w})\nu_{\bm{Y}}(\mathrm{d}\bm{w})<\infty$, then 
\begin{equation}

\mathds{E}\bigg[\sup_{t\in[0,1]}\big|\bm{M^X}_t+\bm{L^X}_t-(\bm{M^Y}_t+\bm{L^Y}_t)-\bm{m}t\big|^2\bigg]
\leqslant 4\int_{(0,\infty)\times \mathbb{S}^{d-1}}(\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))^2 \mathrm{d} x \otimes \sigma(\mathrm{d} \bm{v}),
\end{equation}
were we define $\bm{m}\coloneqq\mathds{E}[\bm{L^X}_1-\bm{L^Y}_1]
=\int_{(0,\varepsilon)\times \mathbb{S}^{d-1}}\bm{v}
(\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))\mathrm{d} s \otimes\sigma(\mathrm{d}\bm{v})\in\mathbb{R}^d$. In particular, 
\begin{equation}

\begin{split}
\mathcal{W}_2(\bm{X},\bm{Y})
&\leqslant |\bm{\varpi_X}-\bm{\varpi_Y}+\bm{m}|
    + 2 d^{1/2}|\bm{\Sigma_X}-\bm{\Sigma_Y}|\\
&\qquad   + 2\bigg(\int_{(0,\infty)\times \mathbb{S}^{d-1}}(\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))^2 \mathrm{d} x \otimes \sigma(\mathrm{d} \bm{v})\bigg)^{1/2}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:09:23.950453+00:00","domain":"probability theory","id":"claim_c1e155b71b63926f1a2ac10aa3337c666b18f27f346a7c2df4dc2f0f1baf6ca1","kind":"concept","schema_version":1,"statement":"[Theorem 9 (Wei-Kuo Chen, {\cite[Theorem~1) of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] {Chen2024GaussianConvexity}}]
Let $G$ be a standard Gaussian vector in $\R^m$, and let $\Psi:\R^m\to\R$ be convex. Assume that for every $s>0$, $\E e^{s\Psi(G)}<\infty$. Define
