{"assumptions":[],"created_at":"2026-10-27T16:50:27.033395+00:00","domain":"probability theory","id":"claim_c201f69f8990764e41f011172d481267b97168c50c68f4b15b02d6bd78e5b9c3","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2505.14012, 'Ergodicity for stochastic neural field equations'] \phantom{ }
\begin{enumerate}[(I)]
\item  A strong solution $u(t)$, $t\in[0,T]$ to (equation eq:gen_model of the paper) is an $H$-valued predictable process, such that
\begin{align*}
&\mathbb{P}\left(\int_0^T (\|u(s)\| + \|\alpha u(s)\|)\, ds <\infty \right) = 1,\quad
\mathbb{P}\left(\int_0^T \|B(u(s))\|^2_{L_2(V,H)}\, ds<\infty\right) = 1,
\end{align*}
and satisfies for arbitrary $t\in[0,T]$,
\begin{align*}
&u(t) = u(0) + \int_0^t\left(-\alpha u(s) + KF(u(s))\right)\, ds + \int_0^t B(u(s))\, dW(s),
\end{align*}
$\mathbb{P}$-a.s. in $H$.

\item A weak solution $u(t)$, $t\in[0,T]$ to (equation eq:gen_model of the paper) is an $H$-valued predictable process, such that
\begin{align*}
&\mathbb{P}\left(\int_0^T\|u(s)\|\, ds<\infty \right) = 1,\quad
\mathbb{P}\left(\int_0^T\|B(u(s))\|^2_{L_2(V,H)}\, ds<\infty\right) = 1,
\end{align*}
and satisfies for arbitrary $t\in[0,T]$,
\begin{align*}
\langle u(t),v\rangle
=&\langle u(0),v\rangle + \int_0^t\left(\langle u(s),-\alpha v\rangle + \langle KF(u(s)),v \rangle\right)\, ds
+ \int_0^t\langle v,B(u(s))\, dW(s)\rangle,
\end{align*}
$\mathbb{P}$-a.s. for every $v\in H$.

\item A mild solution $u(t)$, $t\in[0,T]$ to (equation eq:gen_model of the paper) is an $H$-valued predictable process that satisfies 
\begin{align*}
&\mathbb{P}\left(\int_0^T \|u(s)\|\, ds<\infty  \right) = 1,\quad\mathbb{P}\left(\int_0^T \|B(u(s))\|^2_{L_2(V,H)}\, ds\right) = 1,
\end{align*}
and satisfies for arbitrary $t\in[0,T]$,
\begin{align*}
&u(t) = S(t)u(0) + \int_0^t S(t-s)KF(u(s))\, ds+\int_0^t S(t-s)B(u(s))\, dW(s),
\end{align*}
$\mathbb{P}$-a.s. in $H$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.312883+00:00","domain":"probability theory","id":"claim_c20527e5906ad98a2bb6389df54d2a1f1c295fa0fdda79ae3969a097978e9831","kind":"definition","schema_version":1,"statement":"[Definition def-sol-H1 of arXiv:2606.00325, 'Ergodicity for a class of stochastic Hasegawa-Mima equations with dissipation'] A stochastic process $\phi_t$ is a weak solution of (equation eq:main of the paper) if  $\phi\in C(0, T; V)\cap L^2(0, T; W)$ almost surely, it is adapted and for every $\psi  \in  V$ it verifies $\mathbb{P}-$a.s. for every $t\ge 0$
    \begin{align}
        \left\langle\phi(t)-\phi_0, \psi\right\rangle &+  \left\langle\nabla \phi(t)-\nabla \phi_0, \nabla\psi\right\rangle + \int_0^t\brak{A^{1/2}\phi(s), A^{1/2} \psi}ds \\ &+ \int_0^t \left\langle\nabla^\perp \phi(s)\cdot \nabla v, \psi\right\rangleds + \int_0^t \left\langle\Delta \phi(s), \nabla^\perp \phi(s)\cdot \nabla \psi\right\rangleds = \left\langle \psi, W_t\right\rangle.\notag
    \end{align}","status":"unverified"}

