\sum_{k=0}^{\lfloor n/2\rfloor}
(-1)^{j+k}
\dfrac{n! (2(n-1-k-j))!}{(n-2k)! k! (n-1-k-j)! j!}
= 0.
\end{displaymath}
\item In the case $j = \lfloor n/2\rfloor$,
\begin{displaymath}
