            \end{aligned}
        \end{equation}
        where ${\mathcal R}_{{\mathcal{O}}_T\circ\cdots\circ{\mathcal{O}}_1\left({\mathcal T_0}\right)}$ is defined as in (equation reminder_terms_expansion of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:15.354233+00:00","domain":"probability theory","id":"claim_c32ced9bf017a3ff42d653f31d6f809f1a28b4f7e045fe0c1398867cc113a9f6","kind":"definition","schema_version":1,"statement":"[10 19 of arXiv:2607.12303, 'Marginal Stationary Distributions and Convergence Rates of Higher Order Markov Chains'] {\rm
