{"assumptions":[],"created_at":"2026-10-26T20:56:25.272176+00:00","domain":"probability theory","id":"claim_c438c1178690a170b46c18c0f2c95cf6d5124b0c3ea2a033d8963ee87143fabb","kind":"concept","schema_version":1,"statement":"[Proposition 7 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] For $n\ge a$, let
\begin{equation*}
s_n=\Big(\frac{a(2p-1)}{2a(1-p)-1}\Big)^2\sum_{k=a}^{n}(b_kc_k^{-1})^2.
\end{equation*}
Then,\vspace{.1cm}\\
\noindent{(i)} for $0\le p< (4a-1)/4a$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{s_n}{n^{4a(1-p)-1}}=\frac{(\Gamma(a(2p-1)+1))^2}{4a(1-p)-1},
\end{equation*} 
\noindent{(ii)} for $p=(4a-1)/4a$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{s_n}{\log n}=\Big(\Gamma\Big(a+\frac{1}{2}\Big)\Big)^2,\ \ \text{and}
\end{equation*}
\noindent{(iii)} for $(4a-1)/4a<p\le 1$, we have $\lim_{n\to\infty}s_n=l$,
where $l$ is some non zero constant. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:12:13.460252+00:00","domain":"probability theory","id":"claim_c43ab1ad899e60cace1dbafc667aea57b8f360eb2a6f544e42fdf7afc8616e22","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2608.28307, 'Rigidity of closed $\lambda$-self-expanders'] Let $x:M^n\to \mathbb{R}^{n+1}$ be a $\lambda$-self-expander, then we have
\begin{equation}
\begin{split}
&LH=S(\lambda-H)-\frac{1}{2}H,\\
&LS=2|\nabla h|^2-S-2S^2+2\lambda Str(h^3),\\
&L|x|^2=|x|^2+2\lambda\langle x,\xi\rangle+2n.
\end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.114643+00:00","domain":"probability theory","id":"claim_c43ff87d52d6269d8c58c4481c715ef353260dfa7dcd956ac527daf453bd240e","kind":"lemma","schema_version":1,"statement":"[Lem L:1.1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that $X$ satisfies (AC), (H1a), and (H1b), and additionally that $({\mathcal{E}},{\mathcal{F}})$ is transient. 

Let $B\subset E$ be a nearly Borel set of finite $0$-order capacity. Then there exists a unique  finite, positive measure $\nu_B$ with $\mathrm{supp}[\nu_B]\subset \overline{B}$ such that 
\begin{equation}
    \mathbb{P}^x[\sigma_B<\infty]=\int_E u(x,y)\nu_B(\mathrm{d} y),\quad \forall x\in  E,
\end{equation}
where $u(x,y)$ denotes the potential kernel of $X$.
In particular,
\begin{equation}
{\mathbb{P}}^x\left[\sigma_B\le t\right] \ge \emph{Cap}_{(0)}(B)\inf_{y\in \overline B}\int_0^t  p(s, x, y)\mathrm{d} s,\quad \forall t>0,x\in E.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:41.018718+00:00","domain":"probability theory","id":"claim_c444d44a0f7df559c6e0ad7b9433ded5d8729ae27bcacdc22eb104471a8bfe4a","kind":"concept","schema_version":1,"statement":"[Theorem mt1 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Let $(\ell_N:N\ge 1)$ be the sequence such that $\ell_N = N^{4/5}$ in
dimension $1$, $\ell^3_N \log \ell_N = N^2$ in
dimension $2$, and $\ell_N = N^{4/3d}$ in dimension $d\ge 3$.  Assume
that $\lim_{N\uparrow\infty}K_N=\infty$ and
$\sup_{N\ge 1} K^2_N / \ell^d_N < \infty$.  Then, there exists a
constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only on ${\boldsymbol u}^N$ and uniformly
bounded in $N$, such that
\begin{equation*}
\frac{d}{dt}\, H_N(f^N_t) \;\leq\; 
{\mathfrak c}({\boldsymbol u}^N)\,\, K^2_N
\, \big\{ H_N(f^N_t) \,+\, (N/\ell_N)^d \, \big\}
\end{equation*}
for all $t\ge 0$, $N\ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.369917+00:00","domain":"probability theory","id":"claim_c44d72afcbf02656c83f1fc2b3c2f9ecae484311c7c3887b04f22a1af9285366","kind":"theorem","schema_version":1,"statement":"[Proposition 18 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] Define the processes
