        \quad \text{for some (hence all) $\beta>0$.}
      \end{align}

  \end{enumerate}
  Then we have that
  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\arabic*)}] \setlength\itemsep{.1in}

    \item for any $\tau>0$, the sequence of laws of
      $\{\mathcal{L}u(t,\cdot;\mu)\}_{t\ge \tau}$ is tight, i.e., for any
      $\epsilon \in (0,1)$, there exists a compact set $\mathscr{K}\subset
      L^2_{\rho}(\mathbb{R}^d)$ such that
      \begin{equation}
        \mathscr{L}u(t,\cdot;\mu)(\mathcal{K}) \ge 1-\epsilon,
        \qquad \text{for all $t\ge \tau>0$};
      \end{equation}

    \item there exists a nontrivial invariant measure for~(equation E:SHE of the paper).

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

