\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}\nabla {{\tilde \Phi }_k}} \right\|_N} + {\left\| {{{\bar D}_{t,\Gamma }}{{\left( {\nabla {{\tilde \Phi }_k}} \right)}^{ - 1}}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}   ,
\end{equation}
\begin{equation}
{\left\| {{\partial _{tt}}{{\tilde \Phi }_k}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^{N + 1}  ,
