{"assumptions":[],"created_at":"2026-10-27T19:22:08.409767+00:00","domain":"probability theory","id":"claim_c53997cede5e155ec8f7678a71936c56a33476339c738a312e0bc5edfcc27665","kind":"concept","schema_version":1,"statement":"[Thm replacement of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] Let $(A_n)_{n\ge1}$, $(B_n)_{n\ge1}$, $(X_n)_{n\ge1}$, and $(Y_n)_{n\ge1}$ be sequences of $n \times n$ real symmetric matrices, where $A_n$ is a deterministic sparsity profile, $B_n$ is deterministic, and $X_n$ and $Y_n$ are both inhomogeneous Wigner matrices.  
    Let $(K_n)_{n\ge1}$ be a sequence of positive real numbers. 
    Assume:
    \begin{enumerate}
        \item (Moment matching) For each $n \geq 1$, $X_n$ and $Y_n$ match moments per Definition (def:moments of the paper).
        \item (Sparsity profile) We have
        \begin{equation} 
            \limsup_{n \to \infty} \frac{1}{n K_n} \sum_{1 \leq i < j \leq n} (A_n)_{ij} \left( \mathbb{E} |(X_n)_{ij}|^2 + \mathbb{E}  |(Y_n)_{ij}|^2 \right) < \infty.
        \end{equation}
        \item (Lindeberg's condition) For every $\varepsilon > 0$
        \begin{equation} 
            \lim_{n \to \infty} \left[ \frac{1}{nK_n} \sum_{1 \leq i \leq j \leq n} (A_n)_{ij} \left( \mathbb{E} \left[ (X_n)_{ij}^2 \chi_{\{|(X_n)_{ij}| > \varepsilon \sqrt{K_n}\} } \right] + \mathbb{E} \left[ (Y_n)_{ij}^2 \chi_{\{|(Y_n)_{ij}| > \varepsilon \sqrt{K_n}\} } \right] \right) \right] = 0,
        \end{equation}
        where $\chi_E$ denotes the indicator function of the event $E$. 
    \end{enumerate}
    Then 
    \[ \mu_{\frac{1}{\sqrt{K_n}} A_n \odot X_n + B_n} - \mu_{\frac{1}{\sqrt{K_n}} A_n \odot Y_n + B_n} \;\xrightarrow[n\to\infty]{}\; 0 \qquad\mbox{ weakly in probability}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:35:05.826353+00:00","domain":"probability theory","id":"claim_c53d7f3596518a22312579c4ce3ea8da3c4a0015af89f5222656d60680faf6fe","kind":"definition","schema_version":1,"statement":"[Defn whitenoise of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] A family of random elements $(W(t))_{t\in[0,T]}$, $W(t):\Omega\rightarrow X$, is called a Wiener process if
\begin{itemize}
\item $W(0)=0$ almost surely (a.s.);
\item $W(t_{i+1})-W(t_{i}) (i=0,1,\ldots, n-1)$ are independent random elements for every $0\leq t_{0}<t_{1}<\cdots t_{n}\leq T$;
\item for every $t\in [0,T]$, $W(t)$ is a Gaussian random element with mean zero and covariance operator $tQ$, where $Q:X^{\ast}\rightarrow X$ is a fixed Gaussian covariance.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:31:20.609138+00:00","domain":"probability theory","id":"claim_c53ee60147e8b4a24a7d618b3fe226edc047c0857295f45ad84280a22022d085","kind":"definition","schema_version":1,"statement":"[Definition 8 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Let $\mu,\nu\in\mathcal{P}_p(E)$. A \textit{coupling} of $\mu$ and $\nu$ is a probability measure $\pi$ on $E\times E$ such that
    $$\pi(A\times E)=\mu(A),\qquad \pi(E\times B)=\nu(B),$$
    for all Borel sets $A,B\subseteq E$. The set of all couplings of $\mu$ and $\nu$ is denoted by $\Pi(\mu,\nu)$. The \textit{$p$-Wasserstein distance} of $\mu$ and $\nu$ is defined by
    \begin{equation}
        W_p(\mu,\nu):=\left(\inf_{\pi\in\Pi(\mu,\nu)}\int_{E\times E}d(x,y)^p\dd\pi(x,y)\right)^{\frac{1}{p}}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.861111+00:00","domain":"probability theory","id":"claim_c53f4dfe92c22c33e80f1b116cd66e686819b761d6a5c437fe98f392cc736384","kind":"lemma","schema_version":1,"statement":"[Lemma lem:DDapprox of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] (An Approximation for Donsker's Delta) For all $x\in (0,1)$ it holds that
	\begin{equation}
		L_+^2(\mathcal{S}'(\mathbb{R}), \mu) \mathrel{\reflectbox{$\in$}} \gamma_{\varepsilon}(\beta_x) \xrightarrow{\varepsilon \downarrow 0} \delta_0(\beta_x) \;\,\text{in $(\mathcal{S})'$},
	\end{equation}
	and for all $\varepsilon >0$, $x\in (0,1)$ and $\varphi \in \mathcal{S}(\mathbb{R})$ it holds
	\begin{align*}
		&\mathrm{T}(\gamma_{\varepsilon}(\langle q_x, \cdot \rangle))(\varphi)
		= \frac{1}{\sqrt{2\pi (x(1-x)+\varepsilon)}}\\
		&\quad\quad\quad \cdot\exp\left( -\frac{1}{2}\int_{\mathbb{R}}\varphi^2ds + \left(\frac{1}{2x(1-x)}-\frac{\varepsilon}{2(x(1-x)+\varepsilon)}\right) \left(\int_{\mathbb{R}} q_x \varphi ds\right)^2\right),
	\end{align*}
	and further, for all $z\in\mathbb{C}$, we have
	the bound
	\begin{equation}
		|\mathrm{T}(\gamma_{\varepsilon}(\langle q_x, \cdot \rangle))(z\varphi)|\leq \frac{1}{\sqrt{2\pi x(1-x)}}\exp\left(\frac{3}{2}|z|^2\|\varphi\|_{L^2(\mathbb{R})}^2\right).
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.258417+00:00","domain":"probability theory","id":"claim_c5453994c17989ed660d81da948763b33ab45a7507ccf55a92c55e2d240d5926","kind":"definition","schema_version":1,"statement":"[Dfn 79 ({\cite[Definitions 2.5.6 and 8.1.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {HDP18}}]\quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]For a real-valued random variable $X$, we define its sub-Gaussian norm 
  $\|X\|_{\psi_2}$ by setting
  \begin{align*}
    \|X\|_{\psi_2}:=\inf\{t>0:E[\exp(X^2/t^2)]\le 2\}.
  \end{align*}
   \item [$\rm{(ii)}$]Let $(X_t)_{t\in T}$ be a real-valued stochastic process on a metric space $(T,d)$.
   We say the process has a sub-Gaussian increments if there exists a constant $K\in (0,\infty)$
   such that
   \begin{align}
    \|X_t-X_s\|_{\psi_2}\le Kd(s,t),\qquad s,\;t\in T.
   \end{align}
  \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.659536+00:00","domain":"probability theory","id":"claim_c551caf9a4baebb4586881aff485c4bd20c047e2eff5e86aaa9a2b5698c019de","kind":"theorem","schema_version":1,"statement":"[Theorem 15 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] Let \(g\) be defined by \eqref{def_g_sig}. If \(Z\) is a solution to
