and
\begin{equation}
(\mathcal{D}_2 T (\psi,x) [y])^k=y^k-\sum_{p=1}^d \int_0^\star \partial_p b_k(x_s)y_s^k ds - \sum_{p=1}^d \sum_{\ell=1}^m \int_0^\star \partial_k \sigma_{p,\ell} d(\varphi_s^\ell+\psi_s^\ell).
