{"assumptions":[],"created_at":"2026-10-27T19:26:26.759628+00:00","domain":"probability theory","id":"claim_c592ced74bd6adefe4f60ab189869c7d43ef4552c7dfd141c51a1056a13148a6","kind":"lemma","schema_version":1,"statement":"[Lemma lem:BLPP-propagator of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The propagator satisfies the following identities.
\begin{enumerate}[label=\textup{(\roman*)},
leftmargin=*]
\item \textup{(Splitting with sign.)}
For $i < p < j$,
\begin{equation}
\partial_{a_p} [B_{\mathbf{t},\mathbf{a}}]_{ij}(z, w)
= -[B_{\mathbf{t},\mathbf{a}}]_{ip}(z, a_p)[B_{\mathbf{t},\mathbf{a}}]_{pj}(a_p, w).
\end{equation}

\item \textup{(Flux conservation.)}
For $i < j$,
\begin{equation}
\Bigl(\partial_z + \partial_w
+ \sum_{i < p < j} \partial_{a_p}\Bigr)
[B_{\mathbf{t},\mathbf{a}}]_{ij}(z, w) = 0.
\end{equation}

\item \textup{(Time conservation.)}
\begin{equation}
\sum_{p=1}^k \partial_{t_p}
[B_{\mathbf{t},\mathbf{a}}]_{ij} = 0.
\end{equation}

\item The propagator is $n$-independent.
\end{enumerate}","status":"unverified"}

