		\begin{align*}
			\mathbb{E}_{s}^i[  \mathds{1}_C \, Y  ] &=  \mathds{1}_{C}\,  \mathbb{E}_{s}^i[ Y],\\
			\mathbb{E}_{s}^i[ I^j(s) \,  Y  ] &= \mathds{1}_{j=i} \,  \mathbb{E}_{s}^i[ Y]{,}
		\end{align*}
		\item[(ii)] {f}or $t \in [s,\infty)$ and $n \in \mathbb{N}_0$ it holds that
		\begin{align*}
			\mathbb{E}_{s}^i[Y] &= \mathbb{E}_{s}^i[\mathbb{E}_{t}^{Z(t)}[Y]],\\
			\mathds{1}_{\{\tau_n > s\}}	\, \mathbb{E}_{s}^i[Y] &= \mathds{1}_{\{\tau_n > s\}}	\,  \mathbb{E}_{s}^i[\mathbb{E}_{\tau_n}^{\zeta_n}[Y]].
		\end{align*}

	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.460384+00:00","domain":"probability theory","id":"claim_c5f3a951421fbfb79a962655553e27566fab942ed07a3a209371a790e7ed97a0","kind":"lemma","schema_version":1,"statement":"[Lem 13 (Vanishing viscosity limit) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] For fixed $n\in\mathbb N$, equation \eqref{eq:penalized-hyperbolic} admits a unique kinetic solution $u_n$ in the sense of Definition \ref{def:kinetic-penalized}.
