where 
\begin{align*}
  \g{c}{sg1,n}:=\g{c}{estres,n}(t+\alpha^{-1}+\alpha^{-1}c_1(t,\kappa,p)\mu(F)^{1/p})+\alpha^{-1}\mu(F)^{1/p}( c_1(t,\kappa,p)+c_1([0,t],\kappa,p)).
\end{align*}","status":"unverified"}

