{"assumptions":[],"created_at":"2026-10-26T19:39:41.437832+00:00","domain":"probability theory","id":"claim_c62921adc142bbcb9a5162c311454f97f4fa293605817c493f5b1bc753c6ac0d","kind":"definition","schema_version":1,"statement":"[Defn 1 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\varrho\in \hspace{0.1cm} ]0,1]$. We define $\mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$ as the set of functions $f:[0,1]^d_x\times \T^d_\xi\to \C$ that are smooth with respect to $\xi$ and such that 
    \begin{enumerate}
        \item there exists a finite family of open connected disjoint sets $U_1,...,U_s$ of $[0,1]^d$ so that
        \begin{equation}
            \overline{\bigsqcup_{j=1}^s U_j}=[0,1]^d,
        \end{equation}
        \item for all $j\in \disc{1}{s}$, there exists  $f_j:\overline{U_j}\times \T^d\to \C$ such that ${f_j}_{|U_j\times \T^d}={f}_{|U_j\times \T^d}$ and such that for all $\beta\in \N^d$, there exists $C_{j,\beta}>0$ so that for all $\xi \in \T^d$,
        \begin{equation}
            \norme{\partial_\xi^\beta f_j(\cdot,\xi)}_{\mathscr{C}^{0,\varrho}\pr{\overline{U_j}}}\leq C_{j,\beta}.
        \end{equation}
    \end{enumerate}
    Additionally, for $f\in \mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$, we will denote 
    \begin{equation}
        \mathscr{U}_f:=\bigcup_{j=1}^s \partial U_j

    \end{equation}
    the set of potential singularities of $f(\cdot,\xi)$ in $[0,1]^d$.","status":"unverified"}

