{"assumptions":[],"created_at":"2026-10-28T00:55:42.215899+00:00","domain":"probability theory","id":"claim_c7f36df34c05bfa8b6fbb7c296e73f2d0a78eb02015205f7694cd19de65046fa","kind":"concept","schema_version":1,"statement":"[Thm potential-infty of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Let $X=(X_t)_{t\geq0}$ be a killed subordinator which is not identically zero. Let $N\in\ensuremath{\mathbb{N}}$ be fixed. Assume that the Laplace exponent $\Phi(z)$ satisfies the following two conditions:
\begin{enumerate}[label={\upshape (\Alph*)}]
\item There exist constants $n\in\ensuremath{\mathbb{N}}\cup\{0\}$, $c_0\in(0,+\infty)$, $c_1,\dots,c_n\in\ensuremath{\mathbb{R}}\setminus\{0\}$ and  $ \alpha_0>\alpha_1>\dots>\alpha_n>-N+1$ with $\alpha_0\in[0,1]$, and a locally integrable function $R:(0,+\infty)\to(0,+\infty)$ such that $R(t)$ is non-increasing on $(0, r)$ for some $r>0$,  $R(t)=o(t^{-N-\alpha_n})$, as $t\to0+$, and
\begin{align}
    \bigg(\frac{d}{dz}\bigg)^{N}
     \bigg(
    \frac{1}{\Phi(z)}
    -
    \sum_{k=0}^n\frac{1}{c_k z^{\alpha_k}}
    \bigg)
    =
    O(R(|z|)),
    \quad
    \text{as $z\to0$ in $\{z\in\ensuremath{\mathbb{C}}\mid {\rm Re}\,z>0\}$}.	
\end{align} 

\item  For any $r>0$, 
\begin{align}
   \sup_{\lambda>0} \int_{\ensuremath{\mathbb{R}}\setminus(-r,r)} 
   \bigg|
   \bigg(\bigg(\frac{d}{dz}\bigg)^N
   \frac{1}{\Phi}\bigg)(\lambda+i\theta)\bigg|\,d\theta<+\infty.	
\end{align}
\end{enumerate}
Then, the potential measure $U|_{(0,+\infty)}(dx)$ restricted over $(0,+\infty)$ admits a continuous density $u(x)$ $(0<x<+\infty)$ which can be estimated as
\begin{align}
   u(x)
   =
   \sum_{k=0}^n\frac{x^{-1+\alpha_k}}{c_k\Gamma(\alpha_k)}+O(\varepsilon_1(x)),
   \quad\text{as $x\to+\infty$},
\end{align}
where 
\begin{align}
   \varepsilon_1(x)=x^{-N-1}R(x^{-1})+x^{-N}\int_{x^{-1}}^{1} R(t)\,dt.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:24:34.432621+00:00","domain":"probability theory","id":"claim_c7f870f9f231023c2bc986b4b09c1ac64a3a0c1f0d8d3de3a2dc4678cfa25c35","kind":"theorem","schema_version":1,"statement":"[Corollary 3 of arXiv:2608.31158, 'Stationary kinetic Krylov-Safonov estimates in space dimension one'] Let $|x_0|\le1$ and $r\in(0,1]$. There exist constants $\beta\in(0,1)$ and $C>1$ depending only on $\Lambda$ such that, for any solution $f$ to \eqref{dfp} in $Q_2$, 
