{"assumptions":[],"created_at":"2026-10-26T20:52:17.374940+00:00","domain":"probability theory","id":"claim_c8c5896b5de525adf8ee25f3324f15ca366ff3d78bedbc5032270b8ba8e34040","kind":"definition","schema_version":1,"statement":"[Defn 4 of arXiv:2606.04636, 'A Thomson-type variational principle for diffusion coefficients'] For two local functions $f,g:\Omega\to\C$, define 
\begin{equation}
\left\langle f,g\right\rangle =\sum_{x\in\Z^{d}}\left(\mu(f^{*}\tau_{x}g)-\mu(f^{*})\mu(g)\right).
\end{equation}

For two local admissible flows $\phi,\psi$, define 
\begin{equation}
\left\langle \phi,\psi\right\rangle =\frac{1}{4}\sum_{x,y,z\in\Z^{d}}\mu\left[c(y,z;\eta)^{-1}\phi(\eta,\eta^{y,z})^{*}\,\tau_{x}\psi(\eta,\eta^{y,z})\right].
\end{equation}

Note that, thanks to the IID structure of $\mu$, these inner products
are indeed well defined on the spaces of local functions and local
admissible flows. In the rest of this section, just as in \cite[Proof of Proposition II.2.2 and equation II.2.155]{Spohn2012IPS},
we consider the Hilbert spaces $\cH_{1}$ and $\cH_{2}$ given by
(equivalence classes of) their completion.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:02.064912+00:00","domain":"probability theory","id":"claim_c8c84b728c44b1983509400defe34a986421113b9fabb3451a67e35ee489cbb7","kind":"concept","schema_version":1,"statement":"[Lem bootstrap of arXiv:2601.00119, 'The largest common subtree of two random trees'] For any $\nu \in (0,1)$ and $\varepsilon > 0$, there exist $c, C > 0$ such that for all $h\geq 1$,
  \begin{equation}
    p_{\varepsilon + 2\nu}(h) \leq C\frac{\log(h)}{h^{\varepsilon}}p_{\varepsilon}(h) + Ch^{2+\nu/4}\exp(-h^{c\nu^2}).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-09-07T12:18:10.808034+00:00","domain":"probability theory","id":"claim_c8d7eb6d72df22102d9e4564ecf3aefb89a73dd29dc5e267d204f3672540e61e","kind":"lemma","schema_version":1,"statement":"[Lemma 16 of arXiv:2512.19517, 'Spiking and Resetting'] There exists a constant $C>0$ such that for any $\alpha \in (0,1/2)$ and $x\in (0,1)$, the following holds
\begin{equation}

\begin{split}
U^\varepsilon(x) &= -\frac{1}{h(0)} \log \varepsilon +  \frac{1}{h(0)}  \log \Big(\frac{h(0)}{f(0)} \Big) +  \int_{0}^x \left[ \frac{1}{y h(y)} -\frac{1}{h(0)y} \right] \, dy  +  \frac{1}{h(0)} \log x \\
& + R_{U^\varepsilon} (x) 
\end{split}
\end{equation}
where 
\begin{equation}

\begin{split}
\vert R_{U^\varepsilon} (x) \vert \le C \big[ \varepsilon^{1/2 - \alpha}/ {\mathfrak h}(x) + \varepsilon^{2\alpha}   \big] \ .
\end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.305806+00:00","domain":"probability theory","id":"claim_c8da7ce496a22cf76ec6b175f302ed0f0f33d2155245c1970cc82b1dff901e0e","kind":"concept","schema_version":1,"statement":"[Prop 68 (Controlling the error terms) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $\mathcal E^j_N, \mathcal V^j_N$ $(1\le j \le 2)$ be as in Proposition \ref{4.3}. Let $q\ge 1$ be an even integer, and let $T>0$. Then there exists $C>0$ and a function $f:I\to \mathbb R_+$ such that $|f(x)| \leq F(|x|)$ where $F:[0,\infty)\to[0,\infty)$ is decreasing and 
of exponential decay at infinity, such that uniformly over all $N\ge 1$ and $s,t\in [0,T]\cap (N^{-1}\mathbb Z_{\ge 0})$ we have the following:
    \begin{enumerate}\item \hyperref[eq:regimeA]{Regime A:} In the case where $|  \varsigma_N|=O(N^{-1/2})$ we have the bound 
    \begin{align*}
        \sum_{j=1,2}\mathbb E[ |\mathcal V^j_N(t,\phi)-\mathcal V^j_N(s,\phi)|^q]^{1/q} &\leq C N^{-1/2}\|\phi\|_{C^{p+2}(\mathbb R^d)}^2 \bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).
\end{align*}
The integer $p$ appearing on the right side is the one from Assumption \ref{a1}.
\item \hyperref[eq:regimeB]{Regime B:} In the case where $N^{-1/2} \ll  |  \varsigma_N| \ll  \psi_N(p,d)N^{-1}$ we have \begin{align*}\sum_{j=1,2}\mathbb E[ |\mathcal E^j_N(t,\phi)-\mathcal E^j_N(s,\phi)|^q]^{1/q}& \leq C |  \varsigma_N|^{1/2} \|\phi\|_{C^3(\mathbb R^d)}^2\bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).
    \end{align*}
    \item \hyperref[eq:regimeC]{Regime C:} In the case where $d=2$ and  $ (\log N)^{1/2p}   \varsigma_N\to   {\boldsymbol v}\ne 0 $, we have 
    \begin{align*}\sum_{j=1,2}\mathbb E[ |\mathcal E^j_N(t,\phi)-\mathcal E^j_N(s,\phi)|^q]^{1/q}& \leq C |  \varsigma_N|^{1/2} \|\phi\|_{C^3(\mathbb R^d)}^2\bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).
    \end{align*}
    \item \hyperref[eq:regimeD]{Regime D:} In the case where $d\ge 3$ and $  \varsigma_N  \to   {\boldsymbol v}\ne 0$ we have that $$\mathbb E[ |\mathcal E^1_N(t,\phi)-\mathcal E^1_N(s,\phi)|^q]^{1/q} \leq C|\varsigma_N-  {\boldsymbol v}| \|\phi\|_{C^3(\mathbb R^d)}^2\bigg(\mathbb E[ |Q^f_N(t,\ind_\mathbb R)-Q^f_N(s,\ind_\mathbb R)|^q]^{1/q}+|t-s|\bigg).$$
    \end{enumerate}
 Note that the second and third cases have the same error bounds; however, we distinguish these two cases because they will need to be analyzed separately later on. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:26:26.750466+00:00","domain":"probability theory","id":"claim_c8da8d569791f637a85a44ab70268adc1b3b328bb8cbb36f72dce4abf147178f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:RBM-propagator of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The propagator satisfies the following identities.
\begin{enumerate}[label=\textup{(\roman*)},
leftmargin=*]
\item \textup{(Splitting.)}
For $i < p < j$,
\begin{equation}
\partial_{a_p} [B_{\mathbf{a},\mathbf{n}}]_{ij}(z, w)
= [B_{\mathbf{a},\mathbf{n}}]_{ip}(z, a_p)[B_{\mathbf{a},\mathbf{n}}]_{pj}(a_p, w).
\end{equation}

\item \textup{(Flux conservation.)}
For $i < j$,
\begin{equation}
\Bigl(\partial_z + \partial_w
+ \sum_{i < p < j} \partial_{a_p}\Bigr)
[B_{\mathbf{a},\mathbf{n}}]_{ij}(z, w) = 0.
\end{equation}

\item The propagator depends on the particle labels
$\mathbf{n}$ only through differences
$n_{\ell'} - n_\ell$, and is $t$-independent.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.038935+00:00","domain":"probability theory","id":"claim_c8dc2723722f8eb90a792cd62b2f10e82ba8fc054d3a2218d543571dc8648f76","kind":"concept","schema_version":1,"statement":"[Lemma 13 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Under the assumptions of the theorem
