\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.257850+00:00","domain":"probability theory","id":"claim_c94affe4b983057176965e625642478308ed136392983ea5993f82f077a10e30","kind":"concept","schema_version":1,"statement":"[Proposition 9 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} and $\eta_{0} = \frac{1}{2}$ be valid. Further, suppose that either
\begin{equation*}
c_{1,2} = c_{2,1} = c_{2,2} = g_{1,1} = 0
\end{equation*}
or both~\eqref{a.2} and one of the following four scenarios hold:
\begin{enumerate}[(i)]
\item $\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) \geq \beta + \beta_{1}^{+} + (2c_{1,2} + c_{2,1})N  + c_{2,2}N^{2}$ and $g_{1,1}g_{1,2}\geq 0$.

\item $-\frac{3}{2}g_{1,1}g_{1,2} \geq 4(c_{1,2} + c_{2,1} + c_{2,2}N + \frac{1}{2}g_{1,1}^{2})\sqrt{N}$.

\item $\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) \leq \beta - \beta_{1}^{-} -(\frac{3}{2}g_{1,1}g_{1,2} + (c_{2,1} + g_{1,1}^{2})\sqrt{N} + c_{2,2}N^{\frac{3}{2}})\sqrt{N}$.

\item If $g_{1,1} > 0$, then
\begin{align*}
\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) &\geq \beta + \beta_{1}^{+} + (2c_{1,2} + c_{2,1})N + c_{2,2}N^{2}\\
&\quad + \frac{1}{2}\bigg(\frac{3}{4}\bigg)^{2}\frac{g_{1,1}^{2}g_{1,2}^{2}}{\frac{1}{2}g_{1,1}^{2} + c_{1,2} + c_{2,1} + c_{2,2}N}.
\end{align*}
\end{enumerate}
 If there are $u_{1},u_{2},u_{3}\in\R$ satisfying~\eqref{eq:extinction in the epidemic models 4},
\begin{equation}
\liminf_{t\uparrow\infty} g_{1,1}(t)g_{1,2}(t) \geq u_{2}\quad\text{and}\quad \limsup_{t\uparrow\infty} c_{1,2}(t) - \frac{1}{2}g_{1,1}(t)^{2} \leq u_{3},
\end{equation}
then any positive solution $I$ to~\eqref{eq:SIS epidemic model} becomes exponentially extinct if $\mu_{\infty} + \gamma_{\infty} > 0$ and
\begin{equation}
(u_{1} + u_{3}N_{\infty} - u_{2}N^{\frac{1}{2}})N_{\infty} < \mu_{\infty} + \gamma_{\infty}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

