{"assumptions":[],"created_at":"2026-10-27T18:51:26.589949+00:00","domain":"probability theory","id":"claim_c98d609968f199bc2d85e24386ea4ea8dc697d9c1898d49c504d043c41f69228","kind":"lemma","schema_version":1,"statement":"[Lemma lem:codiff-finite of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $X = I(f_1)$, $Y = I(f_2)$ be jointly S$\alpha$S with
$\alpha \in (1,2]$ and $f_1, f_2 \in L^\alpha(E,m)$. Then:
\begin{enumerate}[label=(\roman*)]
\item \textbf{Finiteness and bound.}
  \begin{equation}

  0 \leq \tau(X,Y) \leq 2\min\!\bigl(\|X\|_\alpha^\alpha,
  \|Y\|_\alpha^\alpha\bigr) < \infty.
  \end{equation}
\item \textbf{Symmetry.} $\tau(X,Y) = \tau(Y,X)$.
\item \textbf{Independence.} $X \perp Y \Rightarrow \tau(X,Y) = 0$.
\item \textbf{Gaussian case.} For $\alpha = 2$:
  $\tau(X,Y) = \mathrm{Cov}(X,Y)$.
\item \textbf{Integral formula.}
  \begin{equation}

  \tau(X,Y)
  = \int_E\!\bigl[|f_1|^\alpha + |f_2|^\alpha
    - |f_1 - f_2|^\alpha\bigr]\,dm.
  \end{equation}
\end{enumerate}","status":"unverified"}

