\begin{equation}
 \forall x \in (\alpha_h,\beta_h) \qquad \theta_{h,h}\big(F_h(x^+) + F_h(x^-)\big) + \sum_{g \neq h} 2\theta_{h,g} F_g(x) = -\frac{E_h(x^+) - E_h(x^-)}{\sigma_h(x^+)}.
\end{equation}

Conversely, assume that $\boldsymbol{F}(z)$ is a tame solution of \eqref{RHPeq}, that both $\boldsymbol{F}$ and $\boldsymbol{E}/\sigma$ have tameness exponent $1$ and that for each $h \in [H]$ the function $F_h(z)$ is holomorphic in $\amsmathbb{C}\setminus [\alpha_h,\beta_h]$ and satisfies $F_h(z) \sim \frac{\kappa_h}{z}$ as $z \rightarrow \infty$. Then $\boldsymbol{F}$ solves the master problem, \textit{i.e.} $F_h(z) = \Upsilon_h[\boldsymbol{E}\,;\,\boldsymbol{\kappa}](z)$ for any $h \in [H]$.","status":"unverified"}

