{"assumptions":[],"created_at":"2026-10-28T02:04:40.964677+00:00","domain":"probability theory","id":"claim_ca3b9bab0cbe0017d290057d862b3e899c111f43c8db86d35f70745dd159bb64","kind":"concept","schema_version":1,"statement":"[Lemma L:Gronwall of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Let $g(\cdot)$ be a nonnegative and monotone function on $[0,\infty)$ that
  decreases to $0$ as $t\to\infty$, and such that $g(0)<\infty$. Let $k(\cdot)$
  be a nonnegative and integrable function on $[0,\infty)$ and define
  \begin{align}
    h(t) \coloneqq \int_t^{\infty} k (s) \ensuremath{\mathrm{d}} s.
  \end{align}
  Then, we have:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*)}]
    \setlength\itemsep{.1in}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_0^t g \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le g(0) h \left(\frac{t}{2^{n + 1}}\right) + h(0) g \left(\frac{t}{2^{n + 1}}\right).
      \end{align}
      In particular, when $g = h$ as defined in (equation E:def-gnr-H of the paper), the above
      inequality~(equation E:g*h of the paper) reduces to
      \begin{align}
        \int_0^t h \left(\frac{t - s}{2^n}\right) k(s) \ensuremath{\mathrm{d}} s
        \le 2 h(0) h \left(\frac{t}{2^{n + 1}}\right).
      \end{align}

    \item For any nonnegative integer $n$ and $t\ge 0$, it
      holds that
      \begin{align}
        \int_{[0, t]^{n}_<}
            & \ensuremath{\mathrm{d}} u_n \cdots \ensuremath{\mathrm{d}} u_1\:  g \left(t - u_n \right) \prod_{i = 1}^n k(u_{i} - u_{i - 1} ) \nonumber \\
        \le & \left( 2^{n} - 1\right) g(0) h(0)^{n-1} h \left(\frac{t}{2^{n}}\right) + h(0)^n g \left(\frac{t}{2^{n}}\right),
      \end{align}
      where $[0, t]_<^{n} \coloneqq \left\{(s_1,\dots, s_n) \in [0,t]^n; 0 <
      s_1< \dots < s_n <t\right\}$ and we have used the convention that $u_0
      \equiv 0$.

    \item Let $f$ be a function on $[0,\infty)$ such that
      \begin{align*}
        f(t) \le g(t) + \beta \int_{0}^t f(t - s) k(s) \ensuremath{\mathrm{d}} s, \quad \text{for all $t\ge 0$ with $\beta>0$}.
      \end{align*}
      Then, whenever $\beta < [2 h(0)]^{-1}$, the following convergence is true,
      \begin{align}
        \lim_{t\to \infty} f(t) = 0.
      \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:52:51.770225+00:00","domain":"probability theory","id":"claim_ca474e81d459a74d4eefba15bad439c6f05f6e054df81dd992ea07577c8a3e1f","kind":"concept","schema_version":1,"statement":"[Cor probability of exploration processes of arXiv:2605.03151, 'Giants through Higher-Order paths in Random Simplicial Complexes'] Let $X_n \sim \MRSC_d(n; \bm{p})$ with the assumptions ((eq: 1.3.1 assumption 1 of the paper)) and ((eq: 1.3.2 assumption 2 of the paper)). Then, conditional on $\mathcal{X}_{k-1}$, the number of new forward $(d-1)$-simplices at each step $k$, denoted by $F_k$, satisfies
\[  \tag{3.2.27}
