{"assumptions":[],"created_at":"2026-10-27T21:41:19.333700+00:00","domain":"probability theory","id":"claim_ca59a73ccba350bbec514f94cb7dfc3e72b4dca63d203e3769c6ab436f8c743f","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Let $U\subset \BC$ be a domain, let $z \in U$, and let $(U_n)_{n\ge 0}$ be a sequence of domains in $\BC$ containing $z$. The sequence $(U_n)_{n\ge 0}$ converges in the Carath\'eodory sense toward $U$ with respect to $z$ if: 
	\begin{itemize}
		\item For every compact set $K\subset U$, we have $K\subset U_n$ for all $n$ large enough;
		\item For every connected open set $V\ni z$, if $V \subset U_n$ for infinitely many $n\ge 0$, then $V \subset U$.
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.580289+00:00","domain":"probability theory","id":"claim_ca5cfa17d8c70ca9efc39078e92a7b7fe24652188a166c05ce54ca60afb1b69d","kind":"concept","schema_version":1,"statement":"[Lemma 30 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)\cap \Leb^{\infty}(\Rbb^n,\gamma_n)$, and $1\leq q\leq p\leq 2$,
\begin{equation}
\begin{aligned}
    &\left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq M(p)^k\Vop^{k}(f) \\
    &\cdot\left[1+ \frac{q}{2k(2-q)}\max\left\{\ln^+\left(\frac{\Vop^k(f)}{\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^2}\right),\, \ln^+\left(\frac{\Vop^k(f)}{\sum_{|\kappa|=k} \left\|\Dop^\kappa f\right\|_{\Leb^q}^2}\right)\right\}\right]^\frac{kp}{2},
\end{aligned}
\end{equation}
and further for all $\kappa\in \Nbb^n$ with $|\kappa|=k$,
\begin{equation}
    \left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\Dop^\kappa f\right\|_{\Leb^p}^{p} \geq M(p)^{k} \Vop^\kappa(f) \left[1+\frac{q}{2k(2-q)} \ln^{+}\left(\frac{\Vop^\kappa(f)}{\left\|\Dop^\kappa f\right\|_{\Leb^q}^{2}}\right)\right]^\frac{kp}{2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:36.722449+00:00","domain":"probability theory","id":"claim_ca5f667be54b67b21112c578cf4a7993ed3ef7b654bd69c6119929d7c5228b2c","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2511.13559, 'Asymptotic analysis of rare events in high dimensions'] Let $N\geq1$, $\sup_{u\in D}|g(u)|\leq1$, and suppose Assumptions~\ref{assume1},~\ref{assume:global2} are satisfied. Suppose there is $R \geq 12/\cmin + 2(1+2N)(\log\la)/d$ and constants $\CR$, $C_{\g,\ell}$, $\ell=0,\dots,2N$, $C_{\z,\ell}$, $\ell=0,\dots,2N+2$ 
such that $\g\in C^{2N}(\us(R\e)\times[0,(R\e)^2))$, $\z\in C^{2N+2}(\us(R\e)\times[0,(R\e)^2))$, and
\begingroup
\addtolength{\jot}{0.3em}
\begin{align}
&\e\leq s,\qquad R\e\leq\min(1,\rho_0,2\rho_1, 2/\delta_2(\rho_1)),\\
&R\e\leq1/(2C_{\z,0}+2C_{\z,1}),\qquad R^4d^2/\la\leq \CR,\\
\begin{split}
&\max_{j=0,\dots,N}\g_{0,j}(R\e,(R\e)^2)\leq C_{\g,0}, \\
&\max_{j=0,\dots,\lfloor N-\frac\ell2\rfloor}\g_{\ell,j}(R\e,0)\leq C_{\g,\ell} \,d^{\lceil\frac\ell2\rceil},\quad\ell=1,\dots,2N,
\end{split}\\
\begin{split}
&\omega_{0,2}(R\e,R\e)\vee \max_{j=3,\dots,N+1}\omega_{0,j}(R\e,(R\e)^2)\leq C_{\z,0},\\
&\max_{j=j_\ell,\dots,\lfloor N+1-\frac\ell2\rfloor}\omega_{\ell,j}(R\e,0)\leq C_{\z,\ell} \,d^{(\lceil\frac\ell2\rceil-2)_+},\quad\ell=1,\dots,2N+2.
\end{split}
\end{align}
\endgroup
Here, $j_1=j_2=1$, $j_\ell=0$ for $\ell\geq3$, and $(\cdot)_+=\max(\cdot, 0)$.  Then
\bs
\int_{D}g(u)e^{-\la z(u)}\dd u =  \frac{(2\pi/\la)^{d/2}e^{-\la z(0_{d+1})}}{\la(\det H)^{1/2}}\left(g(0_{d+1})+\sum_{m=1}^{N-1}a_m\left(\frac{d^2}{\la}\right)^{m}+ \Rem_N\right),
\es where
\begin{align}

\max_{m=1,\dots,N-1}|a_m|&\leq C_{\g,\z,N},\qquad |\Rem_N|\leq C_{\g,\z,N,R} (d^2/\la)^{N}.
\end{align}
The constant $C_{\g,\z,N}$ depends on $N$, $C_{\g,\ell}$, $\ell=0,\dots,2N$, and $C_{\z,\ell}$, $\ell=0,\dots,2N+2$. The constant $C_{\g,\z,N,R}$ depends on these same constants and also on $\CR$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.279480+00:00","domain":"probability theory","id":"claim_ca6e423673a6e1c872babd5141c185943e5c0cd900c0a6c40518cf4474c9985a","kind":"definition","schema_version":1,"statement":"[Defi eq:assumptioninticonditionK of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Let $R_{0} \in [0,R_{\max}]$ be a random variable. Let $(\nu^{K}_{0})_{K \geq 1}$ be a sequence of random variables in $\mathcal{M}_{P}(\mathbb{R}^{*}_{+})$, such that
    \begin{align}
    \underset{K \geq 1}{\mathrm{sup}} \bigg( \dfrac{1}{K} \hspace{0.1 cm} \mathbb{E}\left(\langle \nu^{K}_{0},1+\mathrm{Id}+\omega \rangle\right) \bigg) < + \infty.

    \end{align}
We use the Poisson point measures $\mathcal{N}$ and $\mathcal{N}'$ of Section~(sec:construction of the paper), independent from $R_{0}$ and $(\nu^{K}_{0})_{K \geq 1}$. For every $K \geq 1$, the renormalized process $(\mu^{K}_{t},R^{K}_{t})_{t \geq 0}$ with initial condition $(\mu^{K}_{0},R_{0})$, is given for every $t \geq 0$ by $\mu^{K}_{t} := \dfrac{\nu^{K}_{t}}{K}$ and

\begin{align*}
    (\nu^{K}_{t},R^{K}_{t}) = &  \hspace{0.1 cm}X^{K}_{t}(\nu^{K}_{0},R_{0})  \\  & +  \displaystyle{\int_{0}^{t}\int_{\mathcal{U} \times \mathbb{R}^{*}_{+} } \mathbb{1}_{\{u \in V^{K}_{s-} \}} \mathbb{1}_{\{h \leq b\left(\xi^{u,K}_{s-}\right)\}}}  [ X^{K}_{t-s}(\nu^{K}_{s-} + \delta_{x_{0}} + \delta_{\xi^{u,K}_{s-}-x_{0}} -\delta_{\xi^{u,K}_{s-}},R^{K}_{s})  \\
    &  \hspace{3 cm} - X^{K}_{t-s}(\nu^{K}_{s-},R^{K}_{s}) ] \mathcal{N}(\mathrm{d}s,\mathrm{d}u,\mathrm{d}h)  \\
     & + 
    \displaystyle{\int_{0}^{t}\int_{\mathcal{U} \times \mathbb{R}^{*}_{+} } \mathbb{1}_{\{ u \in V^{K}_{s-}\}} \mathbb{1}_{\{h \leq d\left(\xi^{u,K}_{s-}\right)\}} [X^{K}_{t-s}(\nu^{K}_{s-} - \delta_{\xi^{u,K}_{s-}},R^{K}_{s})}  \\ 
    & \hspace{3 cm} - X^{K}_{t-s}(\nu^{K}_{s-},R^{K}_{s}) ] \mathcal{N}'(\mathrm{d}s,\mathrm{d}u,\mathrm{d}h), 
\end{align*}
where for all $t \geq 0$, $V^{K}_{t}$ is the set containing alive individuals at time $t$, and $\xi^{u,K}_{t}$ are individual energies, defined and actualized over time with the same conventions as in Section~(sec:construction of the paper), simply replacing the flow $X$ by $X^{K}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:41:03.309814+00:00","domain":"probability theory","id":"claim_ca737046f4013ac6931c1720047c41a961b7ed8b9824a2cd573faced6b8aa7e1","kind":"concept","schema_version":1,"statement":"[Theorem t:covindfn of arXiv:2411.08848, 'Stationary random measures: Covariance asymptotics, variance bounds and central limit theo'] Let ${\mathcal X}$ be a stationary random measure whose truncated correlation measure ${\bf K}$ has finite total variation. Assume that $A$ and $B$ are bounded open sets with $C^1$-smooth boundaries.  Let ${\mathcal X}_L$ be the scaled random measure defined by ${\mathcal X}_L(A) := {\mathcal X}(LA)$,  $L \geq 1$.  Then

\begin{enumerate}
\item $L^{-d}\mathrm{Cov}({\mathcal X}_L(A),{\mathcal X}_L(B)) \to Q_0^{{\bf K}}(f,g) = (\lambda_D + \int {\bf K} ) \, |A \cap B|, $ where $| \cdot |$ is the Lebesgue measure. 
\item If $\lambda_D + \int {\bf K} = 0$ and further $\int |z||{\bf K}|(\mathrm{d} z)<\infty$, then it holds that

\begin{equation}

L^{-d+1}\mathrm{Cov}({\mathcal X}_L(A),{\mathcal X}_L(B))  \to  -\frac12 \int_{\partial A\cap \partial B} \varepsilon(x) \left[\int |z\cdot N_A(x)| \ {\bf K}(\mathrm{d} z) \, \right] \, \sigma_A(\mathrm{d} x),
\end{equation}

where $N_A(x)$ is the exterior normal to $A$ at $x$ and $\sigma_A$ is the surface area measure of $\partial A$. Further, $\varepsilon(x) \in \{+1,0,-1\}$ is defined as follows: $\varepsilon(x) = +1$ (resp. $-1$) if $N_A(x)$ is the exterior (resp. interior) normal to $B$ at $x$, and $0$ otherwise. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

