{"assumptions":[],"created_at":"2026-10-26T20:46:26.257692+00:00","domain":"probability theory","id":"claim_ca9e0ef8b1b59faf6e7c52ab632ac02f02848bf7220f55fbd588c33e7238b299","kind":"lemma","schema_version":1,"statement":"[Lem 67 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] \quad\par
\begin{itemize}
  \item [$\rm{(i)}$]Let $A,\;B$ be closed subsets of a metric space $(M,d)$.
Suppose that $A$ is unbounded and $B$ has at least two distinct elements.
Taking $a\in A,\;b\in B$, set $A^{(r)}=A\cap \overline{B(a,r)},\;B^{(r)}=B\cap \overline{B(b,r)}$ for $r>0$.
Then there exists an $\tilde{r}_1>0$ such that there exist
$a_0^{r},a_1^{r}\in A^{(r)},\;b_0^{r},b_1^{r}\in B^{(r)}$ for any $r>\tilde{r}_1$ satisfying
the following:
\begin{itemize}
  \item $d(a_0^{r},b_0^{r}),\;d(a_1^{r},b_1^{r})\leq d_{\rm{H}}(A^{(r)},B^{(r)})$;
  \item $\displaystyle  \inf_{r>\tilde{r}_1}d(a_0^{r},a_1^{r})\wedge d(b_0^{r},b_1^{r})>0$;
  \item the set $\{a_0^r,a_1^r,b_0^r,b_1^r:r>\tilde{r}_1 \}$ is bounded.
\end{itemize}
\item[$\rm{(ii)}$]Suppose Assumption 1, and we regard $F,\;F_n,\;n\in\N$ as subsets of a common $\bcm$ space $(M,d)$.
Then there exists an $r_1>0$ such that, for any $r>r_1$ and $n\in\N$ there exist
$a_0^{n,r},a_1^{n,r}\in F^{(r)},\;b_0^{n,r},b_1^{n,r}\in F_n^{(r)}$ satisfying
the following:
\begin{itemize}
  \item $d(a_0^{n,r},b_0^{n,r}),\;d(a_1^{n,r},b_1^{n,r})\leq d_{\rm{H}}(F^{(r)},F_n^{(r)})$;
  \item $\displaystyle \delta:= \inf_{\substack{n\in\N\\r>r_1}}d(a_0^{n,r},a_1^{n,r})\wedge d(b_0^{n,r},b_1^{n,r})>0$;
  \item there exists an $r_{\ast}$ such that the set $\{a_0^{n,r},a_1^{n,r},b_0^{n,r},b_1^{n,r}:r>r_1,n\in\N \}$ is a subset of $B(\rho,r_{\ast})$ and $B(\rho_n,r_{\ast}),\;n\in\N$.
\end{itemize}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.484909+00:00","domain":"probability theory","id":"claim_caa34fe526dea542de4be572cfaed37085d61647a293d717077a24e1c2a3c08f","kind":"concept","schema_version":1,"statement":"[Lemma 62 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $N\geq 0$. Let $z\in D\setminus A_{0,b}$ such that $2\pi V_{A_{0,b}}<\vert\log\varepsilon\vert$.
