{"assumptions":[],"created_at":"2026-10-27T13:52:23.590932+00:00","domain":"probability theory","id":"claim_cbac56665000452be75ce805cdb4f03f299d0cccfff69c235b653073ba736122","kind":"lemma","schema_version":1,"statement":"[Lemma lem:ergodic_characterization of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] $B$ is 
		\begin{itemize}
			\item ergodic if
			\begin{equation*}
				\lim_{r\to +\infty}\frac{1}{\Vol{\mathsf{B}_{r}}}\int_{\mathsf{B}_{r}}\@ifnextchar[{\@withe}{\@withoute}{f(B)\overline{g(\theta_{t}B)}}\, \mathrm{d}t=\@ifnextchar[{\@withe}{\@withoute}{f(B)}\overline{\@ifnextchar[{\@withe}{\@withoute}{g(B)}},
			\end{equation*}
			\item weakly-mixing if
			\begin{equation*}
				\lim_{r\to +\infty}\frac{1}{\Vol{\mathsf{B}_{r}}}\int_{\mathsf{B}_{r}}\left|\,\@ifnextchar[{\@withe}{\@withoute}{f(B)\overline{g(\theta_{t}B)}}-\@ifnextchar[{\@withe}{\@withoute}{f(B)}\overline{\@ifnextchar[{\@withe}{\@withoute}{g(B)}}\,\right|^{2}\, \mathrm{d}s=0,
			\end{equation*}
			\item strong-mixing if
			\begin{equation*}
				\lim_{\|t\|\to +\infty}\@ifnextchar[{\@withe}{\@withoute}{f(B)\overline{g(\theta_{t}B)}}=\@ifnextchar[{\@withe}{\@withoute}{f(B)}\overline{\@ifnextchar[{\@withe}{\@withoute}{g(B)}}
			\end{equation*}
		\end{itemize}
		for any $f,g$ of the forms 
		\begin{equation}
			f(B)=\exp{i\sum_{j=1}^{n}a_{j}B_{t_{j}}}, \quad g(B)=\exp{i\sum_{j=1}^{n}b_{j}B_{t_{j}}}
		\end{equation} 
		with $a_{j}, b_{j} \in \mathbb{R}$ and $ t_{j} \in \mathbb{R}^{d}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.061733+00:00","domain":"probability theory","id":"claim_cbafc16b982f3dba3153ad3150465970fda46865445fc59acae33ad3f28f89dd","kind":"concept","schema_version":1,"statement":"[Thm 7 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta \subseteq \mathbb{R}^d \times \mathbb{S}_+^d \times \mathcal{L}$ be closed, convex, and satisfy Assumptions~\ref{B} and~\ref{J}. Moreover, let the cost function $\ell$ satisfy Assumption~\ref{L}. Then for every $\overline{\mathbb{F}}$-stopping time $\overline{\tau}$ taking values in $[t,1]$ and all $(b,c,v)\in\mathbb{R}^d\times\mathbb{R}^{d^2}\times\mathbb{R}^{\mathbb{N}}$, we have
\begin{equation}
\lambda(t,x)=\inf_{\overline{\mathbb{P}}\in\overline{\mathfrak{P}}_{\Theta}^{t,x,b,c,v}}\mathbb{E}^{\overline{\mathbb{P}}}
\Bigl[\int_{t}^{\overline{\tau}} \overline{\ell}(s,\overline{X}_s,\overline{b}_s,\overline{c}_s,\overline{v}_s)\,\mathrm{d}s+\lambda(\overline{\tau},\overline{X}_{\overline{\tau}})\Bigr].
