{"assumptions":[],"created_at":"2026-10-26T19:20:15.487183+00:00","domain":"probability theory","id":"claim_cbbcbf2a1186f62da0ab61f7927d5bff3bafeb12b7ba600f28e0bd2719a710c2","kind":"concept","schema_version":1,"statement":"[Conj 89 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $n\geq 1$.
For $\varepsilon>0$, consider the family of random variables
\begin{displaymath}
(A, (Z_{j,\varepsilon},[\Gamma_{Z_{j,\varepsilon}}])_{1\leq j\leq n}).
\end{displaymath}
As $\varepsilon\to 0$, this family converges in law towards
\begin{displaymath}
(A,(Z_{j},[\Gamma_{j}])_{1\leq j\leq n}),
\end{displaymath}
with the following properties.
\begin{itemize}
\item $A$ is the same FPS as previously.
\item $(Z_{j})_{1\leq j\leq n}$ are random points on $A$,
sampled, conditionally on $A$, in an i.i.d. way according to the probability measure
\begin{displaymath}
\dfrac{\nu_{A}}{\nu_{A}(A)},
\end{displaymath}
where $\nu_{A}$ is the FPS measure \eqref{Eq nu a Mink non norm}.
\item The family of equivalence classes of loops
$([\Gamma_{j}])_{1\leq j\leq n}$
is \textbf{independent} from
$(A,(Z_{j})_{1\leq j\leq n})$,
with an i.i.d. distribution according to the measure
$\hat{\mu}^{\rm loop}_{\text{SLE}_{4}}$.
\end{itemize} (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.247129+00:00","domain":"probability theory","id":"claim_cbbd9a683ddbd6350eca6cd51f27f77b6b9719d8a7935f032418affb188490d5","kind":"concept","schema_version":1,"statement":"[Lemma eq:I_n asymp of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Assume $\alpha$, $\nu$, and $(j_n)_{n\in{\mathbb N}}$ satisfy the assumptions in Theorem (thm:1 of the paper). Then for every $t\in(1-\epsilon,1+\epsilon)$, 
 we have
\begin{equation}
I_{n,j_n}(t)\sim \alpha \Gamma(j_n)\nu\pp{\frac n{j_n}}t^\alpha.
\end{equation}
In particular, 
\begin{equation}
{\mathbb E} \wt C_{j_n}(nt) =\frac{I_{n,j_n}(t)}{\Gamma(j_n+1)} \sim \alpha t^\alpha \frac1{j_n}\nu\pp{\frac n{j_n}} = t^\alpha\sigma_{n,j_n}^2.
\end{equation}
Moreover, we have local uniform convergence in $t$ in the following sense:
\begin{align}
\lim_{n\to\infty}\sup_{t\in[1-\epsilon',1+\epsilon']}\abs{\frac{I_{n,j_n}(t)}{\alpha\Gamma(j_n)\nu(n/j_n) t^\alpha} - 1} = 0, \nonumber\\
\lim_{n\to\infty}\sup_{t\in[1-\epsilon',1+\epsilon']}\abs{\frac{{\mathbb E}\wt C_{j_n}(nt)}{\sigma_{n,j_n}^2 t^\alpha} - 1} = 0, 
\end{align}
for all $\epsilon'\in(0,\epsilon)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.410016+00:00","domain":"probability theory","id":"claim_cbbee4045db153ee3dfed6d1e363ce9a2b6175ecd918e300197cace56639ca15","kind":"concept","schema_version":1,"statement":"[Proposition 11 of arXiv:2604.07207, 'Mixing times of step-reinforced random walks'] For any $\alpha \in (0,1)$, any $n\geq k\geq 1$ and $\varepsilon>0$, one has
\begin{equation}

     \PP\left(  \left|\frac{N_k(n)}{n}  - \theta_k\right| \geq  \varepsilon\right) \leq C_1e^{-C_2 n}, 
  \end{equation}
where $C_1=C_1(\alpha,\varepsilon,k)$ and $C_2=C_2(\alpha,\varepsilon,k)$ are positive constants. Moreover, for any $\alpha \in [0,1)$ and $n\geq 1$, one has
    \begin{equation}

       \PP\left(I(n) \leq  \frac{(1-\alpha)n}{8}\right) \leq 5e^{-\frac{3(1-\alpha)n}{280}}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.257767+00:00","domain":"probability theory","id":"claim_cbbff55f68ef57baa3a59fcea03b2ff32da0d9fb97b0d14aab219e7acb49e60b","kind":"definition","schema_version":1,"statement":"[Dfn 68 (Real tree coded by a function, {\cite[Section 3) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {abraham2013note}}]
  Let $f:[0,\infty)\to [0,\infty)$ be a compactly supported continuous function and set 
  \[ \sigma_f=\sup\{t>0:f(t)>0\}<\infty.\]
  Define a  semi-metric $\bar{d}^f$ on $[0,\sigma_f]$ by setting
  \begin{align*}
    \bar{d}^f(s,t):=f(t)+f(s)-2\inf_{u\in [s,t]}f(u),\qquad 0\le s\le t\le\sigma_f.
  \end{align*}
  We define a real tree coded by $f$ by 
  \begin{align*}
    T^f:=[0,\sigma_f]/\sim,
  \end{align*}
  where $s\sim t$ if and only if $\bar{d}^f(s,t)=0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:38:57.141628+00:00","domain":"probability theory","id":"claim_cbc033b426ae159fcee74d4c549be656d6506e9bdd4b8c5526f9b4aeca91a151","kind":"concept","schema_version":1,"statement":"[Lemma 1 of arXiv:2604.05910, '\textbf{Well-posedness and Hurst parameter estimation for fluid equations driven by fracti'] \begin{itemize}
      \item Let $s>\frac{d}{2}$. Then $H^{s}(\T^d)$ is an algebra, meaning that if $f\in H^s(\T^d)$ and $g\in H^s(\T^d)$ the product $fg\in H^s(\T^d)$ and
\begin{equation*}
\Vert fg\Vert _{H^{s}}\lesssim \Vert f\Vert _{H^{s}}\Vert g\Vert _{H^{s}}.
\end{equation*}
\item Let $s,r,t>0$ such that $s+r>t+\frac{d}{2}$. If $f\in H^s(\T^d)$, $g\in H^r(\T^d)$, then $fg\in H^t(\T^d)$ and 
\begin{align}
    \| fg\|_{H^t} \lesssim \|f\|_{H^s} \|g\|_{H^r}.
\end{align}
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

