{"assumptions":[],"created_at":"2026-10-26T19:36:44.552908+00:00","domain":"probability theory","id":"claim_cc9bb6131c2f18a3b782541a88aa008eb744bd807debf61b131ba1fb77ac812c","kind":"concept","schema_version":1,"statement":"[Prop 5 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-0Mass-Fast}, with corresponding initial data $(Q^i_0,P^i_0)$ for $i=1,2$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq 0$. 
    \begin{enumerate}[label=(\roman*)]
        \item 
        For any $t\geq 0$ 
        \begin{align}

            \E\Bigl[|P_t^{1}|^2\Bigr] \leq 
            \begin{dcases} C_1 \bigl(\eps +  e^{-\frac{C_2}{\eps}t} |P_0^{1}|^2\bigr) \  &\text{if $\alpha=0$}, \\
            C_3 \left(\eps +\eps |Q^1_0|^2  + (e^{-\frac{C_4}{\eps}t} + \eps)  |P^1_0|^2    \right) &\text{if $\alpha>0$},
             \end{dcases}
        \end{align}
        where the constants $C_1, C_2, C_3, C_4>0$ are independent of $\eps$ and $t$.

        \item Let $(\hat q_t,q_t,p_t)\in \R^{k}\times \R^{d-k} \times \R^{d-k}$ with initial data $(\hat q_0,q_0,p_0)=(Q^1_0,Q^2_0,P^2_0)$  evolve according to~\eqref{eq:0Mass-q1} and~\eqref{eq:limit-gen}. 
        We have for any $t\leq 0$
        \begin{align}
        \E\biggl[\Bigl|(Q^{1}_t,Q^{2}_t,P^{2}_t)^\top - (\hat q_t,q_t,p_t)^\top\Bigr|^2\biggr] \leq \begin{dcases}C_5 e^{C_6 t^2}\Bigl(\eps + 
        \bigl|P_0^{1}\bigr|^2  \Bigr) \ &\text{if $\alpha=0$}, \\
        C_7 e^{C_8 t^2}\Bigl(\eps t^2+\eps^2 t^2 \bigl|Q_0^{1}\bigr|^2 + |P^1_0|^2\Bigr)  &\text{if $\alpha>0$},
        \end{dcases}
        \end{align}
        where the constants $C_5,C_6, C_7,C_8>0$ are independent of $\eps>0$ and $t>0$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.757842+00:00","domain":"probability theory","id":"claim_cc9c54e892fd8bc42e5ebd4657fa126261c5a0bc1b4b8845b1934e98ba4ef4d0","kind":"lemma","schema_version":1,"statement":"[Lemma lem:frostman-green-smoothing of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $\mu$ be a finite positive Radon measure on $D$ satisfying, for some
$C_\mu<\infty$ and $\alpha>0$,
\begin{equation}
 \mu(B_D(z,r))\le C_\mu r^\alpha,
 \qquad z\in D,
 \quad 0<r\le1.
\end{equation}
Then $\mu(\{z\})=0$ for every $z\in D$.  For every $p>0$,
\begin{equation}
 L_p(\mu)
 :=\sup_{z\in D}\int_D
 \left(1+\log^+\frac1{|z-w|}\right)^p\mu(dw)<\infty.
\end{equation}
Moreover, for every compact $K\Subset D$,
\begin{equation}
 \sup_{\substack{z,z'\in K\\|z-z'|\le\delta}}
 \int_D|G_D(z,w)-G_D(z',w)|^2\,\mu(dw)
 \xrightarrow[\delta\downarrow0]{}0.
\end{equation}
In particular,
\begin{equation}
 \sup_{z\in D}\int_DG_D(z,w)^2\,\mu(dw)
 \le C_D^2L_2(\mu)<\infty.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.520285+00:00","domain":"probability theory","id":"claim_cca280fbe179e0b4234741f35e1313eed15e360d4a3bf444a3f2723610d7f8c3","kind":"concept","schema_version":1,"statement":"[Proposition prop:Markov of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $D\subset \mathbb{C}$ be a domain with $\partial D =  \partial^D\cup\partial^F$, $\partial^D\cap\partial^F=\emptyset$, and $U\subset D$ open. Let $h$ be the GFF on $D$ with  \textit{Dirichlet} (resp. free) \textit{boundary conditions} on $\partial^D$ (resp. $\partial^F$). Then we can write $h=h_1+h_2$ where: 
		\begin{enumerate}
			\item $h_1$ and $h_2$ are independent;
			\item $h_1$ is a GFF on $U$ with Dirichlet boundary condition on $\partial U\backslash \partial^F$ and free on $\partial U\cap \partial^F$;
			\item $h_2$ is the same as $h$ outside $U$ and harmonic inside $U$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

