\mu_{\Lambda_{M_2}\setminus\Lambda_{M_1}}^{\nu,\xi}(\mathtt{Con_2}(M_1,M_2))\le c_8\Big(\frac{M_2}{M_1}\Big)^{-\frac{1}{4}}.
\end{equation}","status":"unverified"}

