\right)^\frac{1}{q}.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.566748+00:00","domain":"probability theory","id":"claim_cd4868c0d132b6d6fd968b03e356b856fd0fcfb1e142a7b01aaf46f732ba1b00","kind":"lemma","schema_version":1,"statement":"[Lemma L:lmm_tu of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $0<s<t$, and $a,b,c \in \mathbb{R}$ satisfy the property that $-1 <a <0$, $b > c
    \geq -2$ and $a + b + c > -4$. Furthermore, suppose that $t - s \ll s$. Denote
  by
  \begin{align*}
    I  \coloneqq & \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_2 \int_{s}^{\theta_2} \ensuremath{\mathrm{d} } \theta_1  \int_0^s \ensuremath{\mathrm{d} } r_2 \int_{0 \vee (r_2 - \theta_2 + \theta_1)}^{r_2} \ensuremath{\mathrm{d} } r_1 \: (r_2-r_1)^{a}  (\theta_1 - r_1)^{b}  (\theta_2 - r_2)^{c} \shortintertext{and}
    I' \coloneqq & \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_2 \int_{s}^{t} \ensuremath{\mathrm{d} } \theta_1  \int_0^s \ensuremath{\mathrm{d} } r_2 \int_{0}^{(r_2 - \theta_2 + \theta_1) \wedge r_2} \ensuremath{\mathrm{d} } r_1 \: (r_2-r_1)^{a}  (\theta_1 - r_1)^{c} (\theta_2 - r_2)^{b}.
  \end{align*}
  Then, the following inequalities hold.
  \begin{align*}
    I \lesssim (t-s)^{(a + b + c + 4)\wedge 2} \quad  \text{and} \quad
    I' \lesssim \begin{dcases}
                  (t-s)^{(a + b + c + 4)\wedge 2}, & a + b + c \neq -2, \\
                  (t-s)^2 (1 + |\log (t-s)|),      & a + b + c = -2.
                \end{dcases}
  \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:02:34.840366+00:00","domain":"probability theory","id":"claim_cd48ca07e5c3a0675d84f162196b534b1d3f00399de6ace87a53fa1de0a48392","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2607.20714, 'High Minima of Gaussian Processes: Overshoots and Minimizer Locations'] Suppose that $\sigma_*^2>0$, and let $T$ be any measurable selection from
