		\item $Y$ is an $\mathcal{F}_t$-adapted, $d$-dimensional process such that $P$-a.s., for $i=1,...,m,$
		\begin{itemize}
			\item $Y_i(0)=0,$
			\item $Y_i$ is continuous and non-decreasing,
			\item  $\int_0^{t} \mathbf{1}_{ F_i } (W(s)) dY_i(s)=Y_i(t)$ for all $t \ge 0$. 
