		\Phi_n^{(1)}(u)=G_{r_1, T_1}\big(\underline v^{(1)}\big), \qquad		\Phi_n^{(2)}(u)=G_{r_2,T_2 }\big(\underline v^{(2)}\big), \qquad\Phi_n(u)=\big(\Phi_n^{(1)}(u),\Phi_n^{(2)}(u)\big).
