{"assumptions":[],"created_at":"2026-10-26T19:33:46.771487+00:00","domain":"probability theory","id":"claim_ce68c231114f66b98cd91ce2562227d472467204a9e1016860c49a7020fa8a82","kind":"definition","schema_version":1,"statement":"[Definition 47 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1)$, $c \in (1, q^{-1})$, and set
\begin{equation}
\begin{split}
&p_2 = \frac{q}{c-q}, \hspace{2mm} \sigmap = \sqrt{p_2(1+p_2)} = \frac{q^{1/2}c^{1/2}}{c-q}, \hspace{2mm} \bar{\kappa} = \frac{(c-q)^2}{(1-qc)^2} - 1 > 0.
\end{split}
\end{equation}
For $\kappa \in [0, \bar{\kappa})$ we also define
\begin{equation}
z_c(\kappa) = \frac{q + \sqrt{1+ \kappa}}{1 + q \sqrt{1+ \kappa}}, \hspace{2mm} h_1(\kappa) = \frac{2q\sqrt{1+\kappa}+ 2q^2 + q^2\kappa}{1-q^2} , \hspace{2mm} h_2(\kappa) = \kappa p_2 + \frac{q (c^2 - 2qc + 1)}{(c-q)(1-qc)}.
\end{equation}
Notice that by our parameter range, we have $q < 1 \leq z_c(\kappa) < c < q^{-1}$.

We also define for $z \in \mathbb{C} \setminus \{0, q , q^{-1}\}$ the functions
\begin{equation}
\begin{split}
& \SFb(z;\kappa) = (1+\kappa) \log(1 - q/z) - \log(1-qz) - h_1(\kappa)\log(z), \\ 
&\SFt(z;\kappa) = (1+\kappa)\log(1 - q/z) - \log(1-qz) - h_2(\kappa) \log(z),\\
&\bar{\SFb}(z;\kappa) = \SFb(z;\kappa) - \SFb(\zc(\kappa);\kappa), \hspace{2mm} \bar{\SFt}(z; \kappa) = \SFt(z;\kappa) - \SFt(c;\kappa), \\
&\GFt(z) = \log(1-q/z)- p_2 \log(z), \hspace{2mm} \bar{G}_2(z) = \GFt(z) - \GFt(c).
\end{split}
\end{equation}","status":"unverified"}

