    \mathcal{A}^{\theta}_{\delta,N} := \left\{ \xi_t(x) \in \{\zero,\one \}  \, \forall (x,t) \in \mathcal{I}^{\rho}_{\delta,N}\Big(\frac{1}{8}+\theta,\frac{7}{8}+\theta\Big)  \right\}
\end{equation*} satisfy for all $\delta>0$ 
\begin{equation}
\liminf_{N \rightarrow \infty}\Pex\big( \mathcal{A}^{\theta}_{\delta,N} \big)   \geq 1- \tilde{C} \exp(-\tilde{c} \delta^{-1} ) . 
