{"assumptions":[],"created_at":"2026-10-27T20:36:16.061559+00:00","domain":"probability theory","id":"claim_cf1ac626449dec1ef56568fe545423bb51fcbe68c7dd486612775360913990c6","kind":"theorem","schema_version":1,"statement":"[Proposition prop:convergence of the roots of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume:
\begin{enumerate}
\item[{\em (1)}] {the Cram\'er condition (equation cram of the paper) applies};
\item[{\em (2)}] for $\alpha\geqslant 0$, the limit $\ell_\alpha := \lim_{t\to \infty} k_\alpha(t)/t$ exists almost surely;
\item[{\em (3)}] there is a unique $\alpha_*\in(0,\overline{\alpha})$ such that $\ell_{\alpha_*}=0$.
\end{enumerate}
Let $\alpha(t)=\sup{{\left\{\alpha\geqslant 0: k_\alpha(t)=0\right\}}}$ denote the largest root of $\alpha\mapsto k_\alpha(t)$. Then
\[
\lim_{t\to \infty} \alpha(t) = \alpha_* \quad \text{almost surely.}\]
In addition, we have $\alpha_0\leqslant \alpha_*$, where $\alpha_0$ is the rough decay rate introduced in Proposition~(prop:estimation ruin probability for the collective model of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.957748+00:00","domain":"probability theory","id":"claim_cf1bfa466679863b1e7a01315caf5302b6a2665905163389810b1a47ee9f6eda","kind":"lemma","schema_version":1,"statement":"[Lemma 2 (Schatten ideal, interpolation, and tensor regrouping) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Let $U,V,U',V'$ be Hilbert spaces.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
 \item If $T\in\cL(U,V)\cap\Sch_2(U,V)$ and $2\le r<\infty$, then
 \begin{equation}
  \norm{T}_{\Sch_r}
  \le \norm{T}_{\rm op}^{1-2/r}\norm{T}_{\Sch_2}^{2/r}.
 \end{equation}
 \item If $A\in\cL(V,V')$, $B\in\cL(U',U)$, and $T\in\Sch_r(U,V)$, then
 \begin{equation}
  \norm{ATB}_{\Sch_r(U',V')}
  \le \norm{A}_{\rm op}\norm{T}_{\Sch_r(U,V)}\norm{B}_{\rm op}.
 \end{equation}
 \item The canonical regroupings of Hilbert tensor products, for instance
 $((\cA\otimes_2\cB)\otimes_2\cC)\simeq\cA\otimes_2\cB\otimes_2\cC$, are unitary.  Consequently Hilbert--Schmidt norms are unchanged by a mere reorientation of tensor legs.  Multiplication by unimodular factors on any frequency leg is also unitary and hence preserves every Schatten norm.
\end{enumerate}","status":"unverified"}

