defined by the formulae ($z$ is outside the integration contours)
\begin{equation*}

\begin{split}
\mathcal{K}_h[f](z) & = \frac{1}{\sigma(z)} \oint_{\gamma_h} \frac{\dd \zeta}{2\ii\pi} \,\frac{\sigma(\zeta)}{\zeta - z}\,\frac{f(\zeta)}{\theta_{h,h} \sqrt{(\zeta - \alpha_h)(\zeta - \beta_h)}}, \\
\mathcal{K}[\boldsymbol{f}](z) & = \sum_{h = 1}^H \mathcal{K}_h[f_h], \\
