where
${{L_p}}$ is a finite random variable and 
\begin{align*}
    y_p = \begin{cases}\hspace{1.7cm}{\frac{7-8p}{3}}\hspace{2.05cm},
    &{p \in \left(\frac{11}{16}, \frac{7}{8}\right)}, \smallskip \\{\frac{5p-4-\sqrt{-64p^3+161p^2-134p+37}}{2p-1}}, &{p \in \left(\frac{7}{8}, \frac{113+\sqrt{97}}{128}\right)}.\end{cases}
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:52:51.763065+00:00","domain":"probability theory","id":"claim_cf93c5dbb2e54f35e713b5fb20bb82094953bae2663b0c13eae98af33f03fdca","kind":"definition","schema_version":1,"statement":"[Definition Def:ms-dissipative-schurz of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let $\left\{X(t):t\in[0,\infty)] \subseteq D \subseteq \mathbb{R}^d \right\}$ be a solution of the SDE (equation eq:main_d of the paper) corresponding to initial data $X(0)\in D$ which is measurable with respect to $\mathcal{F}_0$. The SDE is called 
    \begin{enumerate}
    \item mean-square dissipative if  there exist $r,R>0$ such that     $$\limsup_{t\to\infty}\mathbb{E}\left[\|X(t)\|^2\right]<R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right]<r^2$;

    \item uniformly mean-square dissipative if  there exist $r,R>0$ such that $$\lim_{t\to\infty}\expect{\sup_{0\leq s \leq t}\|X(s)\|^2} <R^2$$
    whenever $\mathbb{E}\left[\|X(0)\|^2\right] < r^2$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.285665+00:00","domain":"probability theory","id":"claim_cf9b4d14b32b875e8e602a05497339f8d78af0e6f5b7f3b71f69382aff19afbd","kind":"definition","schema_version":1,"statement":"[Definition def:SUSY1eps of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\zeta\in\mathrm{Prefix}_2(u,q)$ for some $u,q\in(0,1)$.
		We define $\mathrm{SUSY}_1(\zeta,\varepsilon)$ as the set of $\mathbf{m}\in[-1+\delta_\varepsilon,1-\delta_\varepsilon]^N$ such that
		\begin{equation*}
			\left|\frac{1}{N}\|\mathbf{m}\|^2-q\right|\leq\varepsilon,
			\qquad
			\left|\frac{1}{N}\langle\partial_m h_\zeta(q,\mathbf{m}),\mathbf{m}\rangle
			-\xi'(q)\int_0^1\zeta([0,t])\,\mathrm{d} t\right|\leq \varepsilon,
		\end{equation*}
		and
		\begin{equation*}
			\mathrm{dist}\!\bigl(\zeta_\mathbf{m},\,\zeta|_{(q,1]}+\zeta([0,q])\,\delta_q\bigr)\leq\varepsilon,
		\end{equation*}
		where we recall that $\mathrm{dist}$ is as in (equation def:dist of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.224212+00:00","domain":"probability theory","id":"claim_cf9e9a9a83a417da92c23a4b82dc92aa730bbc4376003b7a7d4d95b429ce3c56","kind":"concept","schema_version":1,"statement":"[Proposition AS of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(M,[\hat{h}])$ be the conformal infinity of an asymptotically hyperbolic manifold $(X^{n+1},g^+)$, and $p\geq 3$. Let $u_0$ be a non-integrable minimizer of the fractional Yamabe energy and suppose that it satisfies the $\text{AS}_p$ condition. Then, there exists a sequence $(u_k)_{k\in \mathbb{N}} \subset H^\gamma (M)$ with $u_k \to u_0$ in $H^\gamma (M)$ such that 
\begin{align*}
    \lim_{k\to \infty}\frac{I_\gamma [u_k,\hat{h}] -\Lambda_\gamma (M,[\hat{h}])}{\|u_k - u_0\|_{H^\gamma (M)}^{p-\alpha} } = 0 \quad \forall \alpha>0.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.861751+00:00","domain":"probability theory","id":"claim_cfa97543e2ef279fa8e4cd5e795ffbada34b1c464209acf0caf557573d89e91a","kind":"lemma","schema_version":1,"statement":"[Lemma 16 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] For $x \geq 2t$, let
        \begin{equation}
            \phi(t, x) = \frac{K(x-2t)}{t^{3/2}}e^{-(x-2t)}e^{\frac{-(x-2t)^2}{4t}},
