        \end{align*}
	    where the integral is taken over $(\ell_2, r_1,r_2,r_3,r_4)$ with respect to Lebesgue measure on $(0,\infty)^5$, and $C = (1-\frac2{\gamma^2}W)^4$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.301973+00:00","domain":"probability theory","id":"claim_d306a584cf46eb298f812d27e7bf7d6c96d3e36379215aad5524d49787a5c3be","kind":"definition","schema_version":1,"statement":"[Definition def:results:CBP of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper) and Assumption (as:results:invMeasure of the paper). We say $\nu \in {\mathcal{M}_{\kappa, d}}$ is a \emph{Cayley fixed point{}} if $\nu$ is of the form \begin{equation}
        \nu(\mathbf{x}) = \nu_0(x_0)\prod_{i = 1}^\kappa \bar{\nu}(x_i | x_0),

    \end{equation}
    where $\nu_0 \in \mathcal{P}(\ensuremath{\mathbb{R}}^d)$ is absolutely continuous and solves the following fixed point equation
    \begin{equation}

        \nu_0(x)^{\frac{1}{\kappa}} = \frac{1}{\mathcal{Z}_{\nu_0}} e^{-\tfrac{1}{\kappa}U(x)}\int_{\ensuremath{\mathbb{R}}^d} e^{-W(x-y) - \frac{1}{\kappa}U(y)}\nu_0(y)^{\frac{\kappa-1}{\kappa}} dy, \quad \nu_0\text{-a.e. }x \in \ensuremath{\mathbb{R}}^d,
    \end{equation}
   where the normalizing constant is given by 
    \begin{equation}

        \mathcal{Z}_{\nu_0} := \int_{\ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d} \exp\Big( - \tfrac{U(x) + U(y)}{\kappa} - W(x -y)\Big) \big[\nu_0(x)\nu_0(y)\big]^{\frac{\kappa-1}{\kappa}} dx dy,
    \end{equation}
    and $\bar{\nu}(x|y) := \bar{\nu}(x, y) / \nu_0(y)$ for $\nu_0$-a.e. $x, y \in \ensuremath{\mathbb{R}}^d$ where the edge marginal $\bar{\nu}(x, y)$ of $\nu$ is mutually absolutely continuous with respect to $\nu_0^{\otimes 2}$ and is of the form
    \begin{equation}

        \bar{\nu}(x,y) = \frac{1}{\mathcal{Z}_{\nu_0}}\exp\Big( - \tfrac{U(x) + U(y)}{\kappa} - W(x -y)\Big) \big[\nu_0(x)\nu_0(y)\big]^{\frac{\kappa-1}{\kappa}}, \quad \nu_0^{\otimes 2}\text{-a.e. }(x, y) \in \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.962610+00:00","domain":"probability theory","id":"claim_d3077dc0ec159f51b65238e351d3b0cbac37885c7165a2369bdd075d2578dd6f","kind":"concept","schema_version":1,"statement":"[Theorem 14 (Free-boundary integral equation) of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] The optimal boundary $b_T$ solves
\begin{equation}
    \begin{aligned}
        g(x)=\mathbb{E}\Bigg[g(X^x_{T-t})&+\int_0^{T-t}c(t+u)\ind{X^x_{u}\in(1-b_T(t+u),b_T(t+u))}\,du\\
        &-\int_0^{T-t}\mathcal{L}g(X^x_{u})\ind{X^x_{u}\not\in(1-b_T(t+u),b_T(t+u))}\,du\Bigg],
    \end{aligned}
\end{equation}
for $x=b_T(t)$ and $x=1-b_T(t)$ with $t<T$. For $T=\infty$, the integral is interpreted as the monotone limit as the integration domain expands and $g(X^x_{T-t})=0$ since $X^x_{\infty}\in\{0,1\}$, almost surely.

