	\right\}
	\right).
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:32:29.004915+00:00","domain":"probability theory","id":"claim_d39e8757514b5093c775ac9cb4e4d0d42dcd10ab096a0b9f1c917dfae1c73cc2","kind":"lemma","schema_version":1,"statement":"[Lem typT 1 suc of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Let $a_1$ be the constant in Lemma~(lem:typT poly LB of the paper)
  and fix a compact set $K\subseteq M$.
  Define $H^{\mathrm{t}}_{n,K} \coloneqq \bigcap_{j=0}^{N_n-1}\{\hat{X}_{t_j(n)}\in K^k\}$.
  Then there exists a constant $c_K \in (0,\infty)$ such that, for all sufficiently large $n\in\mathbb{N}$,
  \begin{equation}
    \sup_{x\in M}
    \hat{P}_{\diag(x)}\!\left(
      H^{\mathrm{t}}_{n,K}
      \cap
      \bigcap_{j=0}^{N_n-1}
      \left\{
        C_{\delta_{\ell_{j+1}(n)}}\!\circ\hat{\theta}_{t_j(n)}
        <a_1\Psi_{\mathrm{ct}}(\delta_{\ell_{j+1}(n)})
      \right\}
    \right)
    \leq
    \frac{c_K}{n\log n}.
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.641842+00:00","domain":"probability theory","id":"claim_d3a2fac92c14a15c260406d959e68e1e888e8d9928ebbb10dd853d84caa1178a","kind":"definition","schema_version":1,"statement":"[Definition 4 of arXiv:2609.00702, 'On the Set-Valued Katugampola Fractional Integral: Properties and Regular Selections'] The Katugampola fractional integral of a function  $f:I \to \mathbb{R}$ is defined as 
        \begin{equation*}
            \begin{aligned}
        _a^\rho\mathfrak{D}^\nu f(t)= \frac{(\rho+1)^{1-\nu}}{\Gamma(\nu)}\int_a^t(t^{\rho+1}-x^{\rho+1})^{\nu-1}x^{\rho}f(x)dx
    \end{aligned}
        \end{equation*}
        where $\nu>0$ and $\rho \neq -1$ are real numbers.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.530658+00:00","domain":"probability theory","id":"claim_d3a4798aed3a9bf4f2593ac2bece4d9899efb939b4d6feb050ce1eadf942dbc0","kind":"concept","schema_version":1,"statement":"[Lemma 25 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm d}$, $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ and let $(\mathcal{Y}_t^{(\rm d)}, \mathcal{Y}_t^{(\rm a)})_{t \geq 0}$ be an $\text{ooSBM}(4, c, \Tilde{c})$ started from $(\mu_{\rm d}, \mu_{\rm a})$. Then we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. there exists $N<\infty$ such that for all $0 \leq t < 1$ we have
    \begin{equation*}
        \overline{\bigcup_{0 \leq u \leq t} \text{supp}(\mathcal{Y}_u^{(\rm d)}) \cup \text{supp}(\mathcal{Y}_u^{(\rm a)})} \subseteq (\mu_{\rm d} \cup \mu_{\rm a})^{NH(t)}.
    \end{equation*}
    \begin{proof}
        This can be concluded from the result for the coupled processes in Lemma \ref{lemma oosbm range domination} and from Corollary \ref{corollary SBM thickening}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

