{"assumptions":[],"created_at":"2026-10-27T20:29:14.940341+00:00","domain":"probability theory","id":"claim_d45a3476fc07e1716bda930f00f2860c69e9c8d21817a6e33874eeca8fda7b9e","kind":"lemma","schema_version":1,"statement":"[Lemma Lemma1stResult of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Suppose that Assumption (Assumptions of the paper) holds, let $\mathbf{X}_0$ be an initial random variable independent of $\mathbf{W}$, and let $\mathbf{X} = (\mathbf{X}_t)_{t \geq 0}$ be the corresponding solution to (equation eqGenSDEIntro of the paper) with $d$-th component $X = (X_t)_{t \geq 0}$. Then for all $\ell \in \mathbb{N}$, all $R > 0$ and all $\delta > 0$ it holds that
\begin{equation}

\begin{aligned}
&2  \Phi\Bigl(- \tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert \Bigr)^{\ell+1} - 2 \sum_{j = 1}^\ell \Phi\Bigl(-\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^j P \Bigl(\sup_{t \in I_{\ell-j}} \Vert \mathbf{X}_t \Vert > R \Bigr) \\
&\quad \leq P \Bigl(T_{1,\delta}(X) = \ell, \sup_{t \in [0, (\ell+1) \delta]} \Vert \mathbf{X}_t \Vert \leq R \Bigr) \\
&\quad \leq 2 \Phi\Bigl(\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^{\ell+1}
\end{aligned}
\end{equation}
and
\begin{equation}

\begin{aligned}
&2 \Phi\Bigl(-\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^\ell - 2 \sum_{j = 1}^{\ell-1} \Phi\Bigl(-\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^j P \Bigl(\sup_{t \in I_{\ell-j}} \Vert \mathbf{X}_t \Vert > R \Bigr) \\
&\quad \leq P \Bigl(T_{1,\delta}(X) \geq \ell, \sup_{t \in [0, \ell \delta]} \Vert \mathbf{X}_t \Vert \leq R \Bigr) \\
&\quad \leq 2 \Phi\Bigl(\tfrac{\sqrt{\delta}}{A} \sup_{\Vert \mathbf{x} \Vert \leq R} \vert F(\mathbf{x}) \vert\Bigr)^\ell,
\end{aligned}
\end{equation}
where $\Phi$ denotes the cumulative distribution function of the standard normal distribution and $I_1 \coloneq [0, \delta]$, $I_j \coloneq ((j-1) \delta, j \delta]$, $j = 2, \ldots, \ell+1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.772422+00:00","domain":"probability theory","id":"claim_d45af90e2ebec7190517c4b796a1de2fe781c073434dfc7e269f6f0c0d1e8fac","kind":"theorem","schema_version":1,"statement":"[Cor TP2-fnk-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] For $s\in\{0,\dots,d-1\}$, the array $(F^s_{n,k})_{n,k\geq 0}$ satisfies the following recursion:
	\begin{align}
	F^s_{n,k}
	=\sum_{j\geq 0}W^{*d}_{j} \,F^s_{n-1,k+j-1},
	\quad
	\begin{cases}
		n\geq 1,\quad k\geq1,\quad s\in\{1,\dots,d-1\};\text{ or,}\\
		n\geq 2,\quad k\geq1,\quad s=0,\\
	\end{cases}
	\end{align}
	where we make the convention that $F^0_{n,0}=0$ for all $n\geq1$.
	When $s\in\{1,\dots,d-1\}$ and $k=0$, we have the modified recursion:
	\begin{multline}
		F^s_{n,0}
		=\sum_{j\geq 0}\Bigl(W^{*d}_{j}-W^{*s}_0\cdot W^{*(d-s)}_j\Bigr) \,F^s_{n-1,j-1},
		\\
			n\geq 1,\quad k=0,\quad s\in\{1,\dots,d-1\},
	\end{multline}
	where we make the convention that $F^s_{n,-1}=0$ for all $s\in\{1,\dots,d-1\}$ and $n\geq0$.","status":"unverified"}

