    such that 
    \begin{equation}
        \bm{p} = -\alpha({\color{NavyBlue}{\mathbf{1}}}^{\otimes 2n} + \bm{q}) - \beta({\color{NavyBlue}{\mathbf{1}}}^{\otimes 2m} + \bm{r}){\color{NavyBlue}{\mathbf{0}}} + \alpha\beta\bm s + \gamma {\color{NavyBlue}{\mathbf{\varnothing}}}.
    \end{equation}
    {The time degrees $\deg_{{\color{NavyBlue}{\mathbf{0}}}}(\bm r)$ and $\deg_{{\color{NavyBlue}{\mathbf{0}}}}(\bm s)$ are only required to be finite.}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.504129+00:00","domain":"probability theory","id":"claim_d53eafc8462e276e9d5341e74bf7868d05bf00c1a8d424d60a3662b3bdfd230f","kind":"lemma","schema_version":1,"statement":"[Lemma vertex_s of arXiv:2607.22480, 'Distinguishability threshold for random geometric graphs'] Let $1\leq s< n$ be an integer and let $H\in \mathcal{E}$ be an $n$-vertex graph. Suppose that the $\boldsymbol{v}_1, \dots, \boldsymbol{v}_n$ are random vectors on $\mathbb{S}^{d-1}\subset \mathbb{R}^d$, sampled as in Lemma~(lemma:distribution_v_i of the paper), and let $G$ be the corresponding random geometric graph. Suppose that the set of coordinates $\boldsymbol{v}_i(j)$ are revealed for $j\leq s-1$, denote this set $\mathcal{G}_{s-1}$, and assume that they satisfy the event $\Pi_{s-1}$.

\begin{enumerate}
\item[(a)] The probability, over the remaining randomness, that $G$ and $H$ agree on edges $si$ for all $i\in \{s+1, \dots, n\}$ is
\begin{align}
    \mathbb{P}\Big[si\in E(G)\Longleftrightarrow si\in E(H)\text{ for all } i\in \{s+1, \dots, n\}\Big| \mathcal{G}_{s-1}\Big]\leq e^{\widetilde O(n^{3/2}p^{1/2}/{d})}\prod_{s<i\leq n}\Phi_{s-1, s, i}.
\end{align}
\item[(b)] Conditioning on $\mathcal{G}_{s-1}$ and on the event that $G, H$ agree on the edges $si$ for all $i\in \{s+1, \dots, n\}$, the coordinates $\boldsymbol{v}_{s+1}(s), \dots, \boldsymbol{v}_n(s)$ have the following distribution:\\
\begin{center}
\fbox{
\parbox{15cm}{\phantomsection\emph{Setup ($\star$)}: Suppose that the set of coordinates $\{\boldsymbol{v}_i(j)| i\in [n], 1\leq j\leq s-1\}$ is revealed and satisfies the event $\Pi_{s-1}$.
For $i\in \{s+1, \dots, n\}$, let $r_i(s)=\sqrt{1-\sum_{k=1}^{s-1} \boldsymbol{v}_i(k)^2}$ be the residual length of the vector $\boldsymbol{v}_i$ after coordinate $s$. If $si\in E(H)$, then $\boldsymbol{v}_i(s)/r_i(s)$ is distributed as the first coordinate on the unit sphere $\mathbb{S}^{d-s}\subseteq \mathbb{R}^{d-s+1}$, conditioned on being at least \[\tau_{si}=\frac{c_p}{\sqrt{d}\boldsymbol{v}_s(s)r_i(s)}-\frac{\langle \pi_{s-1}(\boldsymbol{v}_i), \pi_{s-1}(\boldsymbol{v}_s)\rangle}{\boldsymbol{v}_s(s)r_i(s)}.\]
If $si\notin E(H)$, then $\boldsymbol{v}_i(s)/r_i(s)$ is distributed as the first coordinate on the unit sphere $\mathbb{S}^{d-s}\subseteq \mathbb{R}^{d-s+1}$, conditioned on being smaller than $\tau_{si}$.

Moreover, all the coordinates $\boldsymbol{v}_i(s)$ are independent.

Additionally, define $\boldsymbol{u}_i(s)$ as the truncated random variable $\boldsymbol{u}_i(s)=\boldsymbol{v}_i(s)\mathbf{1}_{|\boldsymbol{v}_i(s)|\leq 10\sqrt{\log d}/\sqrt{d}}$}
}
\end{center}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.338670+00:00","domain":"probability theory","id":"claim_d53ffc49ecc3614d1d5658bede61ad6de8c9a6bf2e2fc7f6bfc5dcea05d3de56","kind":"concept","schema_version":1,"statement":"[Corollary 15 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Assume that $(G, H)$ is an inhomogeneous graph system, with a constant subsampling parameter $s \in (0, 1]$, where the mother graph $G^\uparrow$ follows the Chung-Lu model, with degree-law $\nu \in L^1$. Assume that $\nu \neq \delta_0$, and set 

    \begin{equation}
        d^* = \frac{\E[D^2]}{\E[D]} \in (0, +\infty]
    \end{equation}
    where $D \sim \nu$ is the degree-law of the model. Then:
    \begin{itemize}
        \item If $s^2 > \frac{1}{d^*}$, then $ \operatorname{pliminf}_{n \to +\infty}ov(\hat{\pi}, \pi^*) > 0$: partial alignment is feasible.
        \item If $s^2 < \frac{1}{d^*}$, then as long as $\nu$ is supported on $[\eps, +\infty)$ for some fixed $\eps > 0$, for any estimator $\hat{\pi}
        '$, $ \ds\operatorname{plimsup}_{n \to +\infty}ov(\hat{\pi}', \pi^*) = 0$: partial alignment is intractable.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.602296+00:00","domain":"probability theory","id":"claim_d544344670491bccf2218a241d6cd0865956944760bbf6e73f1c0fbd67d3d972","kind":"theorem","schema_version":1,"statement":"[Theorem 36 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Assume the hypotheses of Theorem~\ref{thm:augmented-semigroup}. Let $\rho:\mathcal E\to\X$ be the projection $\rho(x,u)=x$, and let

\begin{equation}
\Lambda_h((x,u),A)=R_h((x,u),A\times\N^d),
\qquad h\in\N^d,
\quad A\in\calX.
\end{equation}

The following assertions are equivalent.
\begin{enumerate}[label=\textup{(L\arabic*)},leftmargin=2em]
\item For every initial law concentrated on $\mathcal E$, the projected field $Z=\rho(Y)$ is a homogeneous $\N^d$-indexed Markov chain with respect to its lower-rectangle filtration

\begin{equation*}
\mathcal G_k^Z=\sigma\{Z_m:m\leqd k\}.
\end{equation*}
\item For every $h\in\N^d$ there exists a Markov kernel $P_h^Z$ on $\X$ such that

\begin{equation}
\Lambda_h((x,u),A)=P_h^Z(x,A)
\end{equation}

for every $A\in\calX$ and every $(x,u)\in\mathcal E$.
\end{enumerate}
When these equivalent conditions hold, $(P_h^Z)_{h\in\N^d}$ is a Markov semigroup on $\X$:

\begin{equation}
P^Z_{\zerod}=I,
\qquad
P^Z_{h+r}=P^Z_hP^Z_r,
\qquad h,r\in\N^d,
\end{equation}

and the coordinate kernels $P^Z_{e_1},\ldots,P^Z_{e_d}$ commute.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:46.462670+00:00","domain":"probability theory","id":"claim_d54eccf24ff0544a9c42d0cf7633360af64780dbe4deae031c1436f893b9e5f2","kind":"concept","schema_version":1,"statement":"[Corollary 24 (The covariant wave equations for the velocity in terms of $\Flatcurl(\Flatcurl(v))$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The fluid velocity components $v^i$ also satisfy the following covariant wave equation: 
