{"assumptions":[],"created_at":"2026-10-27T06:57:31.000470+00:00","domain":"probability theory","id":"claim_d55e853f84b34fca6260c28c070e2e671edabfd72e841bec9db7987ebc9486e6","kind":"theorem","schema_version":1,"statement":"[Proposition 47 (Square-root promotion) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Suppose
\[
 0\le N_q\le MR^2\Id,
 \qquad
 E_q=R_q^*N_qR_q,
\]
and let $L$ be a top eigenspace of $E_q$, with eigenvalue $\lambda>0$.  Set
\begin{equation}
 V_q^{1/2}=\Ran(N_q^{1/2}R_qL).

\end{equation}
Then, for every unit $c\in L$,
\begin{equation}
 \norm{P_{V_q^{1/2}}R_qc}^2
 \ge\frac{\lambda}{MR^2},
 \qquad
 \norm{N_q^{1/2}R_qc}^2=\lambda.

\end{equation}
Moreover
\begin{equation}
 \ip{N_q^{1/2}R_qc}{N_q^{1/2}R_qc'}
 =\ip{R_qc}{N_qR_qc'},

\end{equation}
which is a four-source Gram.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.668727+00:00","domain":"probability theory","id":"claim_d5600f9cd826e737aaa6ff4acafe83a76f8a0c856aa6704d4379011a4ed8d1fd","kind":"concept","schema_version":1,"statement":"[Theorem 5 (Theorem \ref{DecoTheo3}) of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f : X \rightarrow Y$ be a topologically semi-small map such that $X$ is a closed topological manifolds, the fibered set $R$ is a closed stratified space, and $Y$ is a closed topological $n$-pseudomanifold. Set $B:=f^{-1}(R)$, let $R=\bigsqcup_{\beta}T_{\beta}$ be a suitable decomposition of the fibered set, and let $R_{\operatorname{rel}}$ be its relevant part. Furthermore, let the filtration $Y \supset Y_{n_{R}}(=R) \supset Y_{n_{R}-1} \supset \cdots$ be the refined stratification on $Y$ obtained by Proposition~\ref{RefinedStra}, where $n_{R}:= \dim(R)$. Set $S_{k}:= Y_{k} \setminus Y_{k-1}$, and assume the followings:
        \begin{enumerate}
        	\item for each $r \in R$ the fiber $f^{-1}(r)$ is a closed orientable topological manifold;
        	\item the normal bundle of the manifold $f^{-1}(S_{k})$ in $X$ exists, for each $0 \leq k \leq n_{R}$, and is orientable, and for each $S_{k'}\in R_{\operatorname{rel}}$ and each $r\in S_{k'}$ there is a small open neighborhood $U$ of $r$ such that the connecting homomorphism in the Gysin sequence of the normal bundle of $S_{k}$ restricted to $f^{-1}(U)$ vanishes in degree $\operatorname{codim}_{X}(B)-1$.
        	\end{enumerate}
        	Let $R(f|_{X \setminus B})_{*}\,\underline{\mathbb{Q}}_{X \setminus B}\simeq \underline{\mathbb{Q}}_{Y \setminus R}\oplus \mathcal{L}$, where $\mathcal{L}$ is the local system on $Y \setminus R$ associated to the covering map $f|_{X \setminus B}$. If each $\operatorname{codim}_{Y}(S_{k})$ is even and $\operatorname{codim}_{X}(B)\geq 2$, then
        \begin{align*}
        	Rf_{\ast}\underline{\mathbb{Q}}_{X}[n]\simeq \bigoplus_{S_{k} \in R_{\operatorname{rel}}}\iota_{k\ast}(IC_{\overline{S_{k}}} (R^{0}f\vert_{f^{-1}(S_{k})}\underline{\mathbb{Q}}_{S_{k}})) \oplus IC_{Y}(\underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}),
        \end{align*}
        where $\iota_{k}:\overline{S_{k}} \hookrightarrow Y$ is the canonical closed inclusion, and $IC^{\overline{p}}_{Y}$ is Deligne's intersection complex with respect to the above refined stratification and the perversity $\overline{p}\in\{\overline{n},\overline{m}\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

