{"assumptions":[],"created_at":"2026-10-27T05:37:14.838102+00:00","domain":"probability theory","id":"claim_d60a8be6c29fa94156ea4b705fdc71893d21a23ec2b009e532b4215fb52a23cb","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2607.11608, '2607.11608'] Let $d\ge 1$ and $p^*=2+\frac{4}{d}$. Let $\left\{\ld_N\right\}_{N\in \N}$ be a non-increasing sequence sequence of positive numbers tending to $0$ and $\left\{K_N\right\}_{N\in \N}$ be a non-decreasing sequence of positive numbers. Then, there exists $\ld^*\ge \ld_*>0$ such that the following hold:

\smallskip
\noi
\textup{(i) (weakly coupling regime).}
Suppose that 
\begin{align}
\ld_N\le \ld_* (K_N+\log N)^{-\frac{2}{d}}

\end{align}

\noi
for any $N \in \N$.
Then, 
given any $r\geq 1$ we have
\begin{align*}
\sup_{N\in\N}\mathcal{Z}_{p^*\!,\,N}:=\sup_{N\in\N}\Big\|\ind_{\{|\int_{\R^d} \, :|\P_{N} u|^2: \, dx| \, \leq K_N\}} e^{ \ld_N R_{p^*\!,N}(u)}\Big\|_{L^r(\mu)}<\infty.

\end{align*}

\noi
In particular, we have
\begin{align}
\lim_{N\rightarrow\infty}
\ind_{\{|\int_{\R^d} \, :|\P_{N} u|^2: \, dx| \, \leq K_N\}}  
e^{\ld_N  R_{p^*\!,N}(u)}=
\ind_{\{|\int_{\R^d} \, :|u|^2: \, dx| \, \leq K\}}  \quad     \text{in}\ L^r(\mu), 

\end{align}

\noi
where 
$K = \lim_{N \to \infty}K_N \in (0, \infty]$.
Here, 
\[\int_{\R^d} :\!|u|^2\!:dx = \lim_{N \to \infty}\int_{\R^d} :\!|\P_{N} u|^2\!:dx,\]

\noi
where the limit is understood in 
$L^r(\mu)$ and $\mu$-almost surely
as in Lemma \ref{LEM:conv0}.
As a consequence, 
we have

\smallskip
\begin{itemize}
\item[\textup{(i.a)}] 
If $K  =  \lim_{N \to \infty}K_N  = \infty$, 
then the truncated Gibbs measure $\rho_N$
in \eqref{trunc_gibbs}
converges in total variation to the base Gaussian measure $\mu$ in \eqref{Gaussian}
as $N \to \infty$.



\smallskip
\item[\textup{(i.b)}]
If $K = \lim_{N \to \infty}K_N < \infty$, 
then the truncated Gibbs measure $\rho_N$
in \eqref{trunc_gibbs}
converges in total variation to the base Gaussian measure
with a renormalized $L^2$ cut-off\textup{:}
\begin{align*}
\ind_{\{|\int_{\R^d} \, :|u|^2: \, dx| \, \leq K\}}  d\mu, 

\end{align*}

\noi
as $N \to \infty$.



\end{itemize}

\smallskip
\noi
\textup{(ii) (strongly coupling regime).}
Suppose that 
\begin{align}
\ld_N\ge \ld^{*}(K_N+\log N)^{-\frac{2}{d}}

\end{align}

\noi
for any sufficiently large $N \gg 1$.
Then, we have 
\begin{align}
\sup_{N\in\N}\mathcal{Z}_{p^*\!,\,N}=
\sup_{N\in\N}\Big\|\ind_{\{|\int_{\R^d} \, :|\P_{N} u|^2: \, dx| \, \leq K_N\}} e^{ \ld_N  R_{p^*\!,N}(u)}\Big\|_{L^1(\mu)}
=\infty.

\end{align}

\noi
As a consequence, 
the truncated Gibbs measure $\rho_N$ in \eqref{trunc_gibbs}
does not converge   to any  limit in total variation, even up to a subsequence. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

