{"assumptions":[],"created_at":"2026-10-27T21:24:20.646426+00:00","domain":"probability theory","id":"claim_d70ccae9247c87b702cebe9a4242535cb128862a08b48e1d58485442179d2474","kind":"concept","schema_version":1,"statement":"[Lemma lem:latala-iid-centered-sum of arXiv:2608.11084, 'Sharp Frobenius-Norm Concentration for Sample Moment Tensors'] {latala1997estimation}}]

