{"assumptions":[],"created_at":"2026-10-27T09:36:31.233952+00:00","domain":"probability theory","id":"claim_d7123262b03196195c6441a8968b61fe761fe6202fa11bfaf5db00a5d71cedf0","kind":"lemma","schema_version":1,"statement":"[Lemma 11 ({cf.~\cite{bhatt2022Prismatic}*{Remark 2.5.5}}) of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(A\) be a commutative ring, let \(\mcalG\) be a flat affine group scheme over \(U\defeq\Spec(A)\), and let
  \begin{equation*}
    f\colon B_U\mcalG\to U
  \end{equation*}
  be the structure morphism.
  Let \(q\colon U\to B_U\mcalG\) be the canonical fpqc cover, let \(q_\bullet\colon U^\bullet\to B_U\mcalG\) be its \v{C}ech nerve, and let \(p_n\colon U^n\to U\) be the structure morphism, which can be identified with the projection \(\mcalG^n \to U\).

  For \(\mcalF\in\mcalD^+_{\qcoh}(B_U\mcalG)\), put
  \begin{equation*}
    \mcalF_n\defeq Lq_n^*\mcalF \in \mcalD_{\qcoh}(U^n),\qquad K_{\mcalF}^n\defeq R(p_n)_{*}\mcalF_n \in \mcalD_{\qcoh}(U) \cong \mcalD(A).
  \end{equation*}
  Then the following assertions hold.
  \begin{enumerate}
    \item There is a canonical equivalence
    \begin{equation}

      Rf_*\mcalF\xrightarrow{\sim}\Tot(K_{\mcalF}^\bullet)
    \end{equation}
    in \(\mcalD_{\qcoh}(U)\simeq\mcalD(A)\).
    \item If \(\mcalF\in\mcalD^{\geq c}_{\qcoh}(B_U\mcalG)\), then \(K_{\mcalF}^n\in\mcalD^{\geq c}(A)\) for every integer \(n\geq0\).
    \item For every flat ring homomorphism \(A\to A'\), write \(g\colon U'\defeq\Spec(A')\to U\) for the induced morphism, put \(\mcalG_{U'}\defeq\mcalG\times_UU'\), and write \(f'\colon B_{U'}\mcalG_{U'}\to U'\) for the structure morphism, and \(g'\colon B_{U'}\mcalG_{U'}\to B_U\mcalG\) for the projection. Then the base change morphism
    \begin{equation}

      A'\otimes_A^LRf_*\mcalF\to Rf'_*L(g')^*\mcalF
    \end{equation}
    is an equivalence in \(\mcalD_{\qcoh}(U')\simeq\mcalD(A')\).
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.187198+00:00","domain":"probability theory","id":"claim_d7252d2e675a7b9aed3e8d2ae035a1df0f12f33dbc7af78d31a57747e1da0b2b","kind":"concept","schema_version":1,"statement":"[Lemma 23 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $3\le d\le 5$ and $\epsilon>0$, there exist $\Cl(d,\epsilon),\cl(d,\epsilon)>0$ such that for any $n\ge \Cref{const_lemma_separation1}$, $N\ge \Cref{const_lemma_separation1}n$, $\psi\in \Psi(n,N)$, $\diamond\in \{\mathrm{in},\mathrm{out}\}$, $i\in \{ 1,2\}$, and any line segment $\widetilde{\eta}\subset \mathfrak{B}_{m_{\diamond},100}^{\diamond}$ satisfying $\mathrm{vol}(\widetilde{\eta})\le 100m_\diamond$ and $\mathrm{dist}(z_i^{\diamond},\widetilde{\eta})\ge \frac{m_\diamond}{100}$, 
	 \begin{equation}
	 	\mathbb{P}\big( \mathsf{R}_i^{\diamond}[\psi, \cref{const_lemma_separation2}, \widetilde{\eta}] \mid    \mathsf{C}[\psi] \big) \le \tfrac{1}{4} \epsilon. 
	 \end{equation}
	Particularly, by taking $\widetilde{\eta}=\{z_{3-i}^\diamond\}$, this implies 
\begin{equation}
		\mathbb{P}\big( \mathsf{S}[\psi,\cref{const_lemma_separation2}] \mid    \mathsf{C}[\psi] \big)\le   \epsilon.
	\end{equation}
	Consequently, there exists $\cl>0$ such that 
	\begin{equation}
		\mathbb{P}\big(     \widehat{\mathsf{C}}[\psi, \cref{const_lemma_separation3}] \big)\asymp  \mathbb{P}\big(  \mathsf{C}[\psi] \big), \ \forall \psi\in \Psi(n,N). 
