{"assumptions":[],"created_at":"2026-10-27T12:59:58.453347+00:00","domain":"probability theory","id":"claim_d775b5be4f7667dc7db79a46b6bca9932bcc6654bf5525b3c7a2ac9f9c5bc4a3","kind":"concept","schema_version":1,"statement":"[Thm logsequences of arXiv:2605.10908, 'On Talagrand's Convexity Conjecture'] There exist constants $\varepsilon, L >0$ so that for each solid subset $A \subset \mathbb{R}^{n}$ with $\gamma_{n}(A) \geq 1-\varepsilon$, there exists a finite sequence $\{I_{k}\}_{k \geq 1}$ of subsets of $[n]$ such that 
    \begin{itemize}
        \item $L |I_{k}| \geq \log(k+1)$ for each $k,$
        \item For any $x \in \mathbb{R}^{n}$, if $\sum_{i \in I_{k}} x_{i}^{2} \leq L^{-1}|I_{k}|$  for all $k \geq 1$, then $x \in A_{(3)}$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.635224+00:00","domain":"probability theory","id":"claim_d7772371623dbfc0c7497e9148ff1ec049afdf88947652e010ed0a0d911e18ca","kind":"concept","schema_version":1,"statement":"[Lemma lem:simplex_computation of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $\vec \varpi, \vec \alpha$ and $\vec \ell$ be such that $\vec\ell$ is of convergent type for $\cal F$. Let $S \subset \cal P$ be a simplex, and write $d = \dim \cal F$.
	\begin{enumerate}[leftmargin=*, label=\normalfont(\roman*)]
	\item If at most $d$ vertices of $S$ are contained in $\cal F$, then
		\begin{equation*}
			\int_{(\log B) S} \prod_{i=1}^s \mathrm e^{t_i} (t_i + 1)^{\ell_i} \,\mathrm d\vec t \ll_{S} B^a (\log B)^{d + \ell - \delta},
		\end{equation*}
		where $\delta > 0$ is a constant that depends on $S$.
	\item If exactly $d+1$ vertices of $S$ are contained in $\cal F$, let $\cal F_S = \cal F \cap S$ be the face of $S$ contained in $\cal F$. Then there exists a constant $C_{S}$ not depending on $\vec \ell$ such that
		\begin{align*}
			\int_{(\log B) S} \prod_{i=1}^s \mathrm e^{t_i} (t_i + 1)^{\ell_i} \,\mathrm d\vec t &= C_{S} B^a \int_{(\log B)\cal F_S} \prod_{i=1}^s (t_i + 1)^{\ell_i} \,\mathrm d\mu\\
			& \qquad \qquad\qquad+ O_{S}(B^a (\log B)^{d + \ell - \delta}),
		\end{align*}
		where $\delta > 0$ is a constant that depends on $S$.
	\item Let $\vec v_0, \ldots, \vec v_s$ be the vertices of $S$ and $\vec v_0, \ldots, \vec v_d$ those contained in $\cal F$. Put $\vec w_i = \vec v_i - \vec v_0$, and let $\operatorname{vol}_d(\cal F_S)$ be the $d$-dimensional volume of $\cal F_S$. Then the constant $C_S$ in (enum:d+1-case of the paper) is 
		\begin{align*}
			C_S &= \frac{\det(\vec w_1, \ldots, \vec w_s)}{\sqrt{\det((\vec w_1, \ldots, \vec w_d)^t (\vec w_1, \ldots, \vec w_d))}} \prod_{i=d+1}^s \Bigl(-\sum_{j=1}^s w_{ij}\Bigr)^{-1}\\
			&= \frac{s! \operatorname{vol}(S)}{d! \operatorname{vol}_d(\cal F_S)} \prod_{i=d+1}^s \bigl(a - |\vec v_i|_1\bigr)^{-1}.
		\end{align*}

	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

