\qquad \mathbb{P}_{x_0}\text{-a.s.},
$$
where
$$
\|h\|_{n,1,B}
:=
\int_0^T
\sum_{i=0}^{m(n)-1}
\bigl(|h(B(t_i^n))|+|h(B(t_{i+1}^n)|)\bigr)(t_{i+1}^n-t_{i}^n)
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.262632+00:00","domain":"probability theory","id":"claim_d79d024fd6e2120b4e9497f6cac3aeed1a1372c51d65b2035ac4480b5ccc30e6","kind":"concept","schema_version":1,"statement":"[Lemma kzetaestimate-long of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Retain the setting of Lemma (lemma:kzetaestimate-short of the paper), but forget the constraint that {\small$|\t-\s|\leq N^{\beta}N^{-\zeta}$}. On the same high probability event as in Lemma (lemma:kzetaestimate-short of the paper), we have 

