$$
where $g_K: \mathbb{H} \backslash K \rightarrow \mathbb{H}$ is the unique conformal map satisfying the hydrodynamic normalization $g(z)=z+O\left(\frac{1}{z}\right)$ as $z \rightarrow \infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.958859+00:00","domain":"probability theory","id":"claim_d7c34d1115a6a329c28e08fdeaf814697a4c9edcc3758f17d9dae008a7efc986","kind":"theorem","schema_version":1,"statement":"[Theorem 16 ($L^p$ centered operator) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Fix $p\ge2$ and $\eps>0$.  If
\begin{equation}
 \mathfrak S_H^{(\eps)}(\beta,\sigma)
 +\mathfrak S_B^{(\eps)}(\zeta,\sigma)<\infty,
\end{equation}
then $\cB^\circ_\Lambda$ is a well-defined random bounded operator
\[
 \cB^\circ_\Lambda:\Xspace_T^\sigma\to\Yspace_T^{\beta,\zeta},
\]
uniformly in $\Lambda$, and
\begin{equation}
 \left\|\norm{\cB^\circ_\Lambda}_{\Xspace_T^\sigma\to\Yspace_T^{\beta,\zeta}}
 \right\|_{L^p(\Omega)}
 \lesssim_{p,T,\eps}
 \mathfrak S_H^{(\eps)}(\beta,\sigma)
 +\mathfrak S_B^{(\eps)}(\zeta,\sigma).
\end{equation}
Moreover, as $\Lambda\to\infty$,
\begin{equation}
 \cB^\circ_\Lambda\to\cB^\circ
