{"assumptions":[],"created_at":"2026-10-26T20:54:34.577355+00:00","domain":"probability theory","id":"claim_d822cba6e726eff6b31ed19ab4075bd20a6d0cb5322195df13d26887417d865a","kind":"concept","schema_version":1,"statement":"[Lemma 15 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ satisfy 
	\eqref{c1}. Let $Y_N=I_q(g_N)$ with $p<q<2p$ and 
	$\sup_N\|g_N\|_{H^{\otimes q}}<\infty$. Define
	\begin{equation}
		h_N := \frac{f_N\otimes_p g_N}
		{\|f_N\|^2_{H^{\otimes p}}}\in H^{\odot(q-p)},
	\end{equation}
	\begin{equation*}
		g_N^{(2)} := g_N - \frac{q!}{p!(q-p)!}
		f_N\widetilde\otimes h_N\in H^{\odot q},
		\qquad
		\varepsilon_N := I_q(g_N^{(2)}).
	\end{equation*}
	Then for every $N\geq 1$:
	\begin{equation}
		Y_N = \frac{1}{p\sigma^2}X_N\cdot Y_{1,N} 
		+ \varepsilon_N + r_N,
	\end{equation}
	where:
	\begin{enumerate}
		\item $f_N\otimes_p g_N^{(2)}=0$, and consequently 
		$\langle DX_N, D\varepsilon_N\rangle_H\to 0$ in 
		$L^2(\Omega)$, so $\varepsilon_N$ is asymptotically 
		independent of $X_N$;
		\item $r_N\to 0$ in $L^2(\Omega)$ as $N\to \infty$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.854201+00:00","domain":"probability theory","id":"claim_d825435361ac5b84e554216c7eca3591f849d08d60cb4ef50f746d45e2711121","kind":"lemma","schema_version":1,"statement":"[Lemma 6 (Averaged diagonal self-averaging) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] For every fixed $L<\infty$,
\begin{equation}
