{"assumptions":[],"created_at":"2026-10-26T19:25:40.048299+00:00","domain":"probability theory","id":"claim_d8691ded0a0fb4701d5298f44749893c910b9666e4ef6a9504012a7238dc703c","kind":"theorem","schema_version":1,"statement":"[Theorem 7 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $Z$ be a one-dimensional symmetric $\alpha$-stable process with $\alpha \in (1,2)$. Consider two processes, $X$ and $\tilde{X}$, satisfying the SDEs
\begin{align*}
X_t = x_0 + \int_0^t b(s,X_s) \rd s + \int_0^t \sigma(s,X_{s-}) \rd Z_s \quad \text{and} \quad \tilde{X}_t = \tilde{x}_0 + \int_0^t \tilde{b}(s,\tilde{X}_s) \rd s +  \int_0^t \tilde{\sigma}(s,\tilde{X}_{s-}) \rd Z_s,
\end{align*}
for $t\in[0,T]$ with initial values $x_0, \tilde{x}_0\in\real$.
Let the framework be the same as in Theorem \ref{mainthm}.
However, instead of the assumptions (i)-(iii) therein, suppose the coefficients satisfy the following conditions for some constant $\tilde{\eta} \in [1/\alpha,1]$:
\begin{itemize}
    \item[(a)] The coefficient $\tilde{b}$ is Lipschitz continuous and $\tilde{\sigma}$ is $\tilde{\eta}$-H\"older continuous in space: there exist nonnegative functions $f_{\tilde{b}}$ and $f_{\tilde{\sigma}}$ such that
    \begin{align*}
       |\tilde{b}(t,x)-\tilde{b}(t,y)| \le f_{\tilde{b}}(t) |x-y|
       ,\ |\tilde{\sigma}(t,x)-\tilde{\sigma}(t,y)| \le f_{\tilde{\sigma}}(t)|x-y|^{\tilde{\eta}}
       ,\ \int_0^T f_{\tilde{b}}(s)\rd s<\infty
       ,\ \int_0^T f_{\tilde{\sigma}}^\alpha(s)\rd s<\infty.
    \end{align*}
    \item[(b)] The differences between coefficients are small in the supremum norm.
    Let the quantities $B_\infty$ and $S_\infty$ be defined as follows.
    For the drift coefficients, $B_\infty$ is defined by either
    \begin{align*}
        B_\infty := \int_0^T \left\|b(s,\cdot) - \tilde{b}(s,\cdot)\right\|_\infty \rd s \quad \text{or} \quad B_\infty := \sup_{t\in[0,T]} \left\|b(t,\cdot) - \tilde{b}(t,\cdot)\right\|_\infty.
    \end{align*}
    For the jump coefficients, $S_\infty$ is defined by either
    \begin{align*}
        S_\infty := \left(\int_0^T \left\|\sigma(s,\cdot) - \tilde{\sigma}(s,\cdot)\right\|_\infty^\alpha \rd s \right)^{1/\alpha} \quad \text{or} \quad S_\infty := \sup_{t\in[0,T]} \left\|\sigma(t,\cdot) - \tilde{\sigma}(t,\cdot)\right\|_\infty.
    \end{align*}
    The theorem's conclusions hold provided that there exists a choice of definitions for $B_\infty$ and $S_\infty$ from the options above such that $B_\infty<1$ and $S_\infty<1$.
    \item[(c)] Additionally, the squared difference of the jump coefficients is integrable:
    \begin{align*}
        \int_0^T \left\|\sigma(s,\cdot)-\tilde{\sigma}(s,\cdot)\right\|^2_\infty\rd s<\infty.
    \end{align*}
    These can be set as either $B_\infty$ or $S_\infty$.
\end{itemize}
Then, under these assumptions, the conditions on the coefficients can be significantly relaxed compared to Theorem \ref{mainthm}.
Notably:
\begin{itemize}
    \item The coefficients $b$ and $\sigma$ of the baseline process $X$ are no longer required to be continuous or bounded; mere measurability is sufficient. The only condition required for these coefficients is that a weak solution of $X$ exists.
    \item The coefficients $\tilde{b}$ and $\tilde{\sigma}$ of the perturbed process $\tilde{X}$ are no longer required to be bounded. Note that $\tilde{X}$ is assumed to have a strong solution.
    \item One may define $B_\infty$ using either the $L^1([0,T]; L^\infty)$ or $L^\infty([0,T]; L^\infty)$ norm of $b-\tilde{b}$. The former typically provides a tighter smallness condition for short time intervals, whereas the latter is preferable for a long time horizon where the integral norm might exceed unity. The same applies to $S_\infty$.
\end{itemize}
There exists a positive constant $C = C\left(T, \alpha, \int_0^T f_{\tilde{b}}(s)\rd s, \int_0^T f_{\tilde{\sigma}}(s)\rd s\right)$ such that the following stability estimates hold:

\noindent (1) Convergence in expectation:
\begin{align*}
\sup_{t \in [0,T]} \e\left[|X_t-\tilde{X}_t|^{\alpha-1}\right] \le 
 \begin{cases}
    C\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B_\infty^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S_\infty^{\alpha-1/\tilde{\eta}}\right\}\right\}& \textrm{if~~}\tilde{\eta} \in(1/\alp","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.113228+00:00","domain":"probability theory","id":"claim_d86cedc17ad5431087784e395941b3c6c40e04464db9da299e2f8c319c87e99b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:weight-removal-interface-match of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Put $\chi_{\rm rad}=50r^2/29$ and define
\begin{equation}
 \begin{aligned}
 \varphi_-(r)&=\sum_{n=0}^\infty a_n\chi_{\rm rad}^n,
 &a_0&=1,
 &a_n&=-\frac{3}{n!(2n-1)(2n+1)(2n+3)}\quad(n\geq1),\\
 \varphi_+(r)&=r-\frac{39}{25r}-\frac{507}{625r^3}
                 -\frac{6591}{15625r^5},
 &&& &r>0.
 \end{aligned}

\end{equation}
The two profiles solve
\begin{equation}
 \frac{29}{200}\varphi_-''
 +\left(\frac{29}{50r}-\frac r2\right)\varphi_-'
 +\frac12\varphi_-=0,
 \qquad
 \frac{13}{50}\varphi_+''
 +\left(\frac{39}{25r}-\frac r2\right)\varphi_+'
 +\frac12\varphi_+=0.

\end{equation}
There exist matching parameters
\begin{equation*}
 R_{\mathrm{int}}\in
 \left(\sqrt{\frac{29}{15}},\frac{\sqrt{203}}{10}\right),
 \qquad \mathfrak s_{\mathrm{match}}\ne0,
\end{equation*}
For these parameters, the matched profile
\begin{equation}
 \varphi_{\rm dw}(r)=
 \begin{cases}
  \varphi_-(r),&0\leq r\leq R_{\mathrm{int}},\\
  \mathfrak s_{\mathrm{match}}\varphi_+(r),&r\geq R_{\mathrm{int}}
 \end{cases}

\end{equation}
is $C^1$ and piecewise smooth.","status":"unverified"}

