{"assumptions":[],"created_at":"2026-10-26T20:52:45.022168+00:00","domain":"probability theory","id":"claim_d8c8b98116336daa5c3ed584da27f9b4b69649f303dee7e508ab573d98980834","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2606.06193, 'Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common N'] Let $\varphi \in C_b^{2,1}(\R^d\times \mathcal{P}_2(\mathbb{R}^d),\R)$. Then, for any given $x\in\R^d$ and $X \in L^2(\Omega, \mathbb{R}^d)$ we have the following second-order expansion, for all $y\in\R^d$ and $Y\in L^2(\Omega,\R^d)$,
        \begin{equation*}
            \begin{aligned}
                &\varphi(y,\cL(Y))- \varphi(x,\cL(X)) \\
                = & \varphi_x(x,\cL(X))[y-x]
                +\E\left[\varphi_\mu(x,\cL(X))(X)[Y-X]\right]
                +\frac{1}{2}\varphi_{xx}(x,\cL(X))[y-x,y-x]\\
                &+\frac{1}{2} \E\left[\tilde{\E}\left[ \varphi_{\mu\mu}(x,\cL(X))(\tilde{X}, X)[ \tilde{Y}-\tilde{X},Y-X]\right]
                +\varphi_{y\mu}(x,\cL(X))(X)[Y-X,Y-X]\right]\\
                &+\E\left[\varphi_{x\mu}(x,\cL(X))(X)[Y-X,y-x]\right]+R(x,y,\cL(X), \cL(Y)).
            \end{aligned}
        \end{equation*}
        Furthermore, for all $x,y\in \R^d$ and $X,Y \in L^2(\Omega, \mathbb{R}^d)$, the remainder satisfies the estimate
        \begin{equation*}
            \begin{aligned}
                |R(x,y,\cL(X), \cL(Y))| \leq C\left( |y-x|^3

                + \E[|Y-X|^3]\right),
            \end{aligned}
        \end{equation*}
        and the constant $C \in \mathbb{R}_{+}$ only depends on the Lipschitz constants of $\varphi_{xx}$, $\varphi_{x\mu}$, $\varphi_{\mu\mu}$ and $\varphi_{y\mu}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.356741+00:00","domain":"probability theory","id":"claim_d8cb417ff8089f28fe4706fe11af66494df6901f3a60acc86887470309d5c090","kind":"lemma","schema_version":1,"statement":"[Lemma 3 of arXiv:2506.18558, '2506.18558'] Suppose that Assumption {\rm\ref{A2}} holds. Then the following statements hold.
\begin{itemize}
\item[{\rm (1)}] For any $p\ge 4$, there exist constants $C_{1,p}$ and $C_{2,p}>0$ such that for all $t\ge s$, $x\in \RR^n$ and $y\in \RR^m$,
\begin{equation}
\EE|Y_{t}^{s,x,y} |^{p} \le e^{-C_{1,p}(t-s)}|y|^p+C_{2,p}(1+|x|^p);
\end{equation}
\item[{\rm (2)}] There exist constants $\beta$ and $C>0$ such that for any $t \ge s$, $x_1,x_2\in\RR^{n}$ and $y_1,y_2\in\RR^{m}$,
\begin{align}
\mathbb{W}_1 (\delta_{y_1}P^{x_1}_{s,t}, \delta_{y_2}P^{x_2}_{s,t} )\le Ce^{-\beta(t-s) }|y_1-y_2|+C|x_1-x_2|.
\end{align}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.342336+00:00","domain":"probability theory","id":"claim_d8d0181ddda594578ae9fdb6f082bca8193bcc7aa4755dfa88ee5aaa0716d477","kind":"concept","schema_version":1,"statement":"[Proposition 17 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $t \geq 0$.
    Then, if $X \subseteq V_{\geq t}$,

    \begin{equation}
       \sum_{u \in X} w_K(u) \leq |K[{X \leftrightarrow V_{\geq t}}]| .
    \end{equation}
    Similarly, if $Y \subseteq V_{< t}$,
    \begin{equation}
        \sum_{u \in Y} w_K(u) \geq |K[{Y \leftrightarrow (V_{\geq t} \cup Y)}]|.
    \end{equation}


    In particular, $\dsum_{u \in V_{\geq t}} w_K(u) = |K[V_{\geq t}]|$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

