{"assumptions":[],"created_at":"2026-10-26T20:46:26.257186+00:00","domain":"probability theory","id":"claim_d8e21e3935fe3c07baaf217e4678eeabd73ed0a31a71d2438794a8a8368ef645","kind":"lemma","schema_version":1,"statement":"[Lem 60 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] \quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]Suppose that $(F,R,\mu)$ satisfies assumption $\rm{(A2)}$.
  Then
for any $f\in\BL^{\kappa},\;\delta\in (0,1],\;\varepsilon\in (0,1]$, and $\eta\in (0,\varepsilon)$, we have 
\begin{align*}
  \sup_{\substack{t\geq 0\\x\in F}}|P_{t+\delta}f(x)-P_tf(x)|\lesssim
  \g{c}{12q2}\left\{\|f\|_{\Lip^{\kappa}}\varepsilon^{\kappa}
    +\|f\|_{F}\left[\frac{\eta^{\theta}}{\varepsilon^{\theta} }+\frac{\delta}{\eta^{s_0 \theta}(\varepsilon^{\theta}-\eta^{\theta})}\right]\right\} ,
\end{align*}
where
\begin{align*}
  \g{c}{12q2}=1+\frac{1}{c_l \left[ \frac{c_{\rm{LR}}(1\wedge \frac{1}{2}\diam F)^{\theta}}{1+(1\vee \frac{1}{\diam F})c_{\rm{LR}}(1\wedge \frac{1}{2}\diam F)^{\theta}} \right]^{1+s_0}}.
\end{align*}
\item[$\rm{(ii)}$]Suppose that $(F,R,\mu)$ satisfies assumption $\rm{(A3)}$.
  Then
for any $f\in\BL^{\kappa},\;\delta>0,\;\varepsilon\in (0,1]$, and $\eta\in (0,\varepsilon)$, we have 
\begin{align*}
  \sup_{\substack{t\geq 0\\x\in F}}|P_{t+\delta}f(x)-P_tf(x)|\lesssim
  \|f\|_{\Lip^{\kappa}}\varepsilon^{\kappa}
    +\|f\|_{F}\exp \left[ -\g{c}{summ}(1\wedge \frac{1}{2}\diam F)^{1+\beta}\frac{\varepsilon^{1+\beta}}{\delta^{\beta}}\right],
\end{align*}
where $\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}>0$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:02.087558+00:00","domain":"probability theory","id":"claim_d8e71184fb78c426627600ac55d15bd231c4361ca72388f0e9a2fec2728353dd","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2604.25769, 'The conformal dimension of the Brownian tree is one'] For each $\eta > 0$, there exists a metric $D_\sigma$ on $X$ and a constant $C > 0$ such that the identity mapping $\mathrm{id} \colon (X, D) \to (X, D_\sigma)$ is quasisymmetric and
