{"assumptions":[],"created_at":"2026-10-27T07:21:06.856811+00:00","domain":"probability theory","id":"claim_d918681c976b21d29d77ba2634086fad0d29c82594724453f8aea331a815b963","kind":"theorem","schema_version":1,"statement":"[Corollary 31 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] The following assertions hold:
    \begin{enumerate}
        \item Let $d\in\{1,2\}$, suppose that Assumption~\ref{assumption_weak_setting} and Assumption~\ref{Assumption:noise}\ref{assumption:hg2} holds, assume that $(p,\kappa,s,q)$ are as in Theorem~\ref{lwp:rough:initial:data}\ref{it:lwp:rough:initial:data:2}. Then for all $u_0\in L^0_{\F_0}(\Omega;\,_\nu B_{q,p}^{2-s-4\frac{1+\kappa}{p}}(\sO))$ there exists a global solution to~\eqref{SCH}, which is unique in the class $L^p_\loc([0,\infty),w_\kappa;\bpsn{2-s,q}).$
        \item Let $d\in\{3,4\}$, suppose that Assumption~\ref{assumption_weakened_setting} holds,  assume that $(p,\kappa,s,q)$ are as in Theorem~\ref{lwp:rough:initial:data}\ref{it:lwp:rough:initial:data:4}. Then for all $u_0\in L^0_{\F_0}(\Omega;\,_\nu B_{q,p}^{3-s-4\frac{1+\kappa}{p}}(\sO))$ there exists a global solution to~\eqref{SCH}, which is unique in the class $L^p_\loc([0,\infty),w_\kappa;\bpsn{3-s,q}).$
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.325639+00:00","domain":"probability theory","id":"claim_d9188b48ee9323390ceb5f9da2ecbd664eab465d3c21323bd20c57fc6cf9671d","kind":"lemma","schema_version":1,"statement":"[Lem 5 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Under assumptions $(H2)$--$(H4)$, there exist constants $\a_0, v, \g_{*}>0$ depending only on $\varpi,b_1,\zeta,\k$ such that for every $\a\in(0,\a_0]$ and the premetric 
      \begin{align}
        \theta_\alpha(x, y):=p(x, y)^\alpha e^{\alpha v U(x)}, \quad x,y\in E,
      \end{align}
      the following conclusions hold:
      \begin{enumerate}
        \item[(1)] There exists $C_{\a}\geq 1$, such that for any $x,y\in E$,
        \[ \mathbf{E} \theta_\alpha\left(X_t^\sigma, Y_t^\sigma\right)\leq A_t(\s)\theta_\alpha(x, y),\]
        and 
      \[d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq B_t(\s)\theta_\alpha(x, y),\]
        where 
        \begin{align}
          A_t(\s) = C_{\a}e^{-\a\chi_{t}(\s)}, \quad B_{t}(\s) = C_{\a}\left(\int_0^{t}b_3(\beta_s\s)e^{-\chi_s(\s)}ds\right)^{\a}
        \end{align}
        with 
        \[\chi_t(\sigma) = \zeta t- \frac{\k}{\varpi-\g_{*} b_1}\int_0^t\left(b(\beta_s\s)+\g_{*} b_2(\beta_s\s)\right)ds.\]
        \item[(2)] For any $B\subset E$ such that $U$ and $p$ are bounded on $B$ and $B\times B$, and any $t\geq0$, there is  $C_{\a,B}>0$ such that for any $x,y\in B$, one has 
        \[d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq 1-\bar{\varepsilon}_{\a}(C_{\a,B}B_{t}(\s)),\]
        and 
        \[\mathbf{E} \theta_\alpha\left(X_t^\sigma, Y_t^\sigma\right) \leq C_{\alpha,B} A_{t}(\s),\]
        where $\bar{\varepsilon}_{\a}$ is the function from $(H4)$. 
      \end{enumerate}","status":"unverified"}

