{"assumptions":[],"created_at":"2026-10-28T02:47:21.611103+00:00","domain":"probability theory","id":"claim_d939b26d6a978bd73ae31007c10734d0b655ab36f9aff67785405396ef17dab2","kind":"concept","schema_version":1,"statement":"[Proposition thm:assoc-game of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip

\begin{enumerate}[(i)]
\item A global Markovian pure Nash equilibrium $(\tilde\tau_1^*,\tilde\tau_2^*)$, whose value corresponds to a continuous function $V: {\cal I}\rightarrow \mathbb{R}$, exists. 
More precisely,  
\begin{align*}
 \tilde \tau_i^*= \inf\{t \geq 0: X_t \in D_i^{*}\}, \enskip i=1,2,
\end{align*}
where
\begin{align}
\begin{split}
D_1^{*}:&=\{x \in {\cal I}: \tilde f(x)=V(x)\},\\
D_2^{*}:&=\{x \in {\cal I}: \tilde g(x)=V(x)\}.
\end{split}
\end{align}
Moreover, $\tilde f(x)\leq V(x) \leq\tilde g(x)$, for each $x \in {\mathcal I}$.

\item  For $x \in B^{g \leq f} \supseteq  {B^{g\leq h \leq f}} \cup {B^{h<g<f}} \cup {B^{g<f<h}} $, it holds that $V(x) = \tilde f(x)=\tilde g(x)$. 
Moreover, in equilibrium both players stop on $B^{g \leq f}$; in particular, 
\begin{align}
{B^{g\leq h \leq f}} \cup {B^{h<g<f}} \cup {B^{g<f<h}} \subseteq B^{g \leq f} \subseteq  D_i^{*} , \enskip i =1,2.
\end{align} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.976631+00:00","domain":"probability theory","id":"claim_d93a3b759c2643318d9ee9fab4ba7099b3a800d0e932ba935670c7df9d178d75","kind":"concept","schema_version":1,"statement":"[Lemma lem:supportzeta of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix $\tau\in\mathcal{T}$, ${\eps,\mu}\in(0,1]$ and $s^\tau\in\R^{\mathfrak{s}(\tau)}$. For all $t\in (2\mu{\mathfrak{o}}(\tau),1]$, it holds
    \begin{equs}
        \zeta^\tau_{\eps,\mu}(t,s^\tau)=\xi^\tau_{\eps,\mu}(t,s^\tau)\,.
    \end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.276546+00:00","domain":"probability theory","id":"claim_d944a92048e18e33337c0f9e611f33ccdc3718202f4519b8cea76570bf2d177b","kind":"definition","schema_version":1,"statement":"[Definition 6 (Hyperbolically completely monotone functions) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] A positive function \(f\) on \((0,\infty)\) is hyperbolically completely monotone (HCM) if for every \(u>0\), the function
\begin{equation}
v\mapsto f(uv)f(u/v)
\end{equation}
is completely monotone as a function of
\begin{equation}
w=v+v^{-1}.
\end{equation}
Equivalently, for every \(u>0\), the function
\begin{equation}
H_u(w)=f(uv(w))f(u/v(w)),
\qquad
v(w)=\frac{w+\sqrt{w^2-4}}2,
\qquad w>2,
\end{equation}
satisfies
\begin{equation}
(-1)^n\frac{\dd^n}{\dd w^n}H_u(w)\ge0
\end{equation}
for all \(n\ge0\) and all \(w>2\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.257824+00:00","domain":"probability theory","id":"claim_d94887d089eb2c820a5528b567ff773053b82bb9108f82777067cc8120748639","kind":"concept","schema_version":1,"statement":"[Prp 69 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For $f,\;g\in C_c^{+}(\R_{\ge 0})$, we have 
  \begin{align*}
    d_{\frK}^{\tau,\BL^{\kappa}}(\calT^f,\calT^g)\leq 2\|f-g\|_{[0,\sigma_f\wedge\sigma_g]}+2^{\kappa}(\sigma_f\wedge\sigma_g)\|f-g\|_{[0,\sigma_f\wedge\sigma_g]}^{\kappa}+|\sigma_f-\sigma_g|,
  \end{align*}
  where
  \begin{align*}
    \|f-g\|_{[0,\sigma_f\wedge\sigma_g]}:=\sup_{u\in [0,\sigma_f\wedge\sigma_g]}|f(u)-g(u)|.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.363430+00:00","domain":"probability theory","id":"claim_d9489b6aeb2afdfee92ae5f7577164865e4ee83ce00e94d526d86fdefeee3465","kind":"theorem","schema_version":1,"statement":"[Theorem 2 of arXiv:2506.19273, 'A large deviation view of \emph{stationarized} fully lifted blirp interpolation'] For a positive integer $r\in\mN$ and $k\in\{1,2,\dots,r+1\}$ let vectors $\m=[\m_0,\m_1,\m_2,...,\m_r,\m_{r+1}]$,
$\p=[\p_0,\p_1,...,\p_r,\p_{r+1}]$, and $\q=[\q_0,\q_1,\q_2,\dots,\q_r,\q_{r+1}]$  be such that $\m_0=1$, $\m_{r+1}=0$, $1\geq\p_0\geq \p_1\geq \p_2\geq \dots \geq \p_r\geq \p_{r+1} =0$, and $1\geq\q_0\geq \q_1\geq \q_2\geq \dots \geq \q_r\geq \q_{r+1} = 0$. Assume that the elements of $G\in\mR^{m\times n}$, $u^{(4,k)}\in\mR$, $\u^{(2,k)}\in\mR^m$, and $\h^{(k)}\in\mR^n$ are independent standard normals and set $a_k=\sqrt{\p_{k-1}\q_{k-1}-\p_k\q_k}$, $b_k=\sqrt{\p_{k-1}-\p_{k}}$, $c_k=\sqrt{\q_{k-1}-\q_{k}}$, and ${\mathcal U}_k\triangleq [u^{(4,k)},\u^{(2,k)},\h^{(2k)}]$. Also, assume that sets ${\mathcal X}$, $\bar{{\mathcal X}}$, and ${\mathcal Y}$, scalars  $\beta$, $p$, and $s$, and function $f_{\bar{\x}^{(i_3)} } (\cdot)$ are as in Proposition \ref{thm:thm1} and consider the following function
\begin{equation}
\psi(t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp    \sum_{i_3=1}^{l} \lp \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}\rp^p\rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where
\begin{eqnarray}
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3)}} \rp^{s} \nonumber \\
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T\lp\sum_{k=1}^{r+1}b_k\u^{(2,k)}\rp\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}a_ku^{(4,k)}\rp +\sqrt{1-t}\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T\x^{(i)}
 + f_{\bar{\x}^{(i_3)} } (\x^{(i_1)}). \nonumber \\
 \end{eqnarray}
For  $\zeta_k$ given in (\ref{eq:rthlev2genanal7a}) and (\ref{eq:rthlev2genanal7b})   set
\begin{eqnarray}
 \Phi_{{\mathcal U}_1}^{(i_3)} & \triangleq &  \mE_{{\mathcal U}_{1}} \frac{  Z_{i_3}^{\m_1}  } {  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1}  } \nonumber \\
 \Phi_{{\mathcal U}_k} & \triangleq &  \mE_{{\mathcal U}_{k}} \frac{\zeta_{k-1}^{\frac{\m_k}{\m_{k-1}}}}{\zeta_k} ,k\geq 2 \nonumber \\
 \gamma_{00}(i_3) & = &
\frac{  \lp  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1} \rp^p   }  { \sum_{i_3=1}^{l} \lp  \mE_{{\mathcal U}_{1}} Z_{i_3}^{\m_1} \rp^p   } \nonumber \\
 \gamma_0(i_1,i_2;i_3) & = &
\frac{(C_{i_3}^{(i_1)})^{s}}{Z_{i_3}}  \frac{A_{i_3}^{(i_1,i_2)}}{C_{i_3}^{(i_1)}} \nonumber \\
\gamma_{01}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \gamma_{00}(i_3) \Phi_{{\mathcal U}_1}^{(i_3)} (\gamma_0(i_1,i_2;i_3))  \nonumber \\
\gamma_{02}^{(r)}  & = & \prod_{k=r}^{2} \Phi_{{\mathcal U}_k}   \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   (\gamma_0(i_1,i_2;i_3)\times \gamma_0(i_1,p_2;i_3)) \nonumber \\
 \gamma_{1}^{(r)}  & = & \prod_{k=r}^{2} \Phi_{{\mathcal U}_k}   \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   (\gamma_0(i_1,i_2;i_3)\times \gamma_0(p_1,p_2;i_3)) \nonumber \\
\gamma_{2}^{(r)} \triangleq \gamma_{21}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \lp
  \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times
    \gamma_{00}(p_3)    \Phi_{{\mathcal U}_1}^{(p_3)}
  \gamma_0(p_1,p_2;p_3) \rp  \nonumber \\
\gamma_{22}^{(r)}  & = & \prod_{k=r}^{2}\Phi_{{\mathcal U}_k} \lp
  \gamma_{00}(i_3)  \lp  \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times
     \Phi_{{\mathcal U}_1}^{(i_3)}
  \gamma_0(p_1,p_2;i_3) \rp \rp \nonumber \\
\gamma_{k_1+1}^{(r)}  & = & \prod_{k=r}^{k_1+1}\Phi_{{\mathcal U}_k} \lp \prod_{k=k_1}^{2}\Phi_{{\mathcal U}_k}
  \gamma_{00}(i_3)    \Phi_{{\mathcal U}_1}^{(i_3)}   \gamma_0(i_1,i_2;i_3)\times \prod_{k=k_1}^{2} \Phi_{{\mathcal U}_k}
    \gamma_{00}(p_3)    \Phi_{{\mathcal U}_1}^{(p_3)}
  \gamma_0(p_1,p_2;p_3) \rp, k_1\geq 2. \nonumber \\
 \end{eqnarray}
Also, let
\begin{eqnarray}
\phi^{(1,\p)} & = &
  -(1-t)\lp \m_{1}-\m_{2}\rp p \mE_{G,{\mathcal U}_{r+1}} \langle \|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2(\y^{(p_2)})^T\y^{(i_2)} \ra","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:31:20.594615+00:00","domain":"probability theory","id":"claim_d949c4b15961d823b73856fa6fc3ab2f7b88b2bdb01521f1ee900d02cfab5761","kind":"concept","schema_version":1,"statement":"[Theorem 7 (Fast regret of online MYULA) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under the same assumptions of \cref{thm:linear-statistical}, the approximate posterior computed by \cref{alg:proximal} satisfies
