\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.955542+00:00","domain":"probability theory","id":"claim_d9745db31a556371176de74ab9c1900f6e66b038595d563befac79b56f6ed652","kind":"theorem","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] Consider large $n,m\in\mN$ such that $\lim_{n\rightarrow\infty}\frac{m}{n}\rightarrow\alpha\geq 1$ and let $A_{ij}\sim \cN(0,1)$ be the independent elements of $A\in\mR^{m\times n}$. For a real scalar $c_3\geq 0$ set
  \begin{eqnarray}

 \hat{\gamma}_{1} & = &  \frac{c_3 + \sqrt{c_3^2+4\alpha}}{4}
 \nonumber \\
 \phi_{1}(\gamma_1) & = &  \gamma_{1}c_3 - \frac{\alpha}{2}\log \lp 1 - \frac{c_3}{2 \gamma_{1}}   \rp
 \nonumber \\
 \hat{\gamma}_{2} & = &  \frac{c_3 + \sqrt{c_3^2+4}}{4}
 \nonumber \\
 \phi_{2}(\gamma_2) & = &  \gamma_{2}c_3 - \frac{1}{2}\log \lp 1 - \frac{c_3}{2 \gamma_{2}}   \rp.
 \end{eqnarray}
 Let $\xi^+_{sph}$ be as in (\ref{eq:inteq1ab0}) and for a real scalar $u\geq \mE \xi^+_{sph}$ set
 \begin{eqnarray}

 \nonumber \\
 \phi_u(u) & = & -\frac{c_3^2}{2} + \phi_{1}(\hat{\gamma}_1) + \phi_{2}(\hat{\gamma}_2) -c_3 u .
 \end{eqnarray}
One then has the following LDP with the indicator rate function $\zeta_u(u)$
\begin{eqnarray}

\lim_{n\rightarrow \infty} \frac{\log\lp \mP\lp \xi^+_{sph} \geq u  \rp \rp}{n} \leq \min_{c_3\geq 0}\phi_u(u) \triangleq -\zeta_u(u).
\end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.279719+00:00","domain":"probability theory","id":"claim_d975c4522cc1f4746fcdf412bc83e51d08d8c4c5bfe0206b1096825b8663b011","kind":"concept","schema_version":1,"statement":"[Prop eq:lesmom of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Let $p \geq 1$, and under the \hyperlink{ren}{renormalized setting}, assume in addition that
