{"assumptions":[],"created_at":"2026-10-28T00:32:56.082193+00:00","domain":"probability theory","id":"claim_d9c803b67f63c45635a864b400ec9c5777ec8581ab8e1f93fbc140857720d4da","kind":"theorem","schema_version":1,"statement":"[Proposition PropAbsolContinModel of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let $i,j\in\mathcal{Z}$, $j \neq i$. The following conditions are equivalent:
\begin{itemize}
	\item[(a)] $\Lambda^{ij}$ is left-differentiable everywhere and continuously differentiable in between jump times of $Z${.}
	\item[(b)] The process $\mu^{ij}$ defined by 
	\begin{align*}
		\mu^{ij} (t) :=  \lim_{s \uparrow t } \frac{\mathbb{P}_{s}^i[Z(t)=j]}{t-s}, \quad t \in (0,\infty), 
	\end{align*}
	exists, is continuous in between jump times of $Z$, and satisfies the equation
	\begin{align*}
		\mu^{ij} (t) =   \lim_{u \downarrow t } \frac{\mathbb{P}_{t}^i[Z(u)=j]}{u-t}, \quad Z(t-)=Z(t),
	\end{align*}
	assuming that this limit exists.
\end{itemize}
Under both conditions, we moreover have 
\begin{align*}
	\Lambda^{ij}(\mathrm{d} t ) = \mu^{ij} (t)  \mathrm{d} t, \quad t \in [0,\infty).
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.682623+00:00","domain":"probability theory","id":"claim_d9cb44e2c6cdbca93c53b63389bcb3e0d9f5ed4427f3ab72ac008a03a20e5b92","kind":"concept","schema_version":1,"statement":"[Corollary coro:logsogen of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] For $a\in\mathcal{H}^{\beta,\theta}_K(\mathbb{R}^d,\mathbb{R})$ with $\beta\geq 0$, $\theta>1$ and $K>0$, define the probability measure $\mu$ having a density $d\mu(x) = \exp(-\|x\|^2/2+a(x)+c_a)dx$ with respect to the $d$-dimensional Lebesgue measure (with $c_a\in \mathbb{R}$ a normalizing constant). Then, for all $k\in \{1,...,\lfloor \beta \rfloor +1\}$, and $f:\mathbb{R}^d\rightarrow \mathbb{R}$ with $\|f\|_{L_{\mu}^2}=1$ we have
\begin{align*}
    \int |f(x)|^2|\log(|f(x)|)|^{k}d\mu\leq C \sum_{|\alpha|=0}^k\|D^\alpha f\|^2_{L_{\mu}^2}.
\end{align*}
\begin{proof}
    From Theorem (theo:wsobo of the paper) with $\phi(x)=\frac{\|x\|^2}{2}$, we have for all $g:\mathbb{R}^d\rightarrow \mathbb{R}$ with $\|g\|_{L_2(\gamma_d)}=1$
    \begin{align*}
    \int |g(x)|^2|\log(|g(x)|)|^{k}d\gamma_d(x)\leq C \sum_{|\alpha|=0}^k\|D^\alpha g\|^2_{L^2_{\gamma_d}}.
\end{align*}
Then, from Theorem (theo:thetheo of the paper), there exists a map $T\in C^{\lfloor \beta \rfloor+1}(\mathbb{R}^d,\mathbb{R}^d)$ with $\nabla T\in  \mathcal{H}^{\beta}_C \color{black} (\mathbb{R}^d,\mathbb{R}^d)$ such that
\begin{align*}
    \int |f(x)|^2|\log(|f(x)|)|^{k}d\mu(x)= &  \int |f\circ T(x)|^2|\log(|f\circ T(x)|)|^{k}d\gamma_d(x)\\
    \leq &C \sum_{|\alpha|=0}^k\|D^\alpha (f\circ T)\|^2_{L^2_{\gamma_d}}
    \\
    = &C \sum_{|\alpha|=0}^k\|D^\alpha f\|^2_{L_{\mu}^2}.
\end{align*}
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.420962+00:00","domain":"probability theory","id":"claim_d9d620bfc1b3ce915bd8612db69b38ce4bf66a2713888934bc62ad9f9d5b4cde","kind":"definition","schema_version":1,"statement":"[Definition eq:psi1 of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:subexp}
A real random variable \(\xi\) is \(K\)-subexponential if
\begin{equation}
 \mathbb E\exp(\left\lvert\xi\right\rvert/K)\le2.
\end{equation}
It is \(K\)-sub-Gaussian if \(\mathbb E\exp(\xi^2/K^2)\le2\).  Sub-Gaussianity implies subexponentiality after changing \(K\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.329145+00:00","domain":"probability theory","id":"claim_d9d65b8d28ecaca67e4cecedf9ff96fa2685bfaaf32bb7028deb4cc8a3550f9b","kind":"concept","schema_version":1,"statement":"[Lemma 9 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Set $\bm{\sigma}_1,\bm{\sigma}_2\in\C^2$. Assume $\left(\mathbf{W}_t^{H}\right)_{t\geq 0}\subset \C^2$ to be an fBm with Hurst index $H\in\left(0,1\right)$. Let $\left(\psi_t^{(1)}\right)_{t\geq 0}$ and $\left(\psi_t^{(2)}\right)_{t\geq 0}$ be scalar solutions to the system
\begin{align}
    \begin{split}
        \txtd \psi_t^{(1)} = \alpha\psi_t^{(1)}~\txtd t + \left\langle \txtd \mathbf{W}_t^{H} , \bm{\sigma}_1 \right\rangle,\\
        \txtd \psi_t^{(2)} = \beta \psi_t^{(2)}~\txtd t + \left\langle \txtd \mathbf{W}_t^{H} , \bm{\sigma}_2 \right\rangle,
    \end{split}
\end{align}
each initial conditions at $t=0$ in $\C$. Lastly, consider $\alpha,\beta\in\C$ with negative real part. Then, for all $\tau\ge0$, we obtain that
\begin{align}
    &\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(2)} \right)
    = H \underbrace{\left\langle \bm{\sigma}_2, \bm{\sigma}_1 \right\rangle}_{\text{masking}} \underbrace{P(\alpha,\beta,H,\tau)}_{\text{memory}} \underbrace{\left( -\alpha - \overline{\beta} \right)^{-1}}_{\text{mitigation}},
\end{align}
with $P$ introduced in \eqref{eq:function_P}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

