{"assumptions":[],"created_at":"2026-10-27T06:02:34.817026+00:00","domain":"probability theory","id":"claim_da947564a5b829a1732557a631cc175a4c162cee12de063ab13e8befdfc24849","kind":"lemma","schema_version":1,"statement":"[Lemma 3 (Chain-compatible cutoffs) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] Let $\mathsf O\subset\R^{3d}$ be a bounded smooth open set.  After the
reordering
\[
    x^1=r,\qquad x^2=p,\qquad x^3=\theta,
\]
there exist cutoff drifts, indexed by $0\le\delta\le1$,
\[
    B_1^{\mathsf O},B_2^{\delta,\mathsf O}
        \in C_b^\infty\left(\R^{3d};\R^d\right),
    \qquad
    B_3^{\delta,\mathsf O}
        \in C_b^\infty\left(\R^{2d};\R^d\right),
\]
with
\[
    B^{\delta,\mathsf O}(x)
    =\left(
        B_1^{\mathsf O}(x),
        B_2^{\delta,\mathsf O}(x),
        B_3^{\delta,\mathsf O}\left(x^2,x^3\right)
    \right),
\]
such that, for every $x\in\mathsf O$,
\begin{equation}
    B^{\delta,\mathsf O}(x)
    =
    \begin{pmatrix}
        -\gamma x^2-\gamma x^1\\
        -L^{-1}\nabla U(x^3)+\gamma x^1-\delta Lx^2\\
        x^2-\delta\nabla U(x^3)
    \end{pmatrix}.
\end{equation}
Moreover, for every $k\ge0$,
\begin{equation}
    \sup_{0\le\delta\le1}
    \left(
        \left\|B_1^{\mathsf O}\right\|_{C_b^k}
        +\left\|B_2^{\delta,\mathsf O}\right\|_{C_b^k}
        +\left\|B_3^{\delta,\mathsf O}\right\|_{C_b^k}
    \right)<\infty.
\end{equation}
On $\mathsf O$,
\begin{equation}
\begin{aligned}
    J_{x^1}B_2^{\delta,\mathsf O}=\gamma I_{d},
    \qquad
    J_{x^2}B_3^{\delta,\mathsf O}=I_{d}.
\end{aligned}
\end{equation}
The same assertions hold for cutoff drifts $B^{\delta,\mathsf O,*}$ of the
adjoint dynamics, with
\begin{equation}
    B^{\delta,\mathsf O,*}(x)
    =
    \begin{pmatrix}
        \gamma x^2-\gamma x^1\\
        L^{-1}\nabla U(x^3)-\gamma x^1-\delta Lx^2\\
        -x^2-\delta\nabla U(x^3)
    \end{pmatrix},
    \qquad x\in\mathsf O,
\end{equation}
and hence with chain links $-\gamma I_d$ and $-I_d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.279393+00:00","domain":"probability theory","id":"claim_da989923a17c4e1fbd41a27d063c6d9fb8b0c7ab73645eb2b3d24457952d43a6","kind":"theorem","schema_version":1,"statement":"[Corr martingaleutile of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Under the \hyperlink{gen}{general setting}, let $\varphi \in \mathcal{C}^{1,1}_{\omega}(\mathbb{R}^{+} \times \mathbb{R}^{*}_{+})$. Then the process $(\langle \mu_{t}, \varphi_{t} \rangle)_{t \geq 0}$ is a semi-martingale, with for all $t \geq 0$, a finite variation part given by
\begin{align*}
V_{\varphi,t} := & \hspace{0.1 cm} \langle \mu_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t}} \langle \mu_{s}, \Phi_{s}(R_{s},.) \rangle \mathrm{d}s - \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+} }} d(x)\varphi_{s}(x) \mu_{s}(\mathrm{d}x) \mathrm{d}s \\
    &  + \displaystyle{\int_{0}^{t}}\int_{\mathbb{R}^{*}_{+} } b(x)\bigg( \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x)\bigg) \mu_{s}(\mathrm{d}x) \mathrm{d}s,
\end{align*}
with $\Phi$ associated to $\varphi$ as in (equation eq:Phidef of the paper), and a square-integrable martingale part $\heartsuit_{\varphi,t} := \langle \mu_{t}, \varphi_{t} \rangle - V_{\varphi,t} $ whose predictable quadratic variation is given by
\begin{align*}
\langle \heartsuit_{\varphi} \rangle_{t} =  \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}b(x)\bigg[ \varphi_{s}(x_{0})+\varphi_{s}(x-x_{0})-\varphi_{s}(x) \bigg]^{2} \mu_{s}(\mathrm{d}x) \mathrm{d}s + \displaystyle{\int_{0}^{t}\int_{\mathbb{R}^{*}_{+}}}d(x)\varphi_{s}^{2}(x) \mu_{s}(\mathrm{d}x) \mathrm{d}s.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.529919+00:00","domain":"probability theory","id":"claim_da98c390494b57fb0e5bbe1805ce5a1eb3e556b3b16ebc721ff32cdbc069ec7a","kind":"concept","schema_version":1,"statement":"[Lemma 20 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ be a non-zero finite measure and let $\gamma >0$. Consider $\text{DSBM}(\gamma, c)$, $(\Tilde{\mathcal{Y}}_s)_{s \geq 0}$, with initial measure $\Tilde{\mathcal{Y}}_0 = \mu_{\rm a}$. Then the dimension of the range and of the support of $(\Tilde{\mathcal{Y}}_s)_{s \geq 0}$ are those of $\text{SBM}(\gamma)$ given in Proposition \ref{proposition dimension range and support sbm}, i.e. for $s>0$
    \begin{equation*}
        \text{dim}(\text{supp}(\Tilde{\mathcal{Y}}_s)) = 2 \wedge d \hspace{0.25cm} \text{   on   } \{\Tilde{\mathcal{Y}}_s \neq 0\} \hspace{0.25cm} \Tilde{\mathbb{P}}_{\mu_{\rm a}}\text{-a.s.;} \hspace{0.5cm} \text{dim}(\mathcal{R}(\Tilde{\mathcal{Y}})) = 4 \wedge d \hspace{0.25cm} \Tilde{\mathbb{P}}_{\mu_{\rm a}}\text{-a.s.}
    \end{equation*}
    \begin{proof}
        The proof for the upper bounds, i.e. that $\text{dim}(\text{supp}(\Tilde{\mathcal{Y}}_s)) \leq 2 \wedge d$ and $\text{dim}(\mathcal{R}(\Tilde{\mathcal{Y}})) \leq 4 \wedge d$, immediately follows from the fact that $\Tilde{\mathcal{Y}}_s$ is dominated by $\mathcal{X}_s$. The proof for the lower bound for the support uses the same argument as \cite[Theorem IV.7]{le1999spatial} as the following condition is satisfied:
        \begin{equation}
            \Tilde{\mathbb{N}}_b\Big(\int_{\norm{y} \leq K} \int_{\norm{z} \leq K} \Tilde{\mathcal{Y}}_t(dy) \Tilde{\mathcal{Y}}_t(dz) |y-z|^{\varepsilon - 2}\Big) < \infty
        \end{equation}
        For the lower bound for the range, we define the total occupation measure $\Tilde{\mathcal{J}}$ of $\Tilde{\mathcal{Y}}$ by 
        \begin{equation*}
            \langle \Tilde{\mathcal{J}}, g \rangle = \int_{s=0}^\infty ds \langle \Tilde{\mathcal{Y}}_s, g \rangle
        \end{equation*}
        which is supported on $\mathcal{R}(\Tilde{\mathcal{Y}})$. The proof for the lower bound for the range then uses the same argument as in \cite[Theorem IV.7]{le1999spatial} as we have that for $d \geq 4$ and for every $K$, $\varepsilon$, $\delta>0$ that
        \begin{equation}
            \Tilde{\mathbb{N}}_b\Big(\int_{\varepsilon \leq \norm{y - b} \leq K} \int_{\varepsilon \leq \norm{z - b} \leq K} \frac{\mathcal{J}(dy)\mathcal{J}(dz)}{|y-z|^{4-\delta}}\Big) < \infty,
        \end{equation}
        as well as the fact that $\Tilde{\mathcal{Y}}$ is a non-trivial measure-valued process (i.e. a.s. not equal to the zero-measure for a positive initial interval of time $[0,y]$). Both the inequalities in \eqref{equation support inequality lower bound} and \eqref{equation range inequality lower bound} can be seen from a direct comparison with SBM which has the corresponding inequalities in the proof of \cite[Theorem IV.7]{le1999spatial}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

