    \end{equation}
    and that there exists a positive constant $\Theta_T$ and a function $\Pi_T \in L^2([0,T], \R_{\geq 0})$ such that
    \begin{equation}
        |p(t,s,x)-p(t,s,y)| \leq \Pi_T(s)|x-y| + \Theta_T|x-y|(|x|+|y|), \quad x,y \in \C^d, 0 \leq t \leq s \leq T.
