 \Bigg)\times \cdots \nonumber \\
 & \cdots \times \Bigg[ \mathcal{Y}^{(s)}_{\omega}(c_k^{+})\langle \chi_{\frak{p}}\chi_{a_k^{+}} \rangle_{S_{\omega}(s)} - \mathcal{Y}^{(s)}_{\omega}(a_k^{+})\langle \chi_{\frak{p}}\chi_{c_k^{+}} \rangle_{S_{\omega}(s)} ds  \Bigg].\end{align}
Then $\mathbf{P}$-almost surely :
\begin{enumerate}
	\item There exist $T_0(\Lambda,\omega)>0$ such that there exist a solution to the SDE (equation eq:SDE-embedding of the paper) on $[0;T_0(\Lambda,\omega)] $.
	\item For any time $0\leq s \leq T_0 (\Lambda,\omega)$, the propagator $\mathcal{Y}_{\omega}^{(s)} $ (seen as the solution to (equation eq:SDE-embedding of the paper)) is an s-embedding $\mathcal{S}^{(s)}_{\omega}$ of the Ising model $S_{\omega}(s)$.
