{"assumptions":[],"created_at":"2026-10-28T02:16:53.595758+00:00","domain":"probability theory","id":"claim_db714096e06d359b804412c4c4f0597ee9c5a74486c91fe84dc6350ee4c18b88","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] \begin{enumerate}[(i)]
    \item  We say that $(M,d,\mu)$ satisfies the volume doubling property (VD)
  if there exist constants $C \ge 1,d_2 > 0$ such that for all $x \in M$ and all $0 < r \le R$,
  \begin{equation}
    \frac{V(x,R)}{V(x,r)} \le C \left(\frac{R}{r}\right)^{d_2}.
  \end{equation}
  \item   We say that $(M,d,\mu)$ satisfies the reverse volume doubling property (RVD)
  if there exist constants $C > 0,d_1 > 0$ such that for all $x \in M$ and all $0 < r \le R$,
  \begin{equation}
   C \left(\frac{R}{r}\right)^{d_1} \le \frac{V(x,R)}{V(x,r)}.
  \end{equation}
  \end{enumerate}","status":"unverified"}

