{"assumptions":[],"created_at":"2026-10-26T19:17:10.027030+00:00","domain":"probability theory","id":"claim_dbe6961d8605d5a85000e78fef3f344d1346e471ac6adf23d9bb564b4382b307","kind":"theorem","schema_version":1,"statement":"[Theorem 33 of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] Fix $0 < \beta < 1$. Set $m(d)=\lfloor d^\beta\rfloor$ and let $k(d)$ be any sequence satisfying $k(d) \rightarrow \infty$, $\frac{m(d)k(d)}{d} \rightarrow 0$, and $\frac{k(d)}{m(d)} \rightarrow 0$.

Then there exist constants $0<c<C<\infty$ (depending only on $\beta$) such that for all sufficiently large $d$
and all $\varepsilon\in(0,1/4)$,
\begin{equation}
c\,d^{1-\beta}\bigl(\log(k(d))+\log(1/\varepsilon)\bigr)
\;\le\;
\tau_{\mathrm{mix}}^{(k(d))}(d,\varepsilon)
\;\le\;
C\,d^{1-\beta}\bigl(\log(k(d))+\log(1/\varepsilon)\bigr).
\end{equation}
Moreover, the full-chain mixing time satisfies the lower bound
\begin{equation}
\tau_{\mathrm{mix}}(d,\varepsilon)
\;\ge\;
c\,d^{1-\beta}\bigl(\log d+\log(1/\varepsilon)\bigr).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.258231+00:00","domain":"probability theory","id":"claim_dbe8e39028e4330255af511d5408e33f8aff8e87835daa8e896b90bf63fff1d0","kind":"concept","schema_version":1,"statement":"[Corollary 13 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} be valid with $N_{\infty} > 0$. Then for any positive solution $I$ to~\eqref{eq:a representative SIS epidemic model} the following two assertions hold:
\begin{enumerate}[(i)]
\item Assume that there are $a_{\infty}, b_{\infty}, c_{\infty}, d_{\infty}\in\R$ such that
\begin{align*}
\liminf_{s\uparrow \infty} h_{1}\big(s,N(s),\mathcal{L}(I_{s})\big) &\geq a_{\infty}, \quad \liminf_{s\uparrow \infty} h_{2}\big(s,N(s),\mathcal{L}(I_{s})\big) \geq b_{\infty},\\
\liminf_{s\uparrow \infty} h_{3}(s,N(s)) &\geq c_{\infty},\quad \limsup_{s\uparrow \infty} g_{1,1}(s)g_{1,2}(s)\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0})\leq d_{\infty}.
\end{align*}
If $a_{\infty} > d_{\infty}N_{\infty}^{\frac{3}{2}}$, then $I$ persists above the smallest zero $x_{0}$ of $f_{\infty}\colon ]0,N_{\infty}]\rightarrow\R$ defined by
\begin{equation}
f_{\infty}(x) := a_{\infty}+ b_{\infty}x + c_{\infty}x^{2} - d_{\infty}(N_{\infty}-x)^{\frac{3}{2}},
\end{equation}
and $x_{0} < N_{\infty}$ whenever $\gamma_{\infty} + \mu_{\infty} > 0$. Further, for $d_{\infty} = 0$ this zero is of the form $x_{0} = \frac{-b_{\infty}-\sqrt{b_{\infty}^{2}-4a_{\infty}c_{\infty}}}{2c_{\infty}}$, if $c_{\infty} \neq 0$, and $x_{0} = - \frac{a_{\infty}}{b_{\infty}}$, otherwise. 

\item Suppose that there are $\hat{a}_{\infty}, \hat{b}_{\infty},\hat{c}_{\infty},\hat{d}_{\infty}\in\R$ such that
\begin{align*}
\limsup_{s\uparrow \infty} h_{1}\big(s,N(s),\mathcal{L}(I_{s})\big) &\leq \hat{a}_{\infty}, \quad \limsup_{s\uparrow \infty} h_{2}\big(s,N(s),\mathcal{L}(I_{s})\big) \leq \hat{b}_{\infty},\\
\limsup_{s\uparrow \infty} h_{3}(s,N(s)) &\leq \hat{c}_{\infty},\quad \liminf_{s\uparrow \infty} g_{1,1}(s)g_{1,2}(s)\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0})\geq \hat{d}_{\infty}.
\end{align*}
If $\hat{a}_{\infty} \geq \hat{d}_{\infty}N_{\infty}^{\frac{3}{2}}$ and $\hat{a}_{\infty} + \hat{b}_{\infty}N_{\infty} + \hat{c}_{\infty}N_{\infty}^{2} < 0$, then $\liminf_{t\uparrow\infty} I_{t} \leq y_{0}$ a.s.~for the largest zero $y_{0}$ of $g_{\infty}\colon [0,N_{\infty}[\rightarrow\R$ given by
\begin{equation}
g_{\infty}(x) := \hat{a}_{\infty} + \hat{b}_{\infty}x + \hat{c}_{\infty}x^{2} - \hat{d}_{\infty}(N_{\infty}-x)^{\frac{3}{2}}.
\end{equation}
Further, for $\hat{d}_{\infty} = 0$ this zero is unique and of the form $y_{0} = \frac{-\hat{b}_{\infty} - \sqrt{\hat{b}_{\infty}^{2}-4\hat{a}_{\infty}\hat{c}_{\infty}}}{2\hat{c}_{\infty}}$, if $\hat{c}_{\infty} \neq 0$, and $y_{0} = - \frac{\hat{a}_{\infty}}{\hat{b}_{\infty}}$, otherwise.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:33:43.749436+00:00","domain":"probability theory","id":"claim_dbedd431ae7bc7d52e662879591a6101b4817efe61d56381ced792a5c2bec6cd","kind":"definition","schema_version":1,"statement":"[Definition def:sol_nl_fp of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $\nu\in \mathcal{M}(\mathbb{R}^d)$. A measurable flow ${\boldsymbol\mu}:[0,\infty)\to \mathcal{M}(\mathbb{R}^d)$ is a (weak) solution to NL-FP$({\bf b},{\boldsymbol\sigma};\nu)$ if it is a weak solution to FP$({\bf b}_{\boldsymbol\mu},{\boldsymbol\sigma}_{\boldsymbol\mu};0,\nu)$ (see Definition (def:sol_lin_fp of the paper)), with ${\bf b}_{\boldsymbol\mu},{\boldsymbol\sigma}_{\boldsymbol\mu}$ as in (equation eq:def_frozen_coeff of the paper).

