{"assumptions":[],"created_at":"2026-10-27T10:47:32.864597+00:00","domain":"probability theory","id":"claim_dd5874fcffa963a8e54a37cc0bfd9d998b2b842443a494e551564ed3aa8a2825","kind":"theorem","schema_version":1,"statement":"[Theorem 12 of arXiv:2609.02426, 'Deformations of the $\osp(n|2)$-action on the superspace\\ of symbols of differential oper'] Let $n\geq3$, $1\leq k,l\leq m$ and let $\nu,\nu'$ be weights of summands of $\Sc^n_d$. Put
\begin{equation}

\Omega_k:=f_{\lambda_k}\vee h_k=\Delta_1h_k,\qquad\text{i.e.}\qquad
\Omega_k(X_F,X_G)=h_k(X_F)\circ(G'\cdot)-(-1)^{|F||G|}h_k(X_G)\circ(F'\cdot).
\end{equation}
Then
\begin{itemize}
\item[i)] $f_\nu\vee f_{\nu'}=0$;
\item[ii)] $h_k\vee h_l=h_k\vee\widetilde{h}_l=\widetilde{h}_k\vee\widetilde{h}_l=0$;
\item[iii)] $f_\nu\vee h_k=f_\nu\vee\widetilde{h}_k=0$ whenever $\nu\notin\{\lambda_k,\mu_k\}$;
\item[iv)] $f_{\mu_k}\vee h_k=0$;
\item[v)] $f_{\lambda_k}\vee h_k=\Omega_k$, $\quad f_{\lambda_k}\vee\widetilde{h}_k=-\Omega_k$,
$\quad f_{\mu_k}\vee\widetilde{h}_k=\Omega_k$.
\end{itemize}
Moreover $\Omega_k\neq0$; it is reduced, $\Omega_k(X_1,\,\cdot\,)=0$, and
\begin{equation}

\Omega_k(X_x,X_{x\theta_i})=(-1)^{i-1}\,\Ehat{i}\,\partial^{k-1}_x,\qquad 1\leq i\leq n .
\end{equation}
Consequently, in the case $2d=m\in\N$, the space $\Hd^1\vee\Hd^1$ is spanned by the $m$ classes
$[\Omega_1],\dots,[\Omega_m]$, which lie in pairwise different summands of
$\Hd^2(\osp(n|2),\Dc^n_d)$; and in the case $2d\notin\N$ we have $\Hd^1\vee\Hd^1=0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.480235+00:00","domain":"probability theory","id":"claim_dd5ab0e3a4c5965a8f3eaf91b81d771246c8c33a8e667a0ccb25267722348d3a","kind":"concept","schema_version":1,"statement":"[Thm CS results kappa>0 of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] The multiple radial SLE($\kappa$) is described by the partition function $\mathcal{Z}(\boldsymbol{\theta})$, which satisfies the following relation:
\begin{equation}
\mathcal{L}_j \mathcal{Z}(\boldsymbol{\theta}) = h \mathcal{Z}(\boldsymbol{\theta}),
\end{equation}
where $\mathcal{L}_j$ is the null vector differential operator given by:
\begin{equation}
\mathcal{L}_j = \frac{\kappa}{2} \left(\frac{\partial}{\partial \theta_j}\right)^2 
+ \sum_{k \neq j} \left( 
\cot\left(\frac{\theta_k - \theta_j}{2}\right) \frac{\partial}{\partial \theta_k} 
- \frac{6 - \kappa}{2\kappa} \frac{1}{2 \sin^2\left(\frac{\theta_k - \theta_j}{2}\right)}
\right).
\end{equation}

\begin{itemize}
\item[(i)] By transforming the partition function $\mathcal{Z}(\boldsymbol{\theta})$ using the Coulomb gas correlation factor $\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{\theta})$, we obtain:
\begin{equation}
\tilde{\mathcal{Z}}(\boldsymbol{\theta}) = \Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{\theta}) \mathcal{Z}(\boldsymbol{\theta}),
\end{equation}
where
\[
\Phi_r(\boldsymbol{\theta}) = \prod_{1 \leq j < k \leq n} \left(\sin\frac{\theta_j - \theta_k}{2}\right)^{-2r}.
\]

The transformed partition function $\tilde{\mathcal{Z}}(\boldsymbol{\theta})$ satisfies:
\[
\left(\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}\right) \tilde{\mathcal{Z}}(\boldsymbol{\theta}) = h \tilde{\mathcal{Z}}(\boldsymbol{\theta}),
\]
where the differential operator $\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}$ is given by:
\begin{equation}
\begin{aligned}
\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}} = & \frac{\kappa}{2} \partial_j^2 - F_j \partial_j 
+ \frac{1}{2\kappa} F_j^2 - \frac{1}{2} F_j^{\prime} \\
& - \sum_{k \neq j} \left( 
f_{jk} \left(\partial_k - \frac{1}{\kappa} F_k\right) 
- \frac{6 - \kappa}{2\kappa} f_{jk}^{\prime}
\right).
\end{aligned}
\end{equation}

The sum of the null vector differential operators is:
\begin{equation}
\Phi_{-\frac{1}{\kappa}} \cdot \mathcal{L} \cdot \Phi_{\frac{1}{\kappa}} = \kappa H_n\left(\frac{8}{\kappa}\right) - \frac{n(n^2 - 1)}{6 \kappa},
\end{equation}
where $H_n(\beta)$, with $\beta = \frac{8}{\kappa}$, is the quantum Calogero-Sutherland Hamiltonian:
\[
H_n(\beta) = \sum_{j=1}^n \frac{1}{2} \frac{\partial^2}{\partial \theta_j^2} 
- \frac{\beta(\beta - 2)}{16} \sum_{1 \leq j < k \leq n} \frac{1}{\sin^2\left(\frac{\theta_j - \theta_k}{2}\right)}.
\]

\item[(ii)] The commutation relation between the null vector operators $\mathcal{L}_j$ and $\mathcal{L}_k$ is:
\[
[\mathcal{L}_j, \mathcal{L}_k] = \frac{1}{\sin^2\left(\frac{\theta_j - \theta_k}{2}\right)} (\mathcal{L}_k - \mathcal{L}_j).
\]
As a result:
\[
[\mathcal{L}_j, \mathcal{L}_k] \mathcal{Z}(\boldsymbol{\theta}) 
= \frac{1}{\sin^2\left(\frac{\theta_j - \theta_k}{2}\right)} (\mathcal{L}_k - \mathcal{L}_j) \mathcal{Z}(\boldsymbol{\theta}) = 0.
\]
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.692527+00:00","domain":"probability theory","id":"claim_dd5b721ec7b875653a379b8be98be2d5abd1e66cd679c5386cdb2ecf22991fcb","kind":"concept","schema_version":1,"statement":"[Prop p:300.4 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $u > 0$ is sufficiently large, there exist a constant $C_u \in (0,\infty)$ and a coupling of $\mathcal Z_{\rm D}$ from~(equation eq:deflqgm of the paper), $\overline{h}_{\rm D}$ from~(equation e:1.7p of the paper) and a random Radon point measure ${\bf \Gamma}_{\infty,u}$ on ${\rm D}$ satisfying that
