{"assumptions":[],"created_at":"2026-10-27T13:52:23.571115+00:00","domain":"probability theory","id":"claim_dd92f88a7ef9fa200398302c3886ad5c4b4d2b5d5f17e230aa2f379e180ff9a7","kind":"concept","schema_version":1,"statement":"[Theorem T:LND_x of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \index{conditional variance}
  Assume $\alpha > 0$, $\beta \in (0, 2]$, $\gamma \ge 0$, $H \in (0, 1)$, and
  $\ell \in (0, 2d)$. Assume the Dalang condition (equation E:main of the paper), namely, $\rho >
    0$ and $\ell < 2\alpha$. Then, for all $0 < S < T < \infty$ and $1 \le M <
    \infty$, there exist positive finite constants $C = C(S,T,M, \alpha, \beta,
    \gamma, H, d, \ell)$ and $C' = C'(S,T,M, \alpha, \beta, \gamma, H, d, \ell)$
  such that the following statements hold.

  \begin{enumerate}[\rm (i)]

    \item If either $\beta \in (0, 2)$ or $(\beta, \gamma) \in \{2\} \times [1,
            \infty)$, then for all $t \in [S, T]$, for all integers $n \ge 1$, and for
          all $x, x_1, \dots, x_n \in B(0, M) \subset \mathbb{R}^d$, we have
          \begin{align}
            \ensuremath{\mathrm{Var} }\left(u(t, x)\big|u(t, x_1), \dots, u(t, x_n)\right)
            \ge C \min_{1 \le j \le n}|x-x_j|^{2\tilde\rho_1},
          \end{align}
          and for all $t \in [S, T]$, for all $x, y \in B(0, M)$, we have
          \begin{align}
            \mathbb{E}\left[\left(u(t, x) - u(t, y)\right)^2\right] \ge
            \begin{cases}
              C'|x-y|^{2\tilde\rho_1} & \text{if } \tilde\rho_1 \in (0, 1), \\
              C'|x-y|^2 (1+|\log|x-y||)                            & \text{if } \tilde\rho_1 = 1,        \\
              C'|x-y|^2                                            & \text{if } \tilde\rho_1 > 1.
            \end{cases}
          \end{align}

    \item If $\beta = 2$ and $\gamma \in [0,1)$, then for all $t \in [S, T]$,
          for all integers $n \ge 1$, for all $x, x_1, \dots, x_n \in B(0, M)
            \subset \mathbb{R}^d$, we have
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x) \big| u(t, x_1), \dots, u(t, x_n) \right) \ge C \min_{1\le j \le n}|x-x_j|^{2\tilde\rho_2},
          \end{align}
          and for all $t \in [S, T]$, for all $x, y \in B(0, M)$, we have
          \begin{align}
            \mathbb{E}\left[ \left( u(t, x) - u(t, y) \right)^2\right] \ge
            \begin{cases}
              C' |x-y|^{2\tilde\rho_2} & \text{if } \tilde\rho_2 \in (0, 1), \\
              C' |x-y|^2 (1+|\log|x-y||)           & \text{if } \tilde\rho_2 = 1,        \\
              C' |x-y|^2                           & \text{if } \tilde\rho_2 > 1.
            \end{cases}
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.442562+00:00","domain":"probability theory","id":"claim_dd9674c4e9f5cf1c2683d9a027a7a883f6b05ae7c9f8a8383971cb7fe33e5e13","kind":"lemma","schema_version":1,"statement":"[Lem 5. lem: pcpt of aging functions near diagonal of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] For every $l \in \mathbb{N}$ and $\eta > 0$,
