           \\ &\qquad \qquad\qquad\qquad = \mathbb{P}_2\left[O_n \cap \left\{ \frac{1}{|S_n||X_0-X_3|}\in [2^k, 2^{k+1})\right\}\right].
            \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:01:15.327825+00:00","domain":"probability theory","id":"claim_dffcd9bd2784134cca70fd9c74c34d7f436d05d04a9f62c85b54718914815e89","kind":"definition","schema_version":1,"statement":"[Defi 3 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $p \in (0, \infty)$. A collection $\{X^n_s : s\in S_n, n \ge 1\}$ of $\cX$-valued random elements is  \textit{$(\nu_n)$-compactly uniformly $p$-th order integrable} (or $(\nu_n)$-$\CUI(p)$, for short) if:
	\begin{enumerate}[\rm (a)]
		\item the map $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF \otimes \cS_n/\cB(\cX)$-measurable for every $n \ge 1$,

		\item for any $\ep >0$, there exists $K_\ep \in \cK(\cX)$ such that
		\begin{align*}
			 \sup_{n \ge 1} \bE\int_{S_n} \lt\|X^n_s\rt\|^p \1_{\{X^n_s \notin K_\ep\}} \nu_n(\od s)  \le \ep.
		\end{align*}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.317280+00:00","domain":"probability theory","id":"claim_e0070fec2997342eb4533d0c2559580cb5e94ab7ac42f9b1f5737b5282362e06","kind":"theorem","schema_version":1,"statement":"[Theorem fplinax of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] Let $ X_t $ be the solution of ((mSDEline of the paper)). If $ A_t, B_t $ and $ C_t $ satisfy the conditions of Lemma (Malianx of the paper). Then the memory-dependent PDEEs for PDFs $ p(x,t) $ of the solutions $ X_t $, satisfies the following equation
