\end{align}

\item For every $t \in \mathbb{R}$, the series $\mathcal{Z}_{t}^{\chi_{f}}$ converges unconditionally in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$ and almost surely over every admissible ordering of $\mathcal{I}$. Moreover, for all $t \in \mathbb{R}$, $\mathbb{E}[\chi_{f}(t)] = 0$ and  
\begin{align}
\mathcal{Z}_{t}^{f} - m^{f}_{t} \stackrel{a.s.}{=}  \mathcal{Z}_{t}^{\chi_{f}}. 
\end{align}

\item For $n \in \mathbb{N}_{0}$ and $t \in \mathbb{R}$, 
\begin{align}
\sum_{0\leq |u| \leq n} \chi_{f, u}(t - S(u)) \stackrel{a.s.}{=}  \sum_{0\leq |u| \leq n} f(t - S(u)) - f \ast \nu^{(\infty)}(t) + \sum_{|u| = n+1} f \ast \nu^{(\infty)}(t - S(u)). 
