{"assumptions":[],"created_at":"2026-10-26T20:55:18.060547+00:00","domain":"probability theory","id":"claim_e21d2920cd98fd47d2f5349adf072400520efc45d9be2b1139ddb1d92630feac","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2606.17381, 'Large deviation principle for friendship-biases\\ in Galton--Watson trees'] {\bf [Vertex types]}
$\mbox{}$
\begin{itemize}
\item[{\rm (a)}] 
{\rm A vertex $u \in V(\Tt_\infty)$ is called a \textit{branching point} if $X_u = 2$.}
\item[{\rm (b)}] 
{\rm A vertex $u \in V(\Tt_\infty) \setminus \{\phi\}$ with $d_u = 2$ is called a \textit{linear point} if its parent is not a branching point, and a \textit{branching-linear point} if its parent is a branching point.}
\item[{\rm (c)}] 
{\rm A \emph{linear piece} from a vertex $v$ is the maximal path
\[
v = v_0 \to v_1 \to \cdots \to v_{\ell(v)} = \tau(v),
\]
where the terminal vertex $\tau(v)$ is the first branching point on the path, i.e. $X_{\tau(v)} = 2$. The random integer $\ell(v)\in\mathbb N_0$ is called the \emph{length} of the linear piece from $v$.}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.439029+00:00","domain":"probability theory","id":"claim_e21de92fd3cc38c969f43b5af9d4679764d2b096c979eb45baf53052eccd1e11","kind":"definition","schema_version":1,"statement":"[Defn 15 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] For $0<\A{1},\A{2}\leq 1$ such that $h\ll  \pr{\A{1}\A{2}}^{1/2}$, and $m$ an order function on $\mc{T}_{\A{1},\A{2}}$, $\eta_1,\eta_2\in [0,1/4]$, we set $\Tilde{h}=h/\sqrt{\alpha_1\alpha_2}$ and define
\begin{enumerate}
    \item $S(m,\alpha_1,\A{2})$ as the set of $p\in \mathscr{C}^{\infty}(\mc{T}_{\A{1},\A{2}})$ such that for all $\beta,\gamma\in \N^d$, there exists $C_{\beta,\gamma}>0$ (uniform with respect to $\Tilde{h}$) satisfying: for all $(x,\xi)\in \mc{T}_{\A{1},\A{2}}$,
    \begin{equation*}
        \bb{\partial^\beta_x\partial^\gamma_\xi p(x,\xi)}\leq C_{\beta,\gamma}m(x,\xi),
    \end{equation*}
    \item $S_{\eta_1,\eta_2}(m,\alpha_1,\A{2})$ as the set of $p\in \mathscr{C}^{\infty}(\mc{T}_{\A{1},\A{2}})$ such that for all $\beta,\gamma\in \N^d$, there exists $C_{\beta,\gamma}>0$ (uniform with respect to $\Tilde{h}$) satisfying: for all $(x,\xi)\in \mc{T}_{\A{1},\A{2}}$,
    \begin{equation*}
        \bb{\partial^\beta_x\partial^\gamma_\xi p(x,\xi)}\leq C_{\beta,\gamma}\Tilde{h}^{-\bb{\beta}\eta_1-\bb{\gamma}\eta_2}m(x,\xi).
    \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:46:25.365670+00:00","domain":"probability theory","id":"claim_e2215321fcae63fe15a7601afb376b887e7565c3d782eadab89b8413075c329c","kind":"theorem","schema_version":1,"statement":"[Prop parallel of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $V\in\mathfrak{C}$ and let $x,y,z_1,\ldots,z_M\in V$ such that $x$ and $y$ are separated in $\mathcal{X}\cap\overline{V}\setminus\{z_1,\ldots,z_M\}$. Let $K_x$ be the connected component of $\mathcal{X}\cap\overline{V}\setminus\{z_1,\ldots,z_M\}$ containing $x$, and let $V_x \in \mathfrak{C}$ be the smallest region 
such that $\overline{V_x} \supseteq K_x$.\footnote{In other words, $\overline{V_x}$ is the union of $\overline{K_x}$ with the components bounded by the loops within $\overline{K_x}$.} Then 
\begin{equation}
    \mathfrak{d}_V(x,y)\geq\frac{1}{M}\min_i\mathfrak{d}_{V_x}(x,z_i).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.817568+00:00","domain":"probability theory","id":"claim_e2215394d1589ec751799927be55837697b2a710516749256f2359e82c53b745","kind":"concept","schema_version":1,"statement":"[Lemma 28 of arXiv:2608.12804, 'Scaling Limits for Ising Models on Inhomogeneous Random Graphs and Applications'] For all $\bs \in \{-1,+1\}^N$, as long as $\theta_N = \Omega(N^{-2/3})$, we have:
    \begin{multline*}
        \E T\left(\bs\right) = \exp\left(-\frac{\beta^2}{4N^2\theta_N}\sum_{i=1}^{N}W\left(\frac{i}{N},\frac{i}{N}\right)
        -\frac{\beta^2}{2N^2}\sum_{i> j}W^2\left(\frac{i}{N},\frac{j}{N}\right)-\frac{\beta^4}{12 N^4\theta_N^3}\sum_{i> j} W\left(\frac{i}{N},\frac{j}{N}\right)\right.\\
        \left.+o\left(\frac 1{N\theta_N}\right)+\frac{\beta}{N}\sum_{i> j}W\left(\frac{i}{N},\frac{j}{N}\right)\sigma_i \sigma_j + O\left(\frac{1}{N^3 \theta_N^2}\left|\sum_{i>j}W\left(\frac{i}{N},\frac{j}{N}\right)\sigma_i \sigma_j\right| \right)\right).
    \end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.581327+00:00","domain":"probability theory","id":"claim_e223779cdc13a0e6697024a26546bc6f1b41ae70a872c9683d0ced4a6c8dfa69","kind":"concept","schema_version":1,"statement":"[Proposition Prop.LowerBound of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For each $\beta>\beta_0$, there exist constants $n_0\geq 1$ and $C\geq 0$ such that for any $z\in \mathbb{R}$, 
 \begin{eqnarray}
  \inf_{n\geq n_0} \bigg|1-\int_0^\infty e^{\mathtt{i}zt -\frac{\beta}{n}  t} \cdot \gamma_n \overline\varPi_n(t)\, dt\bigg| \geq C  \cdot \big( |z|\wedge 1 \big).
 \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:30:50.730635+00:00","domain":"probability theory","id":"claim_e2257c30bb9e5a6df68c10cde70a4753ac91fe141bee8b31ab995213695417f1","kind":"lemma","schema_version":1,"statement":"[Lem estimate of arXiv:2503.22334, 'Probabilistic analysis of optimal multi-pivot QuickSort'] For all $0 \le L<\infty$ exists an $M_L<\infty$ such that for all $\lambda \in [-L,L]$ and all $n \ge 0$ we have
    \begin{align}
