{"assumptions":[],"created_at":"2026-10-28T01:16:46.753805+00:00","domain":"probability theory","id":"claim_e23a170882e945188435b9f833b2bd7e9face1accac29c3303834282a3227607","kind":"theorem","schema_version":1,"statement":"[Theorem prop:chfuntheta of arXiv:2411.19192, 'Characteristic function and Esscher transform of a switching Levy model for the temperatur'] Under the probability $\mathcal{Q}^{\theta}$ defined by the Esscher transform  in equation ((eq:esscher of the paper)) and the condition $\lambda_{21} > \lambda_{12} > \theta$ the characteristic function of the temperature process is given by:
 \begin{eqnarray}
        \varphi^{\theta}_{T_t}(u)&=& \exp[iu C_1(t, \alpha)]  C_4(u, \theta)C_5(u,\theta)
 \end{eqnarray}
where:
\begin{eqnarray*}
 D(m,n,l, \theta)&=& \frac{(\lambda^{ m}_{12}-\theta)}{(\lambda^{ n}_{21}-\theta) \Gamma(l)}, \; l \geq 1 \\
C_2(u, \theta, k) &=& (\lambda_{12}-\theta)^k (\lambda_{21}-\theta)^k (J^{\theta}_1(u)J^{\theta}_2(u))^k \\
C_3(u, \theta, k) &=& p^{\theta}_{2k}(t)+ (\lambda_{12}-\theta)J^{\theta}_1(u) p^{\theta}_{2k+1}(t)\\
C_4(u, \theta) &=& \sum_{k=0}^{+\infty}  C_2(u, \theta,k) C_3(u, \theta, k)\\
C_5(u,\theta) &=& \sum_{k=0}^{+\infty}   J^{\theta}_3(u,k)  p^{\theta}_{2k}(t) +  \sum_{k=0}^{+\infty}   J^{\theta}_4(u,k)p^{\theta}_{2k+1}(t) \\
\end{eqnarray*}
\begin{equation*}
  g_j(u,s, \theta)=-iu \mu^j_1 \sigma e^{-\alpha (t-s)} +  \mu^j_1 \theta +\frac{1}{2}(-i u\sigma e^{- \alpha (t-s)}+\theta)^2
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:55:27.268607+00:00","domain":"probability theory","id":"claim_e24e09f33b6f36eff685165ee155dcd0352138d5dd83b2c5154347ba6e73ed11","kind":"definition","schema_version":1,"statement":"[Definition ParScale of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] We assume that $c^+$, $\{a_i^+\}_{ i \geq 1}$, $\{b_i^+\}_{ i \geq 1}$ are non-negative reals such that
\begin{equation}
\sum_{i = 1}^{\infty} (a_i^+ + b_i^+ ) < \infty \mbox{ and } a_{i}^{+} \geq a_{i+1}^{+},  b_{i}^{+} \geq b_{i+1}^{+} \mbox{ for all } i \geq 1.
\end{equation}
We let $J_a^{+} = \inf \{ k \geq 1: a_{k}^{+} = 0\} - 1$ and $J_b^{-} = \inf \{ k \geq 1: b_{k}^{-} = 0\} - 1$. In words, $J_a^{+}$ is the largest index $k$ such that $a_{k}^{+} > 0$, with the convention that $J_a^{+} = 0$ if all $a_k^{+} = 0$ and $J_a^{+} = \infty$ if all $a_k^{+} > 0$, and analogously for $J_b^{+}$. We fix $q \in (0,1)$ and set
\begin{equation}
\sigma_q = \frac{q^{1/3} (1 + q)^{1/3}}{1- q} \mbox{ and } f_q = \frac{q^{1/3}}{2 (1 + q)^{2/3}}.
\end{equation}
For $N \in \mathbb{N}$ increasing to infinity, we consider three numbers $A_N, B_N, C_N^{+}$ and sequences $\{x^N_i \}_{ i\geq 1}$ and $\{y^N_i\}_{i \geq 1}$ such that
\begin{equation}
\begin{split}
&x_i^N =1 - \frac{1}{N^{1/3} b_i^+ \sigma_q } \mbox{ for $i = 1, \dots, B_N$, and } y_i^N =1 -\frac{1}{N^{1/3} a_i^+ \sigma_q } \mbox{ for $i = 1, \dots, A_N$},
\end{split}
\end{equation}
where $B_N \leq \min\left(\lfloor N^{1/12} \rfloor, J_b^+ \right)$ is the largest integer such that $x^N_{B_N} \geq q$, and $A_N \leq \min\left(\lfloor N^{1/12} \rfloor, J_a^+ \right)$ is the largest integer such that $y^N_{A_N} \geq q$. Here, we use the convention $x_0^N = y_0^N = 1$ so that $A_N =0$ and $B_N = 0$ are possible. We also have
\begin{equation}
\begin{split}
x_{B_N + i }^N = y_{A_N + i}^N =1 - \frac{2}{N^{1/4}c^+ \sigma_q} \mbox{ for } i = 1 ,\dots, C_N^+ \mbox{, where } C^+_N =  \begin{cases} 0 &\mbox{ if $c^+ = 0$, } \\  \lfloor N^{1/12} \rfloor  &\mbox{ if } c^+ > 0 \end{cases}, 
\end{split}
\end{equation}
 and 
\begin{equation}
\begin{split}
\mbox{ $x_i^N = q$ for $i > B_N + C_N^+ $ and $y_i^N = q$ for $i > A_N + C_N^+ $.}
\end{split}
\end{equation}
We let $N_0 \in \mathbb{N}$ be sufficiently large (depending on $q, c^+$) so that $x_i^N, y_i^N \geq q$ for all $i \in \mathbb{N}$, provided that $N \geq N_0$. Note that if $N \geq N_0$ and $M \geq 1$ we can define the ascending Schur process in ((S61E2 of the paper)) with parameters $N, M, \{x_i^N\}_{i = 1}^M$ and $\{y_i^N\}_{ i = 1}^N$ as above, since $x^N_i, y_i^N \in [q, 1)$ for all $i \in \mathbb{N}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.054916+00:00","domain":"probability theory","id":"claim_e24ea9a8ee67bd095a6a5d54b67186eca50f188e62ac6c67916db7fbdf5fcead","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] With $(m_i)$'s fixed as in \eqref{e.m_i=}, the map 
