{"assumptions":[],"created_at":"2026-10-27T22:43:19.217220+00:00","domain":"probability theory","id":"claim_e33ce5fb5a724b26e6d97092cb0358e13baf1ad7db13b2cc883243d4830c4a1c","kind":"lemma","schema_version":1,"statement":"[Lemma 2604131506 of arXiv:2609.02626, 'Comparison principles and symmetry for subquadratic fractional $p$-Laplacian equations'] Let $N\ge 1$, $s\in (0, 1)$, $1<p<2$, $\mathcal{U}$ be an open set satisfying $\overline{\mathcal U} \Subset \mathbb{R}_+^N$, and $K\Subset \mathbb{R}^N_+\backslash \overline{\mathcal{U}}$. Then there exists  $C=C(\mathcal{U}, K, N, s, p)>0$  such that given any  $\delta>0$ and $v\in \widetilde{W}^{s,p}(\mathcal{U})\cap \widetilde{W}^{s,p}(\mathcal{T}(\mathcal{U}))\cap L^{\infty}(\mathbb{R}^N)$, if
\begin{equation}
|v(x)-v^*(x)|\le \Big[\frac{\beta (p-1)(2\|v\|_{L^{\infty}(K\cup \mathcal{U})}+\delta)^{p-2} \, {\rm dist}(\mathcal{U}, \mathcal{T}(K))^{N+sp}\delta}{2^{3-p}{\rm diam}(\mathcal{U}, K)^{N+sp}}\Big]^{\frac{1}{p-1}} \quad \mbox{in }\; \mathcal{U},
\end{equation}
with ${\rm diam}(\mathcal{U}, K)=\sup\{|x-y|: x\in \mathcal{U}, y\in K\}$ and
\begin{equation}
\beta:=1-\underset{x\in \mathcal{U}, y\in K}{\sup}\frac{|x-y|^{N+sp}}{|x-y^*|^{N+sp}}\in (0, 1),
\end{equation}
one has then, in weak sense,
\begin{align*}
& \quad (-\Delta)_p^s (v-\delta {\mathbbm 1}_{K})-(-\Delta)_p^s (v^*-\delta {\mathbbm 1}_{\mathcal{T}(K)})\\
&\ge  (-\Delta)_p^s v- (-\Delta)_p^s v^* + C(\|v\|_{L^{\infty}(K\cup \mathcal{U})}+\delta)^{p-2}\delta\quad \mbox{in }\; \mathcal{U}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:25:39.114761+00:00","domain":"probability theory","id":"claim_e33e2b341e2e65f9cb55596a9f95e2cf0b666562d1d2733b317c1a316a43614f","kind":"concept","schema_version":1,"statement":"[Lemma lemma-bound-spin-correlations of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a constant $C>0$ such that for any $k \geq 1$ and any $x_1, \dots , x_k \in D_{\delta}$, 
\begin{equation*}
    \mu_{\delta}^{+}[\prod_{j=1}^{k}\sigma_{x_j}] \leq C^k\delta^{\frac{k}{8}}\exp\bigg( \frac{1}{8}\sum_{j=1}^{k} \log \frac{1}{L(x_j) \wedge {\operatorname{dist}}(x_j, \partial D_{\delta})} \bigg)
\end{equation*}
where for each $j$, $L(x_j) = \frac{1}{2}\min_{p:p \neq j} \vert x_p - x_j \vert$. Above, for $x \in D_{\delta}$, $d_{\delta}(x):={\operatorname{dist}}(x, \partial D_{\delta})$ is the Euclidean distance between $x$ and $\partial D_{\delta}$. Besides, by convention, for $k=1$, $L(x)=\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:42:57.183489+00:00","domain":"probability theory","id":"claim_e348ed292e9d2bf4932d5ba633a23088f8c46d969a68a88509b722461d76b6dd","kind":"concept","schema_version":1,"statement":"[Lemma lem:extremal_length of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] {lawler2008conformally}}]

		For $L>0$ we set $R_L \defeq(0,L) \times (0,\pi)$ and let $\partial_1 = [0,\ri\pi]$ and $\partial_2 = \partial_{2,L} = [L,L+\ri\pi]$.  Let $\tau = \tau_{R_L}$ denote the first time that a complex Brownian motion exits $R_L$ and set
		\begin{align*}
			&f_1(z) = f_{1,L}(z) = 2 \min\{\BP_z[B_{\tau} \in \partial_1] ,  \BP_z[B_{\tau} \in \partial_2]\}
