{"assumptions":[],"created_at":"2026-10-27T23:09:15.345755+00:00","domain":"probability theory","id":"claim_e362294c125033ddcb9b69dcd1dc2e57d37c4ab652fd2ffc82cf910bfd347d5a","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ a strong solution to (eqSEE of the paper) if 
    \begin{enumerate}[(i)]
        \item $X(t) \in D(A)$ for a.e. $(t, \omega) \in[0, T] \times \Omega$ and $A X(\cdot) \in L^1(0, T ; H)$ a.s.; 
        \item $F(\cdot, X(\cdot)) \in L^1(0, T ; H)$ a.s., $\widetilde{F}(\cdot, X(\cdot)) \in L_{\mathbb{F}}^{2}(0, T ; H)$;  
        \item For all $t \in[0, T]$,
        \begin{align*}
        X(t)=X_0 \!+\! \int_0^t(A X(s)+F(s, X(s))) d s+\int_0^t \widetilde{F}(s, X(s)) d W(s), \text{ a.s. }
        \end{align*}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:29:35.088056+00:00","domain":"probability theory","id":"claim_e36cf8e113c0b92a02fc36769758cea2729222550a97e95971b261a4802feec2","kind":"theorem","schema_version":1,"statement":"[Thm 19 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that assumptions \ref{H0}, \ref{H0.5}, \ref{H1}, \ref{H2b}, \ref{H3} and 
\begin{equation*}
\beta+\delta<\frac12\min\{\alpha,1-\alpha\}
\end{equation*}
hold. Let $(\Omega,\mathcal F,(\mathcal F_t)_{t\geq0}, \mathbb P, W,X)$ be a weak mild solution to \eqref{abstract_formulation}. For every $n\in\N$ and $x\in H$, the process $\{X_n(t,x)\}_{t\in [0,T]}$ defined by \eqref{Def:mild_form_approx_process} satisfies the following representation: 
\begin{align}
X_n(t,x)&=e^{tA_n}\left[P_nx+u_n(0,P_nx)\right]-u_n(t,X_n(t,x)) \notag \\
&-({\mathfrak c}+1)A_n\int_0^t e^{(t-s)A_n}u_n(s,X_n(s,x))ds \notag \\
&+\int_0^t e^{(t-s)A_n}\mathcal{V}_n\left[C_n(s,X(s,x))-C_n(s,X_n(s,x))\right]ds \notag \\
&+\int_0^t e^{(t-s)A_n}D_xu_{n}(s,X_n(s,x))\mathcal{V}_n\left[C_n(s,X(s,x))-C_n(s,X_n(s,x))\right]ds \notag \\
&+\int_0^te^{(t-s)A_n}D_xu_{n}(s,X_n(s,x))\mathcal{G}_ndW(s)\notag\\
&+\int_0^t e^{(t-s)A_n}\mathcal{G}_ndW(s),
\end{align}
where, in analogy with \eqref{expr_h+_h-}, for every $s\in[0,T]$ and every $x\in H_n$, we set 
\begin{align}
& u_n(s,x):=\sum_{k=1}^n \left(u_{n,k}^+(s,x)\Phi_k^{+}+u_{n,k}^-(s,x)\Phi_k^{-}\right), \\
&D_xu_n(s,x)\mathcal{V}_nh:=\sum_{k=1}^n\left( \scal{\mathcal{V}_n^ *\nabla_xu_{n,k}^+(s,x)}{h}_{U}\Phi_k^{+}+\scal{\mathcal{V}_n^*\nabla_xu_{n,k}^-(s,x)}{h}_{U}\Phi_k^{-}\right),\quad h\in U,
\\
&D_xu_n(s,x)\mathcal{G}_nh:=\sum_{k=1}^n\left( \scal{\mathcal{G}_n^*\nabla_xu_{n,k}^+(s,x)}{h}_{U}\Phi_k^{+}+\scal{\mathcal{G}_n^*\nabla_xu_{n,k}^-(s,x)}{h}_{U}\Phi_k^{-}\right),\quad h\in U,

\end{align}
$u_{n,k}^{(i)}$ is the unique solution to \eqref{Def:Unki} with $g=\scal{[\mathcal{V}_nC_n]^{(i)}}{\Phi^{(i)}_k}_{H_n}$ and ${\mathfrak{c}}$ is a constant given by Theorem \ref{Thm: soluzione-kolmogorov}, for every $k\in\{1,\ldots,n\}$ and $i\in\{-,+\}$.","status":"unverified"}

