{"assumptions":[],"created_at":"2026-10-26T19:47:01.671640+00:00","domain":"probability theory","id":"claim_e53e49915ff5bc1b39a6649c5534cb1afc8ae96c1857df6c6f7a7e10bd6ad21a","kind":"concept","schema_version":1,"statement":"[Proposition 17 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] Assume the following hypotheses:
\begin{enumerate}
 \item {Assumptions \eqref{as:generatorf}, \eqref{as:b:sigma}, \eqref{as:int:X:nablaX} and \eqref{as:suprho} are fulfilled, $a>\theta$ and $\ta>\ttheta$. We set $r'\geqslant 2$ such that $r'\geqslant r$ where $r$ comes from \eqref{prop:representationBSDEinfinitehorizon:growth}.
 }
 \item $\kappa_{\infty}<1$, recalling that $\kappa_{\infty}$ is defined in Proposition \ref{pr:Lpestimate}, so that 
 the fixed point equation $\Phi(v)=v$ has a unique solution $v \in C^0(\bR^d,\bR^{d'} \times\bR^{d \times d'})$ satisfying $\norm{ v}_{{\rho}_r}<+\infty$. We set $\norm{ v}_{{\rho}_r} \leqslant B <+\infty$ which implies that $\norm{v(x)} \leqslant B(1+|x|^r)$.
\item {$v \in C^2(\bR^d,\bR^{d'}\times \bR^{d \times d'})$ such that $\norm{\nabla^2 v(x)} \leqslant C(1+|x|^{r'})$.}
\item There exists a convex and increasing Orlicz function $\Psi$ satisfying Talagrand inequality \eqref{ineq:Talagrand}, Maximal inequality \eqref{ineq:maximal} 
 and there exists $C>0$ that does not depend on $\Pi$ (but depends on $B$) such that, for all functions $\phi : \bR^d \rightarrow \bR^{d'} \times \bR^{d' \times d}$ continuous with a growth $\norm{\phi(x)}\leqslant B(1+|x|^r)$ and $z \in \Pi$,
 \begin{equation}

  \left| \frac{R^z(P\phi)}{{\rho_{r'}(z)}} - \Exp{\frac{R^{z}(P\phi)}{{\rho_{r'}(z)}}} \right|_{\Psi} + \Exp{\norm{\frac{R^z(P\phi)}{{\rho_{r'}(z)}} - \Exp{\frac{R^{z}(P\phi)}{{\rho_{r'}(z)}}} }^2} \leqslant C.
 \end{equation}


\end{enumerate}
{Then there exist some constants $C>0$, $\varepsilon \in (0,\kappa_{\infty}^{-1}-1)$ and $\delta_0>0$ such that, for all $M \in \bN^*$, $N \in \bN^*$, $n \in \bN$ and $\delta \leqslant \delta_0$,
\begin{align*}
\Exp{\sup_{x \in \bR^d} \norm{\frac{ Pv^{n}_M(x) -v(x)}{\rho_{r'}(x)}}}
  \leqslant &C \left(\frac{\Psi^{-1}(N)}{\sqrt{M}}\left(1+\frac{\Psi^{-1}(M)}{\sqrt{M}}\right)+\delta^2
 +  \sup_{x \in \bR^d \setminus \Box} \left(\frac{1+|x|^r}{\rho_{r'}(x)}\right) +(1+\varepsilon)^n\kappa_{\infty}^n   \right).
\end{align*}} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:39:11.673969+00:00","domain":"probability theory","id":"claim_e541abd528fc95c83885286caf0d968e573f11696df96e3376f0a8714ada00ef","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2608.04853, 'Minimal-Norm Extensions of Stationary Kernels on Subgroups of Locally Compact Abelian Grou'] Let $h>0$, $\tau>1/2$, and $A_h:[0,1/h) \to \R$ be given by
\begin{align*}
    A_h(t)= \frac{\sum_{j \in \Z} \left(1+\left(t+\frac{j}{h}\right)^2\right)^{-2\tau}}{\left(\sum_{j \in \Z} \left( 1+\left(t+\frac{j}{h}\right)^2\right)^{-\tau} \right)^2}
\end{align*}    
Then there exists a constant $C_\tau>0$, independent of $h$ but possibly depending on $\tau$, such that
\begin{align*}
\frac{\left( 1+ \frac{1}{2h^2} \right)^{-2\tau}}{(2+2C_\tau h)^2}    \leq A_h(t) \leq 1, \quad \forall t \in [0,1/h).
\end{align*}
Additionally, we have that
\begin{align*}
    \sup_{t \in [0,1/h)} \sum_{j \in \Z} \left( 1+\left(t+\frac{j}{h}\right)^2\right)^{-\tau} < \infty.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.222171+00:00","domain":"probability theory","id":"claim_e54bdcde55e4b979ca00e32db6a0b5345dbb1047f227097154cd1bf9e39aa4c0","kind":"lemma","schema_version":1,"statement":"[Lemma eloge-derivative of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix $\nu\in \P(\X)$ and $\k\geq 2$. Given $\pi\in \Psym{\X}$, for any $\xi\in \Psym{\X}$, define
\begin{equation*}
    \pi_\varepsilon=\pi_\varepsilon[\xi]\coloneqq (1-\varepsilon)\pi+\varepsilon\xi,\quad \forall \varepsilon\in [0,1].
\end{equation*}
Then
\begin{equation}
    \lim_{\varepsilon\rightarrow 0^+}\frac{1}{|\varepsilon\log \varepsilon|}\cpr{J_\k^\nu(\pi_\varepsilon)-J_\k^\nu(\pi)}=(\k-1)\sum_{x\in \X}\xi^o(x)\indf_{\pr{\pi^o(x)=0}}-\frac{\k}{2}\sum_{x,z\in \X}\xi(x,z)\indf_{\pr{\pi(x,z)=0}}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.651441+00:00","domain":"probability theory","id":"claim_e54c8363314a9374b43678cc61c934558caf52561bd592c4a74b7f0cd8d220db","kind":"theorem","schema_version":1,"statement":"[Theorem SSRR of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume \((\Omega, \mathcal{F}, \mathbb{P}, \theta)\), \(\frac{1}{3} < \beta \leq \gamma < H\), and let \(\mathbf{B}\) be the delayed \(\gamma\)-rough path cocycle constructed in Theorem (thm:B_delayed_cocycle of the paper). Assume \(\xi \in \mathscr{D}_{\mathbf{B}(\omega)}^{\beta}([-r,0])\) and consider the following equation:
			\begin{align}
				\begin{split}
					\mathrm{d}y_{t} &= A\left(y_t, \int_{-r}^{0} y_{\theta+t} \pi(\mathrm{d}\theta)\right) \mathrm{d}t + G \left(y_{t}, y_{t-r}\right) \mathrm{d}\mathbf{B}_{t}(\omega), \\
					y_{s} &= \xi_{s} \quad \text{for} \quad -r \leq s \leq 0,
				\end{split}
			\end{align}
			with the same conditions as in Theorem (SSS of the paper). Then this equation admits a unique solution globally in time. Assume \((\phi^{t}_{\mathbf{B}(\omega)}(\xi))_{t \geq 0}\) is this solution. For \(m \in \mathbb{N}\), define
			\[
			\varphi^{m}_{\omega}(\xi) := \left(\phi^{(m-1)r+t}_{\mathbf{B}(\omega)}(\xi)\right)_{0 \leq t \leq r}.
			\]
			In this case, we indeed have \(\varphi^{m}_{\omega}(\xi) \in \mathscr{D}_{\mathbf{B}(\theta_{mr}\omega)}^{\beta}([-r,0])\). Moreover, the following map
			\begin{align}
				\begin{split}
					&\varphi^{m}_{\omega}: \mathscr{D}_{\mathbf{B}(\omega)}^{\beta}([-r,0]) \rightarrow \mathscr{D}_{\mathbf{B}(\theta_{mr}\omega)}^{\beta}([-r,0]), \\
					& \xi \longrightarrow \varphi^{m}_{\omega}(\xi),
				\end{split}
			\end{align}
			is continuous and satisfies the cocycle property, i.e.,
			\begin{align}
				\varphi^{p+q}_{\omega} = \varphi^{p}_{\theta_{qr} \omega} \circ \varphi^{q}_{\omega},
			\end{align}
			for all \(p, q \in \mathbb{N}\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.959024+00:00","domain":"probability theory","id":"claim_e55d6ad34798a61207624d45c1aa9cd0eda4284bf3e3e901fdc78f32763355a4","kind":"lemma","schema_version":1,"statement":"[Lemma 18 (Simultaneous pathwise block bound) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Assume, in addition to Assumption~\ref{ass:time}, the Galerkin-state finite-state condition stated there.  Fix a final loss $\eps>0$.  Choose $0<\eps_0<\eps$ and $\rho>0$ so that
