	\end{equation*}
	where the sum is over \(y\) such that \(P(Z_k=y\given Z_l= x)>0\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:01:15.328659+00:00","domain":"probability theory","id":"claim_e599e4e3af8575a29ea737bd261f42ebaef353b277abf03f0cef445f39822d54","kind":"theorem","schema_version":1,"statement":"[Coro 12 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let the assumptions of \cref{cor:decay-mass}, excluding \eqref{eq:cor:decay-mass}, be satisfied. Let $\{M_n : n \ge 1\} \subseteq \bN\cup\{0\}$ be a non-decreasing sequence and assume that, for each $n \ge 1$, the  family $\{X^n_k :  k \in S_n\}$ is $M_n$-pairwise diagonally negatively dependent. If
\begin{align}
\lim_{n \to \infty} N(K_n, \ep)^{1 - (\frac{1}{p} \wedge \frac{1}{2})} \lt\|K_n\rt\| \BB((1+M_n) \sum_{k\in S_n} a_{n, k}^2\BB)^{\frac{1}{p} \wedge \frac{1}{2}} = 0\quad \trm{for all }  \ep >0,
\end{align}
then
	\begin{align*}
		\lim_{n \to \infty} \mathbb{E}  \,\BB\| \sum_{k \in S_n} a_{n, k} (X^n_k - \bE X^n_k) \BB\|^p  = 0.
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.668252+00:00","domain":"probability theory","id":"claim_e59a52266b34d88cea230b149b39238e66fee5d6bb3f6d8e3e1e3f2e5687151d","kind":"concept","schema_version":1,"statement":"[Lemma 13 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $q$ be a positive integer, $e_0\in \HHH$, with $\|e_0\|_{\HHH}=1$, and  $(f_t)_{t\in[0,T]}$ be a family of vectors in  $\HHH ^{\odot q}$.   
	We denote by $V$ the orthogonal complement of $\operatorname{span}\{e_0\}$ in $\HHH$. 
	Hence, there exist $(f_{t,q-k})_{t\in [0,T]}\subset V^{\odot  {(q-k)}}$, with $0 \leq k \leq q$, such that
	\begin{equation}
		I_q(f_t)= \sum _{k=0}^{q} I_{k} (e_0^{\otimes k}) I_{q-k} (f_{t,q-k}),
	\end{equation}
	where $I_{0} (h^{\otimes 0})=1$. Furtheremore, for each $0 \leq k \leq q$, there exists a positive constant $C$ such that for any $s,t\in [0,T]$,
	\begin{equation}
		\|f_{t,q-k}-f_{s,q-k}\|_{\HHH^{\otimes {(q-k)}}}\leq C \|f_t-f_s\|_{\HHH^{\otimes q}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:31:02.821684+00:00","domain":"probability theory","id":"claim_e5a131872779c49809c405bbdea4b215853dee5e182a4f98e136f939a7edcddd","kind":"theorem","schema_version":1,"statement":"[Corollary cor:optimal-finite-modeling of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For all $h\geq1$ and $k\geq2$,
\begin{equation}
 \mathcal R_{\mathbb R}(h,k)=\mathcal R_{\mathbb Q}(h,k)=\mathcal R(h,k),
\end{equation}
and
\begin{equation}
 1+\left\lceil\frac{M_{h,k}-1}{h}\right\rceil
 \leq N(h,k)
 \leq 1+\max\left\{(k-2)h^{k-2},
                    \sum_{j=0}^{k-2}h^j\right\}.
\end{equation}
Consequently, for every fixed $k\geq2$,
\begin{equation}
 N(h,k)=\Theta_k(h^{k-2}).
\end{equation}
More finely, if
\[
 \nu_{h,k}(n)=\min\{\operatorname{ndiam}(A):A\subset\mathbb Z,\ |A|=k,\ |hA|=n\},
\]
then
\begin{equation}
 \nu_{h,k}(n)
 \leq\bigl(k-1-r_{h,k}(n)\bigr)h^{k-2}
 \qquad(n\in\mathcal R(h,k)).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.414105+00:00","domain":"probability theory","id":"claim_e5a68699253b15bc20cdc493f4871059a380e4f73c1fdeb3f655214a2dd9aa69","kind":"definition","schema_version":1,"statement":"[Definition 76 of arXiv:2601.16377, '2601.16377'] We say that $\boldsymbol{\ell}$ has no holes in $[\mathfrak{a},\mathfrak{b}]$ if all spacings between particles indexed by $I$ and their immediate neighbors are minimal. In more detail, $I$ should be nonempty and
the following three conditions should be satisfied
\begin{enumerate}
\item Bulk: $\forall i \in \llbracket i_0+1,i_0 + \#I-1\rrbracket\quad \ell_{i + 1} = \ell_i + \theta_{h,h}$.
\item Left boundary: either\footnote{If $i_0=0$ and $a_1=-\infty$, then there is no way for this condition to be satisfied and there is no way for $\boldsymbol{\ell}$ to have no holes.} $\ell_{i_0+1}= a_h$ or $\ell_{i_0+1}=\ell_{i_0}+\theta_{h,h}$.

\item Right boundary: either\footnote{If $i_0+\#I=N$ and $b_H=+\infty$, then there is no way for this condition to be satisfied and no way for $\boldsymbol{\ell}$ to have no holes.}
$\ell_{i_0 + \#I}=b_h$ or $\ell_{i_0+\# I+1}= \ell_{i_0 + \#I}+\theta_{h,h}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.731837+00:00","domain":"probability theory","id":"claim_e5a81479b10738a846f740462a6e77974fbdba240a9810b1b0e705e7a9b3cbf3","kind":"definition","schema_version":1,"statement":"[Definition 3 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $0 < \delta \le \eps \le 1$, we let $\pi^{\eps, \delta} : \mfL_- \to C^\infty(\mathbb{R}^2)$ be the smooth, stationary random noise assignment defined by
	\begin{align*}
		\pi^{\eps,\delta} \<b0> = \xi_\eps, \quad \pi^{\eps,\delta} \<p0> = \xi_{\delta}, \quad \pi^{\eps,\delta} \<0t> = \eps^{-1/2} \xi_{\eps, \delta}
	\end{align*}
	where we have written $\xi_{\eps, \delta} = \xi_\eps - \xi_{\delta}$. 

	We let $Z^{\eps, \delta} = (\Pi^{\eps, \delta}, \Gamma^{\eps, \delta})$ denote the corresponding BPHZ model, as introduced in \cite[Theorem 6.18]{BHZ}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.569963+00:00","domain":"probability theory","id":"claim_e5aac036f1cf72de5dfedf025631c845d095edd072e2411086107e824ae03f85","kind":"theorem","schema_version":1,"statement":"[Theorem thm:charac2cox of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $(\Omega, \mathcal{F}, \mathbb{G}, \mathbb{P})$ be a filtered probability space, where $\mathbb{G} = (\mathcal{G}_t)_{t \geq 0}$ satisfies the usual conditions. Let $\nu$ be a probability measure on $\mathbb{R}$ with $\nu(\{0\}) = 0$ and $\int_{\mathbb{R}} |\xi| \,\nu(d\xi) < \infty$. Let $\lambda: \mathbb{R}_+ \times \mathbb{R} \to \mathbb{R}_+$ be a measurable function, satisfying $c \leq \lambda \leq C$ for some constants $0 < c < C$. Suppose that $X$ is an It\^o semimartingale on $\Omega$ whose differential characteristics associated with a truncation function $h$ are given by
	\begin{equation*}
		\beta_t = \int_{\mathbb{R}} h(\xi) \,\nu(d\xi) \cdot \lambda(t, X_{t-}),\quad
		\alpha_t = 0,\quad
		\kappa_t(d\xi) = \lambda(t, X_{t-}) \nu(d\xi),
	\end{equation*}
	and $X_0 = 0$. Then, there exist a sequence of i.i.d.\ $\operatorname{Exp}(1)$ random variables $(E_k)_{k \in \mathbb{N}^*}$ and a sequence of i.i.d.\ $\nu$-distributed random variables $(J_k)_{k \in \mathbb{N}^*}$, with $(E_k)_{k \in \mathbb{N}^*}$ and $(J_k)_{k \in \mathbb{N}^*}$ being independent, such that $X_t = \sum_{k=1}^\infty J_k \bm{1}_{\{\tau_k \leq t\}}$, where $(\tau_k)_{k \in \mathbb{N}}$ is inductively defined by $\tau_0 \coloneqq 0$ and
	\begin{equation}
		\tau_k \coloneqq \inf\biggl\{t > \tau_{k-1}: \int_{\tau_{k-1}}^t \lambda(s, X_{\tau_{k-1}}) \,ds \geq E_k\biggr\},\quad
		k \in \mathbb{N}^*.
	\end{equation}
	In other words, $X$ is a doubly stochastic compound Poisson process with intensity $(\lambda(t, X_{t-}))_{t \geq 0}$ and jump size distribution $\nu$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:20:07.942207+00:00","domain":"probability theory","id":"claim_e5afe441df891f3ccb7cb7527136a735b815791fbe5a207594f3c4d8512f775e","kind":"theorem","schema_version":1,"statement":"[Theorem thm:axial of arXiv:2608.30254, 'Exact Recovery Thresholds for Weighted Data Selection\\ in Vector-Valued Linear Regression'] For every $d,m\ge1$,
\[
  \frac{L^{\star}_{D_{d,m}}\bigl((m+1)d-1;\mathrm{weighted}\bigr)}
       {L^{\star}_{D_{d,m}}}
  \;=\;1+\frac{m+1}{2md\,(m^2+m-1)}\;>\;1 .
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:48:30.921802+00:00","domain":"probability theory","id":"claim_e5b421b3f990cd212674bd6a3773dcc4d8ee59bc514a6ee07d264108c9c0b11d","kind":"theorem","schema_version":1,"statement":"[Thm 16 (Main Formula) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $k$ be a perfect field. Let $K= k(x)$.
    Let $f\in K$ be a nonzero element.
    Let $PFD(\frac{1}{f})=P+L+H$ be its partial fraction decomposition (over $\overline{k}$), see Theorem \ref{thm: PFD}.

    Let $e$ be the degree of $P$. Let $M$ be the highest order of pole in $H$. Let $p$ be a prime number such that $p-1>e$ and $p>M-1$.

    Let $D=f\frac{\partial}{\partial x}$.
    Then we have that
    \begin{equation}
        D^p= \mu D \hspace{1 cm} \text{, where } \mu=f^p\overline{L}=\frac{\overline{L}}{P^p+L^p+H^p}\in K^p
    \end{equation}
    and $\overline{L}=\sum_{i=1}^d \frac{c_i}{x_i^p-a_i^p}$ if ${L}=\sum_{i=1}^d \frac{c_i}{x_i-a_i}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:46:25.366129+00:00","domain":"probability theory","id":"claim_e5b46f3e36277457e08c79a056664a37e1cb9a215edeecbd9e250f23a008590c","kind":"concept","schema_version":1,"statement":"[Lem translation-invariance-unconditional of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $U' \in \mathcal{Q}$ and $z \in \mathbf R^2$ be such that $U'+z \subseteq [0,1]^2.$ Then
\begin{equation}
    (\Gamma_{U'},(\mathfrak{d}_{V})_{V\in\mathfrak{C}'_{U'}})\overset{d}{=}(\Gamma_{U'+z},(\mathfrak{d}_{V})_{V\in\mathfrak{C}'_{U'+z}})-z.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:03:59.407640+00:00","domain":"probability theory","id":"claim_e5b76860c8c4558cc2ad2d9e81c67a49017cfc40642a510d581098053e42c3ef","kind":"lemma","schema_version":1,"statement":"[Lemma pi=rho of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] Let $\widehat\pi^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}$ and $\widehat\gamma^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}$ be two shift-covariant non-crossing systems of geodesics such that $\widehat\mathbb{P}\{\widehat\pi^0\preceq\widehat\gamma^0\}=1$. Assume that either $\widehat\pi^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}\in{\widehat{\mathbbold\Pi}_c}$ or $\widehat\gamma^{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}\in{\widehat{\mathbbold\Pi}_c}$. Assume also that there exists a cocycle ${\widehat B}\in\widehat{\mathcal{K}}$ such that both $\widehat\pi^u$ and $\widehat\gamma^u$ are ${\widehat B}$-geodesics for all $u\in\mathbb{Z}^2$. 
    That is, 
    \begin{align}
    \widehat\mathbb{P}\bigl\{{\widehat\omega}:\forall u\in\mathbb{Z}^2,\forall n\ge u\cdot(e_1+e_2):{\widehat B}({\widehat\omega},\widehat\pi_n^u({\widehat\omega}),\widehat\pi_{n+1}^u({\widehat\omega}))=\omega_{\widehat\pi_n^u({\widehat\omega})}({\widehat\omega})\bigr\}=1
    \end{align}
    and
    \begin{align}
    \widehat\mathbb{P}\bigl\{{\widehat\omega}:\forall u\in\mathbb{Z}^2,\forall n\ge u\cdot(e_1+e_2):{\widehat B}({\widehat\omega},\widehat\gamma_n^u({\widehat\omega}),\widehat\gamma_{n+1}^u({\widehat\omega}))=\omega_{\widehat\gamma_n^u({\widehat\omega})}({\widehat\omega})\bigr\}=1.
    \end{align}
    Then $\widehat\mathbb{P}\{\forall u\in\mathbb{Z}^2:\widehat\pi^u=\widehat\gamma^u\}=1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.729383+00:00","domain":"probability theory","id":"claim_e5bda4dbcc258e14e568e7a8c4da1d30820a04b146d15a1ea3067cfa9c42172b","kind":"theorem","schema_version":1,"statement":"[Corollary coro:m(t)-polynomial-time-not-going-out of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Let $X_t$ be initialized at any point with $|m(X_0)|\geq \mathsf{m}_{3}$, and define the escape time below $\mathsf{m}_{2}$ as 
    $\tau^{\mathsf{out}}=\inf\{t>0 \ : \,|m_t|<\mathsf{m}_{2}\}$. For any time $T$ we have:  
    \begin{align*}
        \mathbb P[\tau^{\mathsf{out}} \leq T] \leq C T \exp(-cN) \, . 
    \end{align*}
    for $C,c>0$ constants independent of $N$ and $T$, depending only on $\beta$ and $\theta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.355519+00:00","domain":"probability theory","id":"claim_e5c3414ff03ea30f238ff43c30f8c0848b3faab7bc1eea9d5f724f654fd8f2c1","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] Let \(\beta\in(0,1/6)\). There are \(n_0,\lambda_0, r_0\geq 0\) and \(c>0\) such that for any \(n\geq n_0\), any \(\lambda_0\leq \lambda\leq n^{\beta}\), any \(1\leq k\leq n\), and any \(L\geq r_0 \sqrt{\lambda}n^{2/3}\) with \(k+L\leq n\),
    \begin{equation*}
        P\bigl( \bar{A}^{\lambda}_{k,k+L} \bgiven (A^{\lambda}_{k-L,k-1})^c, (A^{\lambda}_{k+L+1,k+2L})^c\bigr)
        \leq
        \exp(-c\tfrac{\lambda L}{n^{2/3}}).
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:48:30.921467+00:00","domain":"probability theory","id":"claim_e5c76bf183878ba69eefdf4fb85aaea4a355c5fd1d86540a80ecc9b3e0b8bde3","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $r\ge 1$ and $n\ge 2$ be integers. Let $p$ be a prime number such that $p>n-1$.
    Then
    \[
    p \text{ divides } \binom{n+(pr-1)-1}{pr-1}={(-1)}^{pr-1}\binom{-n}{pr-1}
    \]
    Moreover, if $p=n-1$, then divisibility no longer holds by Wilson's theorem and its generalizations \cite{Wolstenholme_theorem_history}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:02.062930+00:00","domain":"probability theory","id":"claim_e5cc7327f2504f27ef12e5532c429143866a8f17c444beeeab47a76011bfc3de","kind":"definition","schema_version":1,"statement":"[Defn def:root-biased of arXiv:2601.00119, 'The largest common subtree of two random trees'] Let $\mu$ be a critical measure on $\mathbb{N}$. A random plane tree $\tau_*$ is called a \emph{root-biased Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] For all $k \geq 0$, $\mathbf{P}(\mathrm{k}_\varnothing(\tau_*) = k) = (k+1)\mu(k+1)$.
    \item[(b)] For all $k \geq 1$ such that $\mathbf{P}(\mathrm{k}_\varnothing(\tau_*) = k) > 0$, conditionally given that $\mathrm{k}_{\varnothing}(\tau_*) = k$, $\theta_1\tau,...,\theta_k\tau$ are independent Bienaym\'{e} trees with offspring distribution $\mu$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:54:15.648942+00:00","domain":"probability theory","id":"claim_e5ccada23bfd7998f9faa28dc7ba612e20f93688bb82e2cfa641d08d1e75a580","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{L2}
	Let $\mP_{p,E}$ be the set of polynomial probability generating functions with the expectation $P'(1)=E$ and, also, satisfying $P(0)=0$, $P'(0)=p$. Denote $N=\lfloor \frac{E-p}{1-p}\rfloor$. Then, the unique minimizer of the second derivative at $z=1$ is
	\[\lb{110}
	{\rm argmin}_{P\in\mP_{p,E}}P''(1)=pz+(N(1-p)+1-E)z^N+(E-p-N(1-p))z^{N+1}.
	\]
It is assumed that $E\ge 2-p$, because, otherwise, $\mP_{p,E}=\varnothing$, and \er{110} does not make sense. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:33:12.347572+00:00","domain":"probability theory","id":"claim_e5cd84f383603fce78433bfe0ddd2ee41dbf3884c6aa5055e137c4f30e78e086","kind":"lemma","schema_version":1,"statement":"[Lem 154 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For the collection of random variables described by \eqref{e:state.evol.x.y.increments.CHAOTIC} with $\eta=0$, let us abbreviate $\hat{S}\equiv \hat{S}^{\eta=0}$, $\hat{R}\equiv \hat{R}^{\eta=0}$, 
$\hat{X}^\ell\equiv \hat{X}^{\ell,\eta=0}$, and so on. On the other hand, let $(X^{\ell},M^{\ell},V^{\ell},\dots)_{\ell\leq \ubl}$ be the state evolution limit of our earlier iteration $\IAMP(p,\sigma,b,w,\delta)$, as described around \eqref{e:state.evol.x.y.increments}. Then
  \[\begin{aligned}
  (\hat{S},\hat{X}^\ell,
    \hat{\prxX}^\ell,
    \hat{M}^\ell,\hat{V}^\ell)_{0\leq \ell\leq \ubl}
  &\stackrel{\textit{d}}{=}
  (S', S' X^{\ell}, S' \prxX^\ell,
    S' M^{\ell}, S' V^{\ell})_{0\leq \ell\leq \ubl}\,,\\
  (\hat{R},\hat Y^\ell,\hat{\prxY}^\ell,
  \hat{U}^\ell,\hat{G}^{\ell})_{0\leq\ell\leq\ubl}
  &\stackrel{\textit{d}}{=}(R',R' Y^{\ell},R' \prxY^{\ell}, R' U^{\ell}, R' \bar{G}^{\ell})_{0\leq \ell\leq \ubl}. 
  \end{aligned}\]
where $S'$ and $R'$ are 
symmetric random signs independent of everything else. 
In particular, at $\eta=0$ the constants $\hat{\prxgamma}$, $\hat{\gamma}$ from \eqref{e:gamma.chaotic} are the same as the constants $\prxgamma$, $\gamma$ from \eqref{eq:proxy-C-ell-delta-def}. Additionally $\hat G^{\ell}$ is independent of $(\hat Y^k,\hat\prxY^k,\hat U^k)_{0\leq k\leq \ell-1}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:04:30.593068+00:00","domain":"probability theory","id":"claim_e5d30b198e5b475a86434b5be99001f7378aee64d8fbfc7354b6a1f5212047b2","kind":"lemma","schema_version":1,"statement":"[Lemma lem:geometric of arXiv:2411.10419, 'Lower bounds on the top Lyapunov exponent for linear PDEs driven by the 2D stochastic Navi'] For any $ \ell \in \mathbf{R}^{2} $ define $ Q_{\ell} (k) = || \ell |^{2} - 2 \langle k, \ell
\rangle |^{2} | \langle k^{\perp}, \ell \rangle |^{2}$.
Then there exists a $ c > 0 $ such that for all $ k \in \mathbf{Z}^{2} $
\begin{equ}
\sum_{| \ell | \leqslant \sqrt{2}} Q_{\ell}(k) \geqslant c | k |^{4} \;.
\end{equ}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.963449+00:00","domain":"probability theory","id":"claim_e5d676de20469fb92a1f6af3077e348f6e5d9a59687e597b5edb3ab20046bd40","kind":"theorem","schema_version":1,"statement":"[Corollary 25 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] Let $T<\infty$. The function $(t,l)\mapsto \tilde W_T(t,l)$ is $\llip{\tilde{\mathcal{S}}_T}$. Specifically, at points of differentiability it holds that
    \begin{equation}
        \partial_l \tilde{W}_T(t,l)=\mathbb{E}\left[\int_{0}^{\tilde\tau^*}\partial_l L^l_{u}\partial_l(\tilde{\mathcal{L}}\tilde{g})(L^l_{u})\,du\right]
    \end{equation}
    where $\tilde\tau^*:=\tilde\tau^*_T(t,l)$ is the optimal stopping time, and 
    \begin{equation}
        \mathbb{E}[c(t+\tilde\tau^*)]-c(t)\leq \partial_t\tilde{W}_T(t,l)\leq  \mathbb{E}[c(t+\tilde\tau^*)]-c(t) + K''\mathbb{P}(\tilde\tau^*=T-t),
    \end{equation}
     where $K''$ is defined in Proposition \ref{prop:time_lip}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:30:50.708506+00:00","domain":"probability theory","id":"claim_e5de368b91a9e99de8c545e919ddfd46d8ea7e1097266ce72fec28f2f8c93f29","kind":"lemma","schema_version":1,"statement":"[Lemma eq:GNpos of arXiv:2609.00481, 'The frameset of the second-order B-spline along $ab=1/q$'] For $N\in \mathbb{N}$, and $\gamma\in \mathbb{R}$, we have
\begin{align}
    G_N(\gamma) \vcentcolon= (N+1) F_{N+1}(\gamma) - D_N(\gamma) = \left(\frac{\sin(N\pi \gamma)}
    {\sin(\pi \gamma)}\right)^2 \geq 0, 
\end{align}
and
\begin{align}
    \sum_{k=1}^N k \cos(2\pi k \gamma) = \frac{N+1}{2}\left(D_N(\gamma) -
    F_{N+1}(\gamma)\right).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.848947+00:00","domain":"probability theory","id":"claim_e5e15b8ebf3559d1dc882dd4061fa2fa5e57c682ff0c7b3eac29656430fc852c","kind":"concept","schema_version":1,"statement":"[Lemma 56 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] Let $E\subset F$ be a super order dense sublattice and let $B\subset F$ be solid. The following sets are equal:
\item[(i)] The set of all $f\in F$ such that there is $Q\subset B_{+}$ with $Q\uparrow\left|f\right|$;
\item[(i')] The set of all $f\in F$ such that there is $Q\subset B_{+}\cap E$ with $Q\uparrow\left|f\right|$;
\item[(ii)] The order adherence of $B$ in $F$;
\item[(ii')] The order adherence of $B\cap E$ in $F$;
\item[(iii)] The uo adherence of $B$ in $F$;
\item[(iii')] The uo adherence of $B\cap E$ in $F$.\medskip

