{"assumptions":[],"created_at":"2026-10-26T20:46:26.256892+00:00","domain":"probability theory","id":"claim_e6043545a9af684922f90537f0720b0c8072225d90e830e4e43914c79dc50fb4","kind":"concept","schema_version":1,"statement":"[Thm 56 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $x\in F,\;x_n\in F_n,\;\kappa\in [1/2,1],\;t>0$ and $f\in \BL^{\kappa}(M)$ and set
\[
h:=d(x,x_n)+d_{\rm{H}}(F,F_n)^{\kappa}+d_{\BL^{\kappa}}(\mu,\mu_n).
\]
\begin{itemize}
  \item [$\rm{(i)}$]If $(F,R,\mu)$ satisfies the assumption $\rm{(A2)}$, and $h\leq 1/2$,
then it holds that
\begin{align*}
 \Big|E_x[f(X_t)]-E^n_{x_n}[f(X^n_t)]\Big|\lesssim \g{c}{gen,n}\|f\|_{\BL^{\kappa}} h^{E},
\end{align*}
where
\begin{align*}
  E=\frac{\kappa}{\kappa+(1+s_0)(2+\kappa)(\kappa+\theta)},
\end{align*}
and
\begin{align*}
  \g{c}{gen,n}=\frac{1}{1-(1/2)^E}\left[ \g{c}{12q2}
    +\g{c}{sg2,n}\mu(F)^{1/2}\Bigl\{ c_{\rm{A1}} +\g{c}{suffcond1,3}\left(\frac{\alpha_n}{2}\right)^{-(1+\frac{s_1}{2(1+s_0)\theta})(2\kappa-1)}\Bigr\}
    +\g{c}{suffcond1,3}\mu(F)^{1/2} \right],
\end{align*}
and the $p$ in $\g{c}{sg2,n}$ is $2$.
Moreover, the time-dependence of $\g{c}{gen,n}$ is $t+t^{-[\kappa-\frac{s_1}{2(1+s_0)\theta}(2\kappa-1)]},\;t\in (0,1]$.
\item[$\rm{(ii)}$]If $(F,R,\mu)$ satisfies the assumption $\rm{(A3)}$, and $h$ is sufficiently small,
then it holds that
\begin{align*}
 \Big|E_x[f(X_t)]-E^n_{x_n}[f(X^n_t)]\Big|\lesssim \g{C}{gen,n}\|f\|_{\BL^{\kappa}} h^{E_1}(\log(1/h))^{E_2},
\end{align*}
where
\begin{equation*}
  E_1=\frac{\kappa}{\kappa+(1+s_0)(2+\kappa)\Theta},\qquad E_2=\frac{\kappa (2+\kappa)[ (1+s_0)\Theta-1 ]}{\kappa+(1+s_0)(2+\kappa)\Theta},
  \qquad
  \Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)},
\end{equation*}
\begin{equation*}
  \begin{aligned}
    \g{C}{gen,n}=&\left\{ 1+\mu(F)^{1/2}\g{c}{suffcond1,4}+\g{c}{sg2,n}\mu(F)^{1/2}\Bigl[ c_{\rm{A1}}^{1/2} +\g{c}{suffcond1,4}\left(\frac{\alpha_n}{2}\right)^{-(1+\frac{s_1}{2(1+s_0)\Theta})(2\kappa-1)}\Bigr] \right\}\\
  &\times\left\{ 1+\left[\g{c}{summ}^{1/\beta}(1\wedge\frac{1}{2}\diam F)^{1+1/\beta}\left(\frac{\kappa}{\kappa+(1+s_0)(2+\kappa)\Theta}\right)^{-\frac{1}{\beta}}\right]^{-(\kappa+2)}\right\},
  \end{aligned}
\end{equation*}
and $\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}$,
and the $p$ in $\g{c}{sg2,n}$ is $2$.
Moreover, the time-dependence of $\g{C}{gen,n}$ is $t+t^{-[\kappa-\frac{s_1}{2(1+s_0)\Theta}(2\kappa-1)]},\;t\in (0,1]$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.565384+00:00","domain":"probability theory","id":"claim_e60a1ec3943625bc6093fdfc5da92d348ff575fabb0b74ed4c286b889727a737","kind":"theorem","schema_version":1,"statement":"[Proposition 21 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,\|\cdot\|_X)$ and $(Y,\|\cdot\|_Y)$ be finite dimensional normed spaces. Let $c: X \times Y \to \R$ be a continuous cost function that is positively 1-homogeneous in the second variable, meaning $c(x, ty) = tc(x,y)$ for all $t > 0$.

    Suppose a bounded set $K\subset X$ satisfies the non-degeneracy condition:
    \begin{equation}

        \inf_{u \in \mathbb{S}_Y} \sup_{x \in K} -c(x,u) = \epsilon > 0,
    \end{equation}
    where $\mathbb{S}_Y = \{y \in Y \mid \|y\|_Y = 1\}$. Let $L \subset Y$ be a non-empty set and suppose that $-c$ is non-negative on $K\times L$. Set $M(K,L) = \sup_{x\in K, y\in L} -c(x, y)$. Then,
    \begin{enumerate}
        \item If $L$ is unbounded, then $M(K,L)=\infty$.
        \item If $L$ is bounded, then $0\leq M(K,L)<\infty$ and $L\subseteq M(K,L)K^{\circ, c}$. Moreover, if $-c(x,y)=0$ for all $x \in K$ implies $y=o$, then $M(K,L)=0$ implies $L=\{o_Y\}$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:38.359722+00:00","domain":"probability theory","id":"claim_e60bef4488f17783f9cc829043fd13c5e8d67b399bd28820357c0dcc21a1c8f7","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.21162, '2604.21162'] Assume that {\bf Assumption (H1)} holds and that $d>3$.
