{"assumptions":[],"created_at":"2026-10-26T19:20:33.745613+00:00","domain":"probability theory","id":"claim_e65cc6bc1a113afcb9bae3d531fc257731716ddfd95171de5e1b308b7ff52bc1","kind":"concept","schema_version":1,"statement":"[Theorem 7 (Critical rescaled power variation) of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] Assume $H=K$.  Then, $\Pp$-a.s.~for every $t\in[0,1]$,
\begin{equation}
\lim_{n\uparrow\infty}
\frac1{n^{1/(2H)}}
\sum_{k=0}^{\floor{tb^n}-1}
\abs{Y((k+1)b^{-n})-Y(kb^{-n})}^{1/H}
=
\frac{2^{1/(2H)}\Gamma\big(\frac{H+1}{2H}\big)}{\sqrt\pi}\,t.
\end{equation}
In particular, almost all sample paths of $Y$ have infinite $b$-adic $(1/H)^{\text{th}}$ variation:
\begin{equation}
 V_n^{(1/H)}(Y,t)  \longrightarrow+\infty\qquad\text{for every $t\in(0,1]$ $\Pp$-a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.256649+00:00","domain":"probability theory","id":"claim_e660e49408d96b97653bd16b958e85e189706fd2e16461031243f377e6727b4e","kind":"definition","schema_version":1,"statement":"[Definition 22 of arXiv:2604.19220, 'Split merge dynamics for expanding intervals and point processes on the real line.'] Let $(U_{i,k})_{ k\in \ZZ, \;  i \in \NN} $ be a sequence of i.i.d. uniform  random variables on $[0,1]$ independent of $(E_{1,i}, \; E_{2,i})_{ i \in \NN} $ be a pair of independent sequences of i.i.d. exponential  random variables with parameter $1.$ Both sequences are assumed to be independent. Let us define a $ {\cal S}_{l,m} $ valued Markov chain with the following procedure. 

 For $ i \ge 0 $ let $ \X_i = \{ \X_{i}^{1}< l < \X_{i}^{2}< \ldots < \X_{i}^{n-1} < m < \X_{i}^{n} \}.$
 \begin{itemize}
 \item  If   $ n > 2.$ Then for $ k = 2 $ to $ n $ let 
 $$ \tilde{\X}_i^k = U_{i+1,k} \X_{i}^{k-1} + (1-  U_{i+1,k}) \X_{i}^{k}.$$
 \begin{itemize}
 \item  If $ \tilde{\X}_i^2 < l,$ we set $ \X_{i+1}^1 = \tilde{\X}_i^2,$ and for $ k = 2 $ to $ n-1 $ $ \X_{i+1}^{k} =  \tilde{\X}_i^{k+1}.$ 
 \item  If  $ \tilde{\X}_i^2  > l,$ we take $ \X_{i+1}^1 =  \X_{i}^1 - E_{1,i}  $ and for  $ k = 2$ to $ n-1 $  $ \X_{i+1}^{k} =  \tilde{\X}_i^k.$ 
 \item  If $ \tilde{\X}_i^n < m , \; \X_{i+1}^n=\tilde{\X}_i^n $ and $ \X_{i+1}^{n+1}= \X_i^n +  E_{2,i}.$      \item If $ m < \tilde{\X}_i^n, \;  \X_{i+1}^n= \tilde{\X}_i^n.$
 \end{itemize}
 \item If $ n = 2,$ 
 $$ \tilde{\X}_i^2 = U_{i+1,2} \X_{i}^{1} + (1-  U_{i+1,2}) \X_{i}^{2}.$$
 \begin{itemize}
 \item  If $ \tilde{\X}_i^2 < l,$ we set $ \X_{i+1}^1 = \tilde{\X}_i^2,$ and $ \X_{i+1}^2 = \X_i^2+ E_{2,i}.$
 \item  If $ l < \tilde{\X}_i^2 < m,$ we set 
 $$   \X_{i+1}^1 =  \X_{i}^1 - E_{1,i}, \;  \X_{i+1}^2 =  \tilde{\X}_i^2, \; \X_{i+1}^3 = \X_i^2 +  E_{2,i}. $$
 \item  If $ m < \tilde{\X}_i^2,$ we set $ \X_{i+1}^1 = \tilde{\X}_i^1 - E_{1,i},$ and $ \X_{i+1}^2 = \tilde{\X}_i^2.$
 \end{itemize}
 \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.440318+00:00","domain":"probability theory","id":"claim_e66242bc6838efec779b8bd2dd54982ad6fba760295b3711cedf8bbb514f6229","kind":"theorem","schema_version":1,"statement":"[Proposition prop:T=Gamma of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] With the same assumption and notation as in Proposition (prop:ribbon of the paper), 
