{"assumptions":[],"created_at":"2026-10-27T07:17:17.063709+00:00","domain":"probability theory","id":"claim_e664dee947787982fa3846415dc23b4dd48ab63f216f248562a9c0ca9f4e2f81","kind":"theorem","schema_version":1,"statement":"[Proposition 18 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] For every $\beta > 0$, the ground state energy $\lambda(\beta)$ is differentiable with respect to $\beta$, and
\begin{equation}
\lambda'(\beta) = \int_{\mathbb{R}^d} \de x \, Q(x) \phi_{\beta}(x)^2  =: \theta_{\beta}.

\end{equation}
Let 
\[\mathcal{D}_{\beta,0} = \{g \in \mathcal{D} : g \text{ is real-valued and } \langle g, \phi_{\beta}\rangle = 0\}\]
and define on this real Hilbert space the coercive form $b_{\beta}[f,g] = h_{\beta}[f,g] - \lambda(\beta)\langle f,g\rangle$ and the bounded linear functional $L_{\beta}(g) = \int_{\mathbb{R}^d} \de x \, (Q(x) - \theta_{\beta})\phi_{\beta}(x)g(x) $.
Then, there exists a unique $u_{\beta} \in \mathcal{D}_{\beta,0}$ satisfying
\begin{equation}
b_{\beta}[u_{\beta}, g] = L_{\beta}(g) \quad \text{for all } g \in \mathcal{D}_{\beta,0}.

\end{equation}
Furthermore, $\beta \mapsto \phi_{\beta}$ is differentiable in the form norm $\|\cdot\|_{\mathcal{D}}$ with $\partial_{\beta}\phi_{\beta} = -u_{\beta}$, and $\lambda(\beta)$ is twice differentiable with
\begin{equation}
\lambda''(\beta) = -2 b_{\beta}[u_{\beta}, u_{\beta}] < 0.
\nonumber
\end{equation}
In particular, $\beta \mapsto \theta_{\beta}$ is strictly decreasing, $\sigma_{\beta}^2 = -\lambda''(\beta) > 0$, and $I_{\beta} = \frac{1}{2} \int_{\mathbb{R}^d} \de x \, |\nabla\phi_{\beta}(x)|^2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.498478+00:00","domain":"probability theory","id":"claim_e66d8e33f068b0ae3b35d38e0a991059eb1d18049c3446616260a9dd88739576","kind":"theorem","schema_version":1,"statement":"[Cor lem:lipschitz-f-g of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] The following statements hold:
\begin{enumerate}[label=(\roman*)]
    \item $\tilde F: [0,\infty) \times B \times \Theta \to B$ is locally Lipschitz.
    \item $\tilde G: [0,\infty) \times B \times \Theta \to \gamma(\mathcal{U},\mathcal{B}_{\beta,\rho})$ is locally Lipschitz for all $\rho \in [2,\infty)$, where $\beta$ is as in (SPDE-G-lem of the paper)(i).
    \item For all $M,p > 0$ there is some constant $C > 0$ such that
    \begin{equation}
        R+\|x\|_B \leq M \implies \|\tilde F_u(R,x,\theta)\|_{L^p} \leq C\|x_u\|_{L^p} \,.
    \end{equation}
    \item For any $r \geq 0$, $\theta \in \Theta$, and any $x$
    \begin{equation} 
        |\tilde \sigma_u(\cdot,r,x,\theta)| \lesssim |x_u| \,.
    \end{equation}
    \item There is some $k > 0$ such that, for $\rho \in [2,\infty)$ and $\beta$ as in (SPDE-G-lem of the paper):
    \begin{equation}
    \begin{aligned}
         \|\tilde G_u(R,x,\theta)\|_{\beta,\rho} &\lesssim \|x_u\|_{L^\rho} &\quad &\text{and} &\quad \|\tilde G(R,x,\theta)\|_{\beta,\rho} &\lesssim (1+R)\|x\|_{L^\rho}\\
         |\tilde F^+(R,x,\theta)| &\lesssim 1 + (1+R)|x| &\quad &\text{and} &\quad |\tilde F(R,x,\theta)| &\lesssim (1+R)^k|x|^k
         \,.
    \end{aligned}
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.074799+00:00","domain":"probability theory","id":"claim_e66dbaec733926c3e790a1d0c1fd0cc5d534ad07c6bfcc3aba197debb716046f","kind":"theorem","schema_version":1,"statement":"[Theorem 4 of arXiv:2606.02036, 'Self-intersection local times for Volterra Gaussian processes in stochastic flows with int'] Let $\{u(t) \equiv (u_1(t),\ldots,u_d(t)):  t\in[0,1]\}$ be a centred Gaussian process in $\mathbb{R}^d$ with indepdendent and identically distributed (i.i.d.) components and $\rho:\mathbb{R}^d\to\mathbb{R}$ be a weight function satisfying \eqref{eq:condition_on_weight_function}. Let $p\ge 2$.  If
 \begin{align}

 \int_{\Delta^p_k}\frac{1}{G(u_1(t_1),\ldots,u_1(t_{pk}))^{\frac{d}{2}}}\differential{t_1}\cdots\differential{t_{pk}}<\infty,
