{"assumptions":[],"created_at":"2026-10-27T12:02:11.286867+00:00","domain":"probability theory","id":"claim_e72adf3a031c512c3bcaec7280c62a1802808ac3570a239c715b1f0470eb57a7","kind":"lemma","schema_version":1,"statement":"[Lemma lem:2 of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] Fix $i \in \{1,2\}$. Let $p \neq 7/8$ be such that $\lambda^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) = - \frac{1}{2}$ almost surely.  
    \begin{itemize}
    \item[i)] The following central limit theorem holds - 
      \begin{align}  &\sqrt{\frac{n}{\log n}}\left\{{{\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top}\boldsymbol{M}_{n+1}\left(\boldsymbol{\Gamma}^{(p)}\right)}\right\} \stackrel{d}{\to} N\left(0, {\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top\boldsymbol{\sigma\left(\boldsymbol{\Gamma}^{(p)}\right)}\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)}\right). 
     \end{align}
    \item[ii)] The following law of iterated logarithms holds almost surely -
    \begin{align}  &\limsup_{n \to \infty}\sqrt{\frac{n}{2\log n \log\log\log n}}\left\{{{\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top}\boldsymbol{M}_{n+1}\left(\boldsymbol{\Gamma}^{(p)}\right)}\right\} \\ = - &\liminf_{n \to \infty}\sqrt{\frac{n}{2\log n\log\log\log n}}\left\{{{\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top}\boldsymbol{M}_{n+1}\left(\boldsymbol{\Gamma}^{(p)}\right)}\right\} \nonumber \\ =\textcolor{white}{+}& \sqrt{\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top\boldsymbol{\sigma\left(\boldsymbol{\Gamma}^{(p)}\right)}\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)}. \nonumber
    \end{align}
    \item[iii)] The following quadratic strong law holds almost surely -  
    \begin{align}  &\lim_{n \to \infty} \frac{1}{\log \log n}\sum_{k=2}^n\left(\frac{1}{\log k}\right)^2\left\{{{\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top}\boldsymbol{M}_{k+1}\left(\boldsymbol{\Gamma}^{(p)}\right)}\boldsymbol{M}_{k+1}\left(\boldsymbol{\Gamma}^{(p)}\right)^{\top}\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right\} \\ &= {\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^\top\boldsymbol{\sigma\left(\boldsymbol{\Gamma}^{(p)}\right)}\boldsymbol{\nu}^{(i)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)}. \nonumber
    \end{align}
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.240692+00:00","domain":"probability theory","id":"claim_e72c53700c93d88c87920062487106ecc0fe8852100eaa794f131aa05a6d1480","kind":"lemma","schema_version":1,"statement":"[Lemma 62 of arXiv:2607.18104, '2607.18104'] Fix $M\in \N$ and consider a family of $(\delta,N)$-patched ASEPs $\big(\eta^{\textup{patch},N,i}_t\big)_{t \geq 0}$ for $i\in \lbr M \rbr$. Let $\big(\bar{\eta}^{N,i}_t\big)_{t \geq 0}$ be a family of unwrapped $N$-periodic ASEPs such that for all $i\in \lbr M \rbr$ and $N\in \N$
\begin{equation}
    \eta^{\textup{patch},N,i}_0 =  \bar{\eta}^{N,i}_0  
\end{equation} almost surely. Fix some $T>0$. Assume that \eqref{eq:DominationAssumptionPatch} holds for the processes in the definition of $\big(\bar{\eta}^{N,i}_t\big)_{t \geq 0}$. Then there exists a coupling $\mathbf{P}_{\ast}$ and  $c_1,C_1>0$ such that for all $\delta>0$
\begin{align}
\liminf_{N \rightarrow \infty}\mathbf{P}_{\ast}\left( \bar{\eta}^{N,i}_t = \eta^{\textup{patch},N,i}_t  \ \forall t \in [0,T N^{3/2}] , \,  i \in \lbr M \rbr\right) \geq 1- C_1\exp(-c_1\delta^{-1}) . 
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:08.954678+00:00","domain":"probability theory","id":"claim_e72f0dbc58b76f97ca3246cebb9c0765d6475b8a957f4070ecab4a482d763243","kind":"theorem","schema_version":1,"statement":"[Corollary cor:two_sided_current of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Under the assumptions of Theorem~(thm:conc_current of the paper), for all $t>0$ and $a>0$,
\begin{align}
  \mathbb{P}^\nu\left(\overline{J}_t(U) - \E^\mu[\overline{J}_t] \leq -a\right)
  &\leq
  \left\|\frac{\mathrm{d}\nu}{\mathrm{d}\mu}\right\|_{L^2(\mu)}
  \exp\bigl[-tI^J\bigl(\E^\mu[\overline{J}_t] - a\bigr)\bigr],

\end{align}
and consequently
\begin{align}
  \mathbb{P}^\nu\left(\bigl|\overline{J}_t(U) - \E^\mu[\overline{J}_t]\bigr| \geq a\right)
  \leq
  2\left\|\frac{\mathrm{d}\nu}{\mathrm{d}\mu}\right\|_{L^2(\mu)}
  \exp\Bigl[-t\min\bigl(I^J(\E^\mu[\overline{J}_t] + a), I^J(\E^\mu[\overline{J}_t] - a)\bigr)\Bigr].

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:45:32.045617+00:00","domain":"probability theory","id":"claim_e731907b1d1876f26ef246bf41ffb4cb8dbb2ae0420b0ca4a3d6064cd2c4db07","kind":"definition","schema_version":1,"statement":"[Definition def_0_limdif of arXiv:2411.13972, 'The Stochastic Bessel operator at high temperatures'] ~\\ \emph{
The limiting diffusion $r_\mu$ is defined as follows:}
\begin{itemize}
	\item \emph{It starts at $0$ at time $0$: $r_\mu(0) = 0$.}
	\item \emph{It then follows a Brownian motion with drift $a/4$  reflected downwards at $0$ (built from $W$)
\begin{align}
	r^+:= W(t) + at/4 -  \sup_{s \leqslant t} \big(W(s) +as/4\big)\vee 0\,
\end{align}
until its first hitting time of the critical line $c_\mu(t)$ from (equation criticalline of the paper).}
\item \emph{If it reaches $t \mapsto c_\mu(t)$ in a finite time, it immediately restarts at $0$ at this time, then follows a reflected downwards at $0$ Brownian motion with another drift $-(a+1)/4$ (also built from $W$) 
\begin{align}
	r^-:= W(t) - (a+1)t/4 -  \sup_{s \leqslant t} \big(W(s) - (a+1)s/4\big)\vee 0\
\end{align}
until its first hitting time of the critical line $c_\mu(t)$ from (equation criticalline of the paper).}
\end{itemize}
\emph{And so on, $r_\mu$ alternating between $r^+$ and $r^-$ each time it hits $t \mapsto c_\mu(t)$ and restarts at $0$.
Note that the probability that $r^+$ reaches the critical line decreases with time. On the other hand, since $a>0$, $r^-$ almost surely hits the critical line in a finite time.
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.854389+00:00","domain":"probability theory","id":"claim_e735ca06ecf990c854134cdc82a86c08b554307669258d91ba3f2a4642783da0","kind":"definition","schema_version":1,"statement":"[Definition def:l_and_bb_pin of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] Let $x \in (0,1)$, and let $l^x \in C_0$ be defined by
	\begin{equation*}
		l^x_{\xi} \coloneqq \frac{\xi}{x} \, \mathds{1}_{[0,x]}(\xi) + \frac{1-\xi}{1-x} \, \mathds{1}_{(x,1]}(\xi), \quad \xi \in [0,1].
	\end{equation*}
	Consequently, we define the stochastic process $\beta^{\mathrm{pin},x} \coloneqq \big(\beta_{\xi} - \beta_x  l_{\xi}^x \big)_{\xi \in [0,1]}$. Note that the paths of $\beta^{\mathrm{pin},x}$ are in $C_0$, and we have $\beta^{\mathrm{pin},x}_x = 0$ by construction.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:25:39.086736+00:00","domain":"probability theory","id":"claim_e73e10662666f57fa564db979213d535806c427a5b8cab358102e21a8d7a2d1d","kind":"definition","schema_version":1,"statement":"[Definition def:strip_flow of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Let $\eta\in \{0,1\}^2$. A stochastic flow on $I\times {\mathbb R}$ driven by $\mathcal W$ with boundary conditions $\eta$ is a family of processes 
$$
\mathcal S := \left\{\bigl(\mathcal S_{r,x}(a),\, x \ge r \bigr)\right\}_{(a,r) \in I \times {\mathbb R}}
$$
with the regularity properties (item:R1 of the paper)--(item:R3 of the paper) in Definition~(def:flow of the paper) (restricted to $I\times {\mathbb R}$) such that for each fixed $(a,r)\in I\times {\mathbb R}$,  $\mathcal S_{r,\cdot}(a)$ is the almost sure unique strong solution to~(equation eq:SDE_gener of the paper) and satisfies the boundary conditions $\eta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.473808+00:00","domain":"probability theory","id":"claim_e748d30a842be05754a0cdd8dc305ba29a49280ed165e22753049f597a39fb3a","kind":"lemma","schema_version":1,"statement":"[Lemma eq:dI-budget of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:aggregate-jet-budget}
Uniformly in \(O\in\mathcal O_{N,L}\),
\begin{equation}
 \sum_{I\in[N]^p}\mathfrak d_I\le C N,
 \qquad
 \max_{I\in[N]^p}\mathfrak d_I\le Cq_N^2.
\end{equation}
Writing \(\alpha_I(J)=\partial_I\Psi_O(J)\), one also has
\begin{equation}
 \max_I\left\lvert\alpha_I(J)\right\rvert\le Cq_N,
 \qquad
 \sum_I\left\lvert\alpha_I(J)\right\rvert^2\le CN,
\end{equation}
and, for \(2\le k\le m+1\),
\begin{equation}
 \left\lvert\partial_I^k\Psi_O(J)\right\rvert
 \le C_k\mathfrak d_Iq_N^{k-2}.
\end{equation}
Consequently, for \(2\le k\le m+1\),
\begin{align}
 \left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kF_O(J)
 \left(\left\lvert\alpha_I(J)\right\rvert^k+
       \mathfrak d_Iq_N^{k-2}\right),
 \\
 \sum_I\left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kNq_N^{k-2}F_O(J).

\end{align}
All constants are uniform in \(J,N,O\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.290855+00:00","domain":"probability theory","id":"claim_e74a45e3fac23816dcfd28c86111597a68c1a8cb5686cb481451497d648ff8cb","kind":"definition","schema_version":1,"statement":"[Definition fixptfun of arXiv:2605.06887, 'Law of large numbers for activated random walk on villages'] Define the function $\phi:\mathbb{R}_+^{V} \rightarrow{\mathbb{R}^{V}}$ as follows: for $m \in \mathbb{R}_+^{V}$ and $x \in V$, set
\begin{equation} 
     \phi(m)_x = (\sigma_x - \frac{\lambda_x}{1+\lambda_x})\left( 1-e^{-\beta(m)_x}\right) + \beta(m)_x
\end{equation}
We call $\phi$ the fixed point function of the VARW model.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.300991+00:00","domain":"probability theory","id":"claim_e75671ced7537ab40153dcd0a2b259f81b7a5d1f74f9dab39de630900b2b5d6e","kind":"lemma","schema_version":1,"statement":"[Lem lemma: dlp with convex sums of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $\delta>0$ and $N\in \mathbb N$.
	Let $(\mu_i),(\nu_i)\in \mathcal P(\mathbb R^d)^N$ be such that $d_{\mathrm{LP}}(\mu_i,\nu_i)<\delta$ for all $i$. We set
	\begin{equation*}
		\mu=\sum_{i=1}^N\lambda _i\mu_i,\qquad \nu=\sum_{i=1}^N\gamma _i\nu _i,
	\end{equation*}
	where $(\lambda_i)$ and $ (\gamma_i)$ are sequences of nonnegative real numbers such that $\lambda_1+\ldots+\lambda_N=\gamma_1+\ldots+\gamma_N=1$. Then,
