{"assumptions":[],"created_at":"2026-10-27T22:57:49.906284+00:00","domain":"probability theory","id":"claim_e8925237fbe7c65986124037a394913b3e130b337f98d611b417c8712cb4b2fd","kind":"theorem","schema_version":1,"statement":"[Theorem thm:ergodicity of upper of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an upper probability. Then the following four statements are equivalent:
	\begin{longlist}
		\item $V$ is ergodic;
		\medskip
		\item there exists $Q\in\operatorname{core}(V)\cap \mathcal{ M}^e(T)$ such that $V(A)=Q(A)$ for any $A\in\mathcal{I}$, and 
		\[\lim_{n\to\infty}\int\frac{1}{n}\sum_{i=0}^{n-1} f\cdot(g\circ T^i)dV=\left(\int fdV\right)\left(\int gdQ\right)\]
		for any $f,g\in B(\Omega,\mathcal{F})$ such that $g\ge 0$;
		\medskip
		\item there exists $Q\in\operatorname{core}(V)\cap \mathcal{ M}(T)$ such that 
		\[\lim_{n\to\infty}\int\frac{1}{n}\sum_{i=0}^{n-1} 1_B\cdot(1_C\circ T^i)dV=V(B)Q(C)\]
		for any $B,C\in \mathcal{F}$;
		\medskip

		\item there exists $Q\in\Delta^{\sigma}(\Omega,\mathcal{F})$ such that  $V|_{\mathcal{I}}\ll Q|_{\mathcal{I}}$ (i.e., for any $A\in \mathcal{I}$ if $Q(A)=0$ then $V(A)=0$) and
		\begin{equation}
			\liminf_{n\to\infty}\int\frac{1}{n}\sum_{i=0}^{n-1} 1_B\cdot(1_C\circ T^i)dV\ge V(B)Q(C)\text{ for any }B,C\in\mathcal{F}.
		\end{equation}
	\end{longlist}","status":"unverified"}

