{"assumptions":[],"created_at":"2026-10-27T12:52:05.701005+00:00","domain":"probability theory","id":"claim_e8cc9483f8ce7da50beac4fc289c3d7ea765dc8d32b1a16a98e9192c27c9cc2f","kind":"concept","schema_version":1,"statement":"[Lem kernelfrominf of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] There exists $\overline{c} > 0$ such that, if $r,r'$ are large enough, given any $n \geq 0$, $x,\widetilde{x} \in {\rm D}_n$ and $k,l \geq 1$ such that $l \geq k+2$, ${\rm B}(x;k+r) \subseteq {\rm B}(\widetilde{x};l)$ and $\overline{{\rm B}(\widetilde{x};l+r')}\subseteq {\rm D}_n$, it holds that:
	\begin{equation}
		\mathbb{P}_{y} ( Z_{\tau_{\partial {\rm B}(\widetilde{x};l+r')}}=\widetilde{x}+z)= \Pi_{{\rm B}(0;l+r')}(0,z)(1+O({\rm e}^{-\overline{c}r'}))
	\end{equation} uniformly over all $z \in \partial {\rm B}(0;l+r')$ and $y \in {\rm B}(\widetilde{x};l)$; 
\begin{equation}
		\mathbb{P}_{y} ( Z_{\tau_{\partial {\rm B}(\widetilde{x};l+r')}}=\widetilde{x}+z\,|\, \tau_{\partial {\rm B}(\widetilde{x};l+r')} <  \overline{\tau}_{{\rm B}(x;k)})= \Pi_{{\rm B}(0;l+r')}(0,z)(1+O({\rm e}^{-\overline{c}r')}))
	\end{equation} uniformly over all $z \in \partial {\rm B}(0;l+r')$ and $y \in {\rm B}(\widetilde{x};l)\setminus ({\rm B}(x;k) \setminus \partial_i {\rm B}(x;k))$; and, finally, 
	\begin{equation}
		\mathbb{P}_{y}\big( Z_{\tau_{{\rm B}(x;k)}} = x+w \,\big| \tau_{{\rm B}(x;k)}< \tau_{\partial {\rm B}(\widetilde{x};l+r')}\big)=\amalg_{{\rm B}(0;k)}(w)(1+O({\rm e}^{-\overline{c}(r \wedge k)}))
	\end{equation}
	uniformly over all $w \in \partial_i {\rm B}(0;k)$ and $y \in {\rm B}(\widetilde{x};l+r') \setminus {\rm B}(x;k+r)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:29:21.899227+00:00","domain":"probability theory","id":"claim_e8cf7c709c0c1732dc4020d004f97aa6928fb88169d89e7e24afc09b7cd49853","kind":"concept","schema_version":1,"statement":"[Theorem 9 of arXiv:2608.00449, 'First-order phase transitions in the hard-core model'] \label[theorem]{thm:arytreedynamics}
    Let $f_{d,\lambda}:[0,\infty]\to[0,\infty]$ be the function with $f_{d,\lambda}(\infty)=0$ and $f_{d,\lambda}(r) = \lambda(1+r)^{-d}$. Then, for all integers $d\ge 2$, the following hold.
    \begin{enumerate}
        \item For all $\lambda>0$, $f_{d,\lambda}$ has exactly one fixed point $r^*$.
        \item If $0<\lambda < \lambda_c(d+1)$, then $r^*$ is an attracting fixed point of $f_{d,\lambda}$ whose basin of attraction is $[0,\infty]$.
        \item If $\lambda > \lambda_c(d+1)$, then $r^*$ is a repelling fixed point and there exist $r^0 < r^* < r^1$ such that $\{r^0,r^1\}$ is an attracting periodic orbit of $f_{d,\lambda}$ whose basin of attraction is $[0,\infty]\setminus\{r^*\}$. More precisely, if $r\in [0,r^*)$, then $\lim_{n\to\infty}f_{d,\lambda}^{\circ 2n}(r)=r^0$, and if $r\in(r^*,\infty]$, then $\lim_{n\to\infty}f_{d,\lambda}^{\circ 2n}(r)=r^1$.
        \item We have
        \[ \lim_{\lambda\downarrow \lambda_c(d+1)}|r^1-r^0| = 0. \]
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:44:27.969130+00:00","domain":"probability theory","id":"claim_e8cfe22b91d5a2008cd074facef8d2d24a4c85c3a18b478f13df4856c2cb2676","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] Let $\alpha\in (0,2), m>0$ and $\boldsymbol{Y}$ be the relativistic stable process.
    Then the density $p_\lambda$ of the corresponding process $\boldsymbol{X}$ with resetting exists for all $\lambda>0, t>0$ and,  for any $x\in\Rd$,:
    \begin{enumerate}
        \item If $\lambda > m $ then
        \begin{align*}
          p_\lambda(t,x,y) 
          &\sim  \frac{\lambda\alpha m^{\frac{d+\alpha-1}{2\alpha}}}{2^{\frac{d-\alpha+1}{2}}\pi^{\frac{d-1}{2}}\Gamma(1-\frac{\alpha}{2})(\lambda-m)^2} \frac{e^{-m^{1/\alpha}|y|}}{|y|^{\frac{d+\alpha+1}{2}}} .
    \end{align*}
    \item If $\lambda = m$  then
        \begin{equation*}
        p_\lambda(t,x,y) \sim \frac{m^{\frac{d+\alpha-1}{2\alpha}}e^{-m^{1/\alpha}|y|}}{2^{\frac{d+\alpha-1}{2}}\pi^{\frac{d-1}{2}} |y|^{\frac{d-\alpha+1}{2}}}
        \int_0^{\frac{\sqrt{2^\alpha m}}{|y|^{\alpha/2}}t}\eta(s,1)\, \dx[s].
    \end{equation*}

    \item If $\lambda < m$ and $\frac{t}{|x|^{\alpha/2}}<M$ for some constant $M>0$ then
       \begin{equation*}
        \begin{split}
            p_\lambda(t,x,y) & \sim 
            \left(\lambda + e^{m^{1/\alpha}\langle \frac{y}{|y|},x\rangle }\frac{\eta\left(\frac{t}{|y-x|^{\alpha/2}}\sqrt{2^\alpha m},1\right) (m-\lambda)}{\eta\left(\frac{t}{|y|^{\alpha/2}}\sqrt{2^\alpha m},1\right)}\right) \\
            &\times \frac{ m^{\frac{d-\alpha-1}{2\alpha}}e^{-m^{1/\alpha}|y|}}{2^{\frac{d+\alpha-1}{2}}\pi^{\frac{d-1}{2}}|y|^{\frac{d-\alpha+1}{2}}}
        \int_0^{\frac{\sqrt{2^\alpha m}}{|y|^{\alpha/2}} t} e^{(m-\lambda)\frac{|y|^{\alpha/2}}{\sqrt{2^\alpha m}}s} \eta(s,1)\, \dx[s].
        \end{split}
    \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:08.954829+00:00","domain":"probability theory","id":"claim_e8dc57fcf9963396c8107bf667fe19b6487d904322694724cfc8f6c17ec1fbed","kind":"lemma","schema_version":1,"statement":"[Lemma lem:subgamma of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let $\tilde\sigma^2 > 0$ and $c > 0$. 
Consider the convex function on $[0, 1/c)$
\begin{align}
\phi(k) = \frac{k^2\tilde\sigma^2}{2(1 - ck)}.
\end{align}
Its Legendre transform $\phi^\ast(a)$ is, for $a > 0$,
\begin{align}
  \phi^\ast(a)
  \equiv \sup_{0 \leq k < 1/c}\left[ka - \frac{\tilde\sigma^2 k^2}{2(1 - ck)}\right]
  = \frac{\tilde\sigma^2}{c^2}h\left(\frac{c a}{\tilde\sigma^2}\right),

\end{align}
with supremum attained at $k^\ast = c^{-1}\bigl(1 - \sqrt{\tilde\sigma^2/(\tilde\sigma^2 + 2ca)}\bigr) > 0$
and we define the auxiliary function $h(u) \equiv 1 + u - \sqrt{1 + 2u}$.
Moreover, we have $h(u) \geq u^2/[2(1+u)]$ for $u \geq 0$, i.e.,
\begin{align}
  \phi^\ast(a) \geq \frac{a^2}{2(\tilde\sigma^2 + ca)}.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.604247+00:00","domain":"probability theory","id":"claim_e8dfa72e24c680f0f3eb1ed98112bdaa7c62c9d0fd83703d6c2931bf613a97dc","kind":"definition","schema_version":1,"statement":"[Definition eq:MF1 of arXiv:2606.13264, 'Interference Queueing Networks: A Replica Mean-Field Approach in the Symmetric Setting'] Consider $A_{l,i}$ and $D_{l,i}$  Poisson processes of intensity $\lambda\rm{dx}$ and Poisson processes of intensity $\rm{dxdy}$ respectively, each being independent in $l,i$. The initial condition
\[
