{"assumptions":[],"created_at":"2026-10-26T19:33:46.769829+00:00","domain":"probability theory","id":"claim_e904aa924f969f771605bd08b8908353d1108af6e6ab42ded775d7e31cf64dfd","kind":"lemma","schema_version":1,"statement":"[Lemma 32 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $k \in \mathbb{N}$, $b > 0$, a sequence of positive real numbers $\{d_n\}_{n \geq 1}$ such that $d_n \rightarrow \infty$, and set $T_n = \lceil b d_n \rceil$. In addition, fix $p \in (0,\infty)$ and set $\sigma = \sqrt{p(1+p)}$. Suppose that $(X^n, Y^n)$ is a sequence of random vectors in $\mathfrak{W}_k \times \mathfrak{W}_k$, such that almost surely $X_i^n \leq Y_i^n$ for $i \in \llbracket 1, k \rrbracket$. Define $(\bar{X}^n, \bar{Y}^n) \in \weylc_k \times \weylc_k$ through
\begin{equation}
\bar{X}_i^n = \sigma^{-1} d_n^{-1/2} X_i^n  \mbox{ and } \bar{Y}_i^n = \sigma^{-1} d_n^{-1/2}(Y_i^n  - p T_n) \mbox{ for } i \in \llbracket 1, k \rrbracket,
\end{equation}
and suppose that $(\bar{X}^n,\bar{Y}^n)$ converges weakly to a random vector $(\bar{X}^{\infty},\bar{Y}^{\infty}) \in \weylc_k \times \weylc_k$ as $n \rightarrow \infty$. Then we have the following statements.
\begin{enumerate}
\item[(a)] There exists $N_0 \in \mathbb{N}$, depending on $k, b$, and the sequence $\{d_n\}_{n \geq 1}$, such that for $n \geq N_0$ the sets $\Omega_{\ice}(0, T_n, X^n, Y^n)$ are non-empty almost surely. Consequently, for $n \geq N_0$ we can define a $\llbracket 1, k \rrbracket$-indexed line ensemble $\mathfrak{L}^n = \{L^n_i\}_{i = 1}^k$ on $\llbracket 0, T_n \rrbracket$, such that for all increasing paths $B_1, \dots, B_k$, we have
\begin{equation}
\mathbb{P}\left(\cap_{i = 1}^k \{L^n_i = B_i\}\right) = \mathbb{E}\left[ \mathbb{P}_{\ice, \operatorname{Geom}}^{0,T_n, X^n, Y^n} \left(\cap_{i = 1}^k \{Q_i = B_i\}  \right) \right].
\end{equation}
\item[(b)] If $n \geq N_0$ and $\mathfrak{L}^n$ is as in part (a), define the $\llbracket 1, k \rrbracket$-indexed line ensemble $\mathcal{L}^n = \{\mathcal{L}_i^n\}_{i = 1}^k$ through
\begin{equation}
\mathcal{L}_i^n(t) = \sigma^{-1} d_n^{-1/2} \cdot \left( L_i^n(t d_n) - td_n p \right) \mbox{ for } t \in [0,b] \mbox{ and } i \in \llbracket 1, k \rrbracket.
\end{equation}
Then, $\mathcal{L}^n$ converges weakly to $\mathbb{P}_{\operatorname{avoid}}^{0,b,\mu}$ from (\ref{Eq.RandomBryMeas}), where $\mu$ is the law of $(\bar{X}^{\infty},\bar{Y}^{\infty})$.
\end{enumerate}","status":"unverified"}

