{"assumptions":[],"created_at":"2026-10-27T19:46:25.369245+00:00","domain":"probability theory","id":"claim_e94b0e11a15585ee787eb20332291dc0845ca11b36b716a9ad101c46c593317b","kind":"concept","schema_version":1,"statement":"[Theorem thm:deftwist of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] The (zero boundary) twist field correlations $\sigma_{\rm tw}^D(z_{1}, z_{2},\dots, z_{n})$ can be defined via three equivalent ways by taking the following limits. 
\begin{enumerate}[i)]

\item As $\delta\to 0$, we consider the limit of
\begin{equation}
\delta^{-n/16}\exp(n\mathbf{c}_\mathbb{D}^{\rm{loop}})\exp\left(-
\mu^{\rm loop}_{D}
\Big(\sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd},
t_{\gamma}>\delta
\Big)\right),
\end{equation}
where $\mathbf{c}_\mathbb{D}^{\rm{loop}}$ is an explicit constant 
that can be expressed through the Brownian loop measures
in the unit disk $\mathbb{D}$ and its complement
$\mathbb{C}\setminus\overline{\mathbb{D}}$:

$$\mathbf{c}_\mathbb{D}^{\rm{loop}}
=
\mu^{\rm loop}_{\mathbb{D}}(t_{\gamma}>1,
\indx_{\gamma}(0) \text{ odd})
-
\mu^{\rm loop}_{\mathbb{C}}(
\gamma \cap (\mathbb{C}\setminus\overline{\mathbb{D}})\neq\emptyset,
t_{\gamma}<1,
\indx_{\gamma}(0) \text{ odd}).
$$

\item
As $\max_{1\leq j\leq n}\varepsilon_j\to 0$, we consider the limit of
\begin{equation}
\prod_{j=1}^{n}
\Big(
\frac{1}{\varepsilon_j^{1/8}\sqrt{|\log \varepsilon_j|}}
\Big)
\left(\pi/2\right)^{n/2}\exp\left(-\mu^{\rm loop}_{D_{\varepsilon_1, \dots, \varepsilon_n}(z_1, \dots, z_n)}
\Big(\sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd}
\Big)\right).
\end{equation}
\item Consider the Brownian loop soup 
$\mathcal{L}_{D_{\varepsilon_1,\dots, \varepsilon_n}(z_1,\dots, z_n)}$
in the domain with holes
$D_{\varepsilon_1,\dots, \varepsilon_n}(z_1,\dots, z_n)$,
and let $(\overline C_i^{\varepsilon_1,\dots, \varepsilon_n})_{i \geq 1}$ denote the collection of topological closures of its clusters. 
(It is an infinite countable collection of random compact disjoint subsets in $D$.) 
As $\max_{1\leq j\leq n}\varepsilon_j\to 0$, we consider the limit of
\begin{equation}
\prod_{j=1}^{n}
\Big(
\frac{1}{\varepsilon_j^{1/8}\sqrt{|\log\varepsilon_j|}}
\Big)
\left(\pi/2\right)^{n/2}\mathbb{P}\left(\nexists \text{ path }\gamma\subseteq
\bigcup_{i \geq 1}
\overline{C}_i^{\varepsilon_1,\dots, \varepsilon_n}
\text{ with }\sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd}
\right).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.439903+00:00","domain":"probability theory","id":"claim_e9586eb09bf97dbf8c454205c894874fa343b7fa70a795bdee34c3b090e389d3","kind":"concept","schema_version":1,"statement":"[Thm 25 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\eta<1/4$ and $\varrho\in \hspace{0.1cm} ]0,1]$. Let $p$ as in \eqref{Developpement en série de Fourier par rapport à xi} and $q:=\bb{p}^2$. Let $\widetilde{p}$ be as in \eqref{Definition de p tilde}, $\mathscr{U}_p$ be given in \eqref{Ensemble des singularités} and $\widetilde{q}$ be as in \eqref{Dvpt de Borel pour le théorème central}. We assume that there exist ${\kappa_2}\in \hspace{0.1cm} ]0,1]$ such that, for $0\leq t\ll 1$,
    \begin{equation}
        \mathscr{V}(t):=\mathrm{Vol}\pr{\acc{\rho\in \T^{2d}\m|\m q(\rho)\leq t}}=\mc{O}(t^{\kappa_2})

    \end{equation}
    and ${\kappa_1}\in \hspace{0.1cm} ]0,1]$ such that for $0\leq t\ll 1$,
    \begin{equation}
        \mathrm{L}\Bigl(\pr{\mathscr{U}_p+B(0,t)}\cap[0,1]^d\Bigl)=\mc{O}(t^{{\kappa_1}}).

    \end{equation}
    Let $\alpha$ be such that
    \begin{equation}
        N^{-\eta\min(\varrho,{\kappa_1})}\ll\alpha\ll 1.
    \end{equation}
    Then, for all $\psi\in \mathscr{C}^\infty_c(\R)$,
    \begin{equation}
       \mathrm{tr}\!\croch{\psi\pr{\frac{\widetilde{q}_{N}}{\alpha}}} =N^d\pr{\int_{\T^{2d}}\psi\pr{\frac{q(\rho)}{\alpha}}d\rho+\mc{O}\pr{N^{-\eta{\kappa_1}}}+\mc{O}\pr{N^{-\varrho \eta}\alpha^{-1}}}.

    \end{equation}
    If $\chi\in \mathscr{C}^\infty_c(\R,[0,+\infty[)$, such that $\chi(0)>0$ then,
    \begin{equation}
        \begin{split}
            \log\det\pr{\widetilde{q}_N+\alpha\chi\pr{\frac{\widetilde{q}_N}{\alpha}}} &= N^d\biggl(\int_{\T^{2d}}\log(q(\rho))d\rho+\mc{O}\pr{N^{-\eta{\kappa_1}}\bb{\log(\alpha)}}\\
            &\mm\mm+\mc{O}\pr{\alpha^{\kappa_2}\bb{\log(\alpha)}}+\mc{O}\pr{N^{-\varrho\eta}\alpha^{-1}}\biggl).
        \end{split}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.749770+00:00","domain":"probability theory","id":"claim_e95fcd4a3e8bacd95d1719f0a9b7a71746d8325d25c17010a4fc8f6f3b97952c","kind":"theorem","schema_version":1,"statement":"[Proposition prop:grid-norm-recursion-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Let \(q\in(1,2)\) and assume \(\rho(q)<1\).  Fix \(\alpha>1\).  Then there
exists \(C_{q,\alpha}<\infty\) such that, for all integers
\(0<m\le k\le n\),
\begin{equation}
    A_{k,n}
    \le
    C_{q,\alpha} r_n^{q/2}\rho(q)^m A_{k-m,n}
