{"assumptions":[],"created_at":"2026-10-27T12:10:07.422837+00:00","domain":"probability theory","id":"claim_ec2a39cf4671e8b351d691aff7a7df542401ee9c94b1cf159891fe628cf95812","kind":"concept","schema_version":1,"statement":"[Theorem eq:array-assumptions of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:bulk-universality}
Fix \(p\ge3\), \(m\ge2\), \(L>0\), \(\varepsilon>0\),
\(V\in\mathcal V_m\), and either \(f\in\mathcal F_m\) or
\(f=\ell_\eta\) for fixed \(\eta>0\).  For each \(N\), let
\(J=(J_{I,N})_{I\in[N]^p}\) have independent, not necessarily
identically distributed coordinates satisfying
\begin{equation}
 \sup_{N,I}\mathbb E e^{\abs{J_{I,N}}/K}\le2,
 \qquad
 \mathbb E J_{I,N}^r=\mathbb E G^r,\quad 1\le r\le m,
\end{equation}
where \(G\sim\mathcal N(0,1)\).  Let \((G_I)\) be independent standard Gaussians.  Then there is a constant
\[
 C=C(p,m,L,K,\varepsilon,V,f)<\infty
\]
such that, for all sufficiently large \(N\),
\begin{equation}
 \left|\log\frac{\mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f)}
 {\mathbb E\mathcal Z_{N,L}^G(V,\varepsilon,f)}\right|
 \le C Nq_N^{m-1}.
\end{equation}
Consequently, for every \(p\ge3\) and every \(m\ge2\),
\begin{equation}
 \Phi_{N,L}^J(V,\varepsilon,f)-\Phi_{N,L}^G(V,\varepsilon,f)\longrightarrow0.
\end{equation}
Assume additionally that
\begin{equation}
 (m-1)(p-2)>2.
\end{equation}
Then
\begin{equation}
 \frac{\mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f)}
 {\mathbb E\mathcal Z_{N,L}^G(V,\varepsilon,f)}\longrightarrow1,
\end{equation}
and
\begin{equation}
 \Phi_{N,L}^J(V,\varepsilon,f)-\Phi_{N,L}^G(V,\varepsilon,f)=o(N^{-1}).
