{"assumptions":[],"created_at":"2026-10-27T17:11:02.387343+00:00","domain":"probability theory","id":"claim_ed3732876a017f3a25d4198cd06c7c91672b51c6fd400c909f2309cd243ae1d1","kind":"concept","schema_version":1,"statement":"[Theorem thm:local_clt_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
