\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.337776+00:00","domain":"probability theory","id":"claim_efa79627386d7b30c4093a0a68ad39c1c352c2b7a856a33910c3af46e06fd1c2","kind":"definition","schema_version":1,"statement":"[Definition 6 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K$ be a graph over $V$. We define the self-overlap of $K$:

\begin{equation} 
    SOV(K) = \operatorname*{lim}_{\eps \to 0} \operatorname*{plimsup}_{n \to +\infty}  \max_{\sigma \in \Sym_n}\max_{\underset{|\mc{A}| \geq \eps n}{\mc{A} \subseteq \Der \sigma}}  \operatorname*{min}_{v \in \mc{A}} w_{(K \land_\sigma K)}(v).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.685392+00:00","domain":"probability theory","id":"claim_efaacf9dfeca7a91cf3ed705a278bdb1a224c35b9c908079918bf776b471d429","kind":"lemma","schema_version":1,"statement":"[Lemma 3 (Weighted-report cluster linearization) of arXiv:2608.30916, 'Selection-Aware Stress Testing for Interactive Agents'] Conditional on $\mathcal F_{\Dcal}$, suppose the conditions of Theorem~\ref{thm:validity} hold. Let $\mu_m=\E(H_{1,m}\mid\mathcal F_{\Dcal})$ and $\Phi_{k,m}=\nabla F_m(\mu_m)^\top(H_{k,m}-\mu_m)$. Uniformly over the finite family $\Jcal_0$,
\begin{equation}
