{"assumptions":[],"created_at":"2026-10-27T14:13:22.515686+00:00","domain":"probability theory","id":"claim_f16e4fe542dd64b82b60ffd13122dabac72322a57efbc5edb39fff6b3779ad67","kind":"concept","schema_version":1,"statement":"[Thm CM results kappa>0 of arXiv:2505.16093, 'Multiple chordal SLE($\kappa$) and quantum Calogero-Moser system'] The multiple chordal SLE($\kappa$) is described by the partition function $\mathcal{Z}(\boldsymbol{x})$, we have
\begin{equation}
\mathcal{L}_j \mathcal{Z}(\boldsymbol{x})= h \mathcal{Z}(\boldsymbol{x})   
\end{equation}
where $\mathcal{L}_j$ is the null vector differential operator:
\begin{equation}
\mathcal{L}_j=  \frac{\kappa}{2}\left(\frac{\partial}{\partial x_j}\right)^2 +\sum_{k \neq j}\left( \left(\frac{2}{x_k-x_j}\right) \frac{\partial}{\partial x_k}-\frac{6-\kappa}{\kappa}\frac{1}{\left(x_k-x_j\right)^2}\right)  
\end{equation}

\begin{itemize}


\item[(i)] We transform the partition function $\mathcal{Z}(\boldsymbol{x})$ into an eigenfunction of quantum Calogero-Moser system by multiplying Coulomb gas correlation $\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{x})$ 

\begin{equation}
\tilde{\mathcal{Z}}(\boldsymbol{x})=\Phi_{\frac{1}{\kappa}}^{-1}(\boldsymbol{x})\mathcal{Z}(\boldsymbol{x})   
\end{equation}

where $$\Phi_{r}(\boldsymbol{x})=\prod_{1 \leq j<k \leq n}\left(x_j-x_k\right)^{-2r}$$

 Then $\tilde{\mathcal{Z}}(\boldsymbol{x})$ satisfies 
 $$\left(\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}\right)  \tilde{\mathcal{Z}}(\boldsymbol{x}) = h\tilde{\mathcal{Z}}(\boldsymbol{x})$$  where the differential operator $\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}$ is given by

\begin{equation}
\begin{aligned}
\Phi_{\frac{1}{\kappa}}^{-1} \cdot \mathcal{L}_j \cdot \Phi_{\frac{1}{\kappa}}= & \frac{\kappa}{2} \partial_j^2- F_j \partial_j+\frac{1}{2\kappa} F_j^2-\frac{1}{2} F_j^{\prime} -\sum_{k \neq j}\left(f_{j k}\left(\partial_k-\frac{1}{\kappa} F_k\right)-\frac{6-\kappa}{2\kappa} f_{j k}^{\prime}\right) \\
&=\frac{\kappa}{2} \partial_j^2- \sum_{k} f_{jk}(\partial_j+\partial_k)\\
&-\frac{1}{\kappa}\left[\sum_k \sum_{l \neq k} f_{j k} f_{j l}-2\sum_{k\neq j} f_{j k}^2\right]- F_{j}'
\end{aligned}   
\end{equation}

 The sum of the null vector differential operators $\mathcal{L}=\sum \mathcal{L}_j$ is given by
\begin{equation}
\Phi_{-\frac{1}{\kappa}} \cdot \mathcal{L} \cdot \Phi_{\frac{1}{\kappa}}=\kappa H_n\left(\frac{8}{\kappa}\right)
\end{equation}

where $H_{n}(\beta)$ with $\beta=\frac{8}{\kappa}$ is  the quantum Calogero-Moser Hamiltonian
$$H_n(\beta)=\sum_{j=1}^n \frac{1}{2} \frac{\partial^2}{\partial x_j^2}-\frac{\beta(\beta-2)}{16} \sum_{1 \leq j<k \leq n} \frac{1}{\sin ^2\left(\frac{x_j-x_k}{2}\right)}
$$
\item[(ii)]
The commutation relation between growing two SLEs can be expressed as
$$[\mathcal{L}_j,\mathcal{L}_k]= \frac{1}{\sin^2(\frac{x_j-x_k}{2})}(\mathcal{L}_k-\mathcal{L}_j)$$
\end{itemize}
then
$$[\mathcal{L}_j,\mathcal{L}_k]\mathcal{Z}(\boldsymbol{x})= \frac{1}{\sin^2(\frac{x_j-x_k}{2})}(\mathcal{L}_k-\mathcal{L}_j)\mathcal{Z}(\boldsymbol{x})=0$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

