        \end{equation*}
        By the independence of the marking we have that $|J_k|$, $k \in \mathbb{N}$, are independent Poisson random variables with means given by
        \begin{equation*}
            \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})}(|J_k|) = \frac{1}{2}\mu_{\rm a}(B(x, \varepsilon/2))(1-e^{-c/2k})(e^{-\Tilde{c}s})
