{"assumptions":[],"created_at":"2026-10-27T17:42:08.473641+00:00","domain":"probability theory","id":"claim_f1f60ed287cb00e519099a9a9c768afabf12eeafb088051826015f0569fdd867","kind":"lemma","schema_version":1,"statement":"[Lemma lemma9 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $\varphi$ be a characteristic satisfying (C1 of the paper)-(C2 of the paper). For $u \in \mathcal{I}$ and $n \geq -1$, let $\mathcal{J}_{u} \subseteq \mathcal{I}$ such that $\mathcal{P}_{u} \subseteq \mathcal{J}_{u}$ and  $\mathcal{J}_{u} \cap u\mathcal{I} = \emptyset$. Define the sub-$\sigma$-algebra of $\mathcal{F}$
\begin{align} 
\mathcal{C}_{u}^{(n)} \coloneqq \sigma(\pi_{v}: v\in \mathcal{J}_{u} \cup \mathcal{I}_{u}^{(n)}).
\end{align}
\noindent If $u =\varnothing$ and $n=-1$, we define $\mathcal{C}_{\varnothing}^{(-1)}$ as the trivial $\sigma$-algebra. Then, for $t \in \mathbb{R}$, $u \in \mathcal{I}$ and $k \in \mathbb{N}_{0}$, 
\begin{align}  
\varphi_{u}^{(k)}(t-S(u)) \stackrel{a.s.}{=} \mathbb{E}[\varphi_{u}(t-S(u)) \mid \mathcal{C}_{u}^{(k-1)}] \stackrel{a.s.}{=}  \mathbb{E}[\varphi_{u}(t-S(u)) \mid \mathcal{D}_{u}^{(k-1)}]. 
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:17:33.987904+00:00","domain":"probability theory","id":"claim_f2059057b8131c60c1e0edde342eae27d3cf4e35ea072b06450f7ef873e30a47","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] A quadruple $(u,v,w)$ is called a strong global solution to (P) if and only if for every finite time $T>0$ the following properties are satisfied, that is, $(u,v,w)$ is a
strong solution to (P) on $[0,T]$:
\begin{enumerate}\leftskip10pt
\item[(s1)] $u \in W^{1,2}(0,T\,;L^2(\Omega)) \cap L^\infty (0,T\,;H^1(\Omega)) \cap L^2(0,T\,;H^2(\Omega))$.\\[-0.3cm]
\item[(s2)] $v \in W^{1,\infty}(0,T\,;L^2(\Omega)) \cap L^\infty (0,T\,;H^1(\Omega))$.\\[-0.3cm]
\item[(s3)] $w \in W^{1,2}(0,T\,;L^2(\Omega)) \cap L^\infty (0,T\,;H^1(\Omega)) \cap L^2(0,T\,;H^2(\Omega))$.\\[-0.3cm]
\item[(s4)] The equation (\ref{Equation-1-1}) with (\ref{Equation-1-4}) is satisfied in the following variational sense:

\begin{equation*}
\qquad u'(t)-D_1 \Delta_N u(t)=u(t) \{c_1 v(t)-c_2 w(t)\} \quad \text{in} \quad L^2(\Omega),\quad \text{a.e.}~t \in (0,T),
\end{equation*}

where $-\Delta_N : D(-\Delta_N) \rightarrow L^2(\Omega)$ is the Laplacian with homogeneous Neumann boundary condition whose domain is given by 

\begin{equation*}
\qquad D(-\Delta_N):=\left\{ \eta \in H^1(\Omega)\,;\,\Delta \eta \in L^2(\Omega)~~\text{with}~~\nabla \eta \cdot \bm{n}=0~~\text{for a.e. on}~~\Gamma \right\}.
\end{equation*}

\item[(s5)] The equation (\ref{Equation-1-2}) is satisfied in the following variational sense:

\begin{gather*}
\qquad v'(t)+\left( \int_\Omega K(x,y) v(y,t)dy\right) v(t)=v(t) \{c_3 w(t)-c_4 u(t)\}\\
\qquad \text{in} \quad L^2(\Omega),\quad \text{a.e.}~t \in (0,T),
\end{gather*}

\item[(s6)] The equation (\ref{Equation-1-3}) with (\ref{Equation-1-5}) is satisfied in the following variational sense:

\begin{equation*}
\qquad w'(t)-D_2 \Delta_N w(t)+c_5 w(t)=c_6 \cdot 1-c_7 v(t) w(t) \quad \text{in} \quad L^2(\Omega),\quad \text{a.e.}~t \in (0,T),
\end{equation*}

where we denote by $1$ the constant function equal to $1$ on $\Omega \times [0,T]$.\\[-0.3cm]
\item[(s7)] $(u(0),v(0),w(0))=(u_0,v_0,w_0) \quad \text{in} \quad (L^2(\Omega))^3$.
\end{enumerate}
Throughout this paper, the notation $f'$ denotes the time derivative of $f$ in $L^2(\Omega)$.
Whenever no confusion arises, we use the same notation $f_t=f'$ in the initial-boundary value problems throughout this paper.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:56:11.144247+00:00","domain":"probability theory","id":"claim_f2067f7bdcba6a5b31e8e9cc228bda36a7c5acd30beab96d229cb14a941b976a","kind":"concept","schema_version":1,"statement":"[Lemma 10 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] For each $\kappa,\alpha, n>0$, there exists a non-negative function $\psi\in C^3[-n^{1/4}\kappa,0]$ such that the following properties hold:
