\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.255585+00:00","domain":"probability theory","id":"claim_f33cf1fb8ebf73fe5c6f965a2464f8a758d0aa3c4e90179e44fa8d32bb4cef13","kind":"theorem","schema_version":1,"statement":"[Prp 38 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] \quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]Suppose that there exists a measure $\nu$ satisfying $\rm{Reg}_{s_0,s_1}$.
    Then $\rm{UP}$ implies $\rm{LRES}(1+s_0-s_1)$ with 
    $c_{\rm{LR}}=\left[\frac{4c_u(\frac{1}{4}c_{\rm{UP}}+1)^{s_1}}{c_l(\frac{1}{16}c_{\rm{UP}})^{s_0}c_{\rm{UP}}}\right]^{-1}$.
     In particular, $\rm{(A3)}$ implies $\rm{(A2)}$.
\item [$\rm{(ii)}$]The assumption $\rm{(A1)}$ implies 
\begin{align}
  p(t,x,x)\lesssim c_{\rm{A1}} t^{-\frac{s_0}{1+s_0}},\qquad t<(\diam F)^{1+s_0},\;x\in F,
\end{align}
where $c_{\rm{A1}}=1+c_l^{-1}$.
\item[$\rm{(iii)}$] The assumption $\rm{(A2)}$ implies 
\begin{align}
  c_{\rm{A2}}t^{-\frac{s_1}{(1+s_0)\theta}}\lesssim p(t,x,x),\qquad t>0,\;x\in F.
\end{align}
Moreover, if $t<\frac{D_F^{(1+s_0)\theta}}{5c_{\rm{Exit}}}$, we can take $c_{\rm{A2}}=\frac{1}{100}\left[c_u(5c_{\rm{Exit}})^{\frac{s_1}{(1+s_0)\theta}} \right]^{-1}$.
Here, $D_F$ and $c_{\rm{Exit}}$ are given by
\begin{align*}
  D_F=\frac{1}{2}\diam F\wedge (2c_{\rm{LR}}^{-1}\diam F)^{1/\theta},\qquad c_{\rm{Exit}}=\frac{4^{2+s_0}}{3c_l c_{\rm{LR}}^{1+s_0}}.
\end{align*} 
\item[$\rm{(iv)}$]The assumption $\rm{(A3)}$ implies 
\begin{align}
  c_{\rm{A3}}t^{-\frac{\beta s_1}{1+\beta}}\lesssim p(t,x,x),\qquad t>0,\;x\in F,\;\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}.
\end{align}
Moreover, if $t<2\left[  \frac{C (\frac{1}{2}\diam F)^{1+\beta}}{\log 4}  \right]^{1/\beta} $, we can take $c_{\rm{A3}}=\frac{1}{4c_u}\left[ \frac{\log 4}{2^{\beta}C}\right]^{\frac{\beta s_1}{1+\beta}}$.
Here, $C$ is given by $C=\frac{c_l(c_{\rm{LR}}/4)^{1+s_0}}{4c_u c_{\rm{UR}}} \left( \frac{1}{256}\frac{[c_l(c_{\rm{LR}}/4)^{1+s_0}]^2}{c_u c_{\rm{UR}}} \right)^{\beta}$. 
\item[$\rm{(v)}$]Assume $\rm{(A3)}$. Then, for any $r<\frac{1}{2}\diam F$,
\begin{align*}
  P_x(\sigma_{B(x,r)^c}\leq t)\leq 2 \exp\left[ -\g{c}{summ}\frac{r^{1+\beta}}{t^{\beta}}\right],
\end{align*}
where $\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}>0$ and $\g{c}{summ}=\frac{c_l(c_{\rm{LR}}/4)^{1+s_0}}{4c_u c_{\rm{UR}}} \left( \frac{1}{256}\frac{[c_l(c_{\rm{LR}}/4)^{1+s_0}]^2}{c_u c_{\rm{UR}}} \right)^{\beta}$.
\end{itemize}","status":"unverified"}

