\left\|\sum_{i'=1}^{r+1}\alpha_{i'}\prod_{j=1}^{i'-1}B_{j}\nabla^{(i')}P_tf(x)\right\|_{A_0}^2\le  P_t\left(\left\|\sum_{i'=1}^{r+1}\left(\sum_{i=0}^{i'-1}\alpha_{i'-i}\frac{t^i}{i!} \prod_{j=1}^{i'-1}B_{j}\right)\nabla^{(i')}f\right\|_{A_0}^2\right)(x),\end{equation}
where $\alpha_1=1$.","status":"unverified"}

