        \left|\frac{q_e}{p_e}-1\right|\longrightarrow0 .
\end{equation}
Moreover,
\begin{equation}

        \sum_{e\in\mathcal P_\vartheta}q_e+
        \sum_{e\in\mathcal P_\vartheta}p_e\le C_\vartheta,
\end{equation}
and, for all $R\ge2$,
\begin{equation}

        \sum_{\substack{e\in\mathcal P_\vartheta\\ \ell(e)>R}}q_e+
        \sum_{\substack{e\in\mathcal P_\vartheta\\ \ell(e)>R}}p_e
        \le \frac{C_\vartheta}{R}+o_n(1).
