{"assumptions":[],"created_at":"2026-10-26T20:46:26.255994+00:00","domain":"probability theory","id":"claim_f4880d5e211386dae22bf54f7b1e3edc5ebc8c73dcc51155bf238cfbaae8bb53","kind":"theorem","schema_version":1,"statement":"[Prp 44 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that $\mu$ satisfies $\rm{Reg}_{s_0,s_1}$.
  \begin{itemize}
    \item [$\mathrm{(i)}$]If $F$ is compact, then there exists a constant $\g{c}{c_1,1}=c_{\rm{A1}}^{2(1-\kappa)}(\g{c}{unihk,1})^{2\kappa-1}\in (0,\infty)$ such that
  \begin{align*}
    |p(t,x,y)-p(t,x,z)|\lesssim \g{c}{c_1,1} t^{-\frac{2\kappa s_0 + 3\kappa - 1}{1+s_0}}R(y,z)^{\kappa},\quad x,y,z\in F,\;t\in (0,1],\;\kappa\in [1/2,1].
  \end{align*}
    \item [$\mathrm{(ii)}$]If $(F,R,\mu)$ satisfies $\mathrm{(A2)}$, then there exists a constant 
    $\g{c}{c_1,2}=c_{\rm{A1}}^{2(1-\kappa)}(\g{c}{continuity,2})^{2\kappa-1}\in (0,\infty)$ such that
  \begin{align*}
    |p(t,x,y)-p(t,x,z)|\lesssim \g{c}{c_1,2} t^{-\frac{2[\theta(1+s_0)-s_1]\kappa+s_0\theta+s_1}{2\theta(1+s_0)}}R(y,z)^{\kappa},\quad x,y,z\in F,\;t\in (0,1],\;\kappa\in [1/2,1].
  \end{align*}
    \item [$\mathrm{(iii)}$]If $(F,R,\mu)$ satisfies $\mathrm{(A3)}$, then there exists a constant $\g{c}{c_1,3}=c_{\rm{A1}}^{2(1-\kappa)}(\g{c}{continuity,2})^{2\kappa-1}\in (0,\infty)$ such that
  \begin{align*}
    |p(t,x,y)-p(t,x,z)|\lesssim \g{c}{c_1,3} t^{-\frac{2[(1+s_0)\Theta-s_1]\kappa+s_0\Theta+s_1}{2(1+s_0)\Theta}}R(y,z)^{\kappa},\quad x,y,z\in F,\;t\in (0,1],\;\kappa\in [1/2,1],
  \end{align*}
  where $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$
  \end{itemize}
\begin{rmk}
  Since $\kappa\le 1$, the estimate in \cref{c_1}(i) is better that that in \cref{unihk}.
\end{rmk}
  \begin{rmk}
  The constant $\g{c}{continuity,2}$ in $\g{c}{c_1,2}$
  does not necessarily coincide with
  that in $\g{c}{c_1,3}$ since the constants and exponent in the heat kernel estimate may differ.
  We shall continue to use this abuse of notation throughout this section. 
  \end{rmk}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:40.047542+00:00","domain":"probability theory","id":"claim_f48db17ccf1602387eb6482b5e4b06418e18ee0ca0fc0a68b43fe7751462b877","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] There exists $\gamma\in (0,1)$ such that for every $\delta \in (0,1)$ we can find a constant $c_{12}=c_{12}(\delta)>0$ such that for $\bbQ$-a.a.\ $\omega \in \Omega_{\lambda,\Lambda}$ there exists $N_0(\omega,\delta) \in \bbN$ such that for every $N \geq N_0(\omega,\delta)$,
    \begin{equation}
        \big|\bbE^{\omega,+}_N[\varphi_x - \varphi_y]\big| \leq  c_{12}\frac{|x-y|_\infty^{\gamma}}{N^{\gamma-\delta}}\,,\qquad \forall x,\,y\in\bbZ^d.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.553272+00:00","domain":"probability theory","id":"claim_f490130d4bf4e58d08a1be0561a143fbbd5e1592e7e8d7bf1fa7496e6f9c8d2e","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2608.27156, 'Traveling Waves in Equity Markets with\\Rank-Based Entry and Exit'] For each $t \in [0,T]$ let $\xi_t$ be the finite measure on $\R$ with scaled CDF $H(t,y) = m_t\, V(t,y)$, where $m$ is continuous and positive and $V$ is jointly continuous, nondecreasing in $y$, with $V(t, -\infty) = 0$ and $V(t, +\infty) = 1$ for every $t$. Let $(\xi^n_t)_{t \leq T}$ be paths of finite measures with scaled CDFs $H_n(t,y) = \xi^n_t((-\infty, y])$ and masses $m^n_t = \xi^n_t(\R)$. If
\begin{equation*}
    \sup_{t \leq T} \big| \langle \xi^n_t, \varphi \rangle - \langle \xi_t, \varphi \rangle \big| \;\longrightarrow\; 0
    \quad \text{for every } \varphi \in C_c(\R),
    \qquad \text{and} \qquad
    \sup_{t \leq T} \big| m^n_t - m_t \big| \;\longrightarrow\; 0,
\end{equation*}
then $\sup_{t \leq T} \sup_{y \in \R} \big| H_n(t,y) - H(t,y) \big| \to 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:15:36.169141+00:00","domain":"probability theory","id":"claim_f4971843c9459dd61109bd33e13e79f9740ca88ee763438d199ec894795178be","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2609.01774, 'Hypoellipticity on time-periodic space-times'] Assume that for some $\gamma,\rho>0$, $N_P(z) = C z^{\gamma} + O (z^{\gamma-\rho})$.

