        u\left(x,T_1\right)\leq u\left(y,T_2\right)\left(\frac{T_2}{T_1}\right)^{\frac{c_1}{\psi^{\prime}\left(1\right)}}\exp\left(\frac{c_2}{\psi^{\prime}\left(1\right)}\left(T_2-T_1\right)+\frac{\psi^{\prime}\left(1\right)H_{\psi}\mu_{\max}d^2\left(x,y\right)}{\left(1-\alpha\right)w_{\min}\left(T_2-T_1\right)} \right).
    \end{equation*}","status":"unverified"}

