{"assumptions":[],"created_at":"2026-10-26T19:27:08.845917+00:00","domain":"probability theory","id":"claim_f6e4eae66bd1f2b4c1a47de1cc964ebb5cfae979e65cec0cba52debd3e248a0a","kind":"concept","schema_version":1,"statement":"[Prop 21 (Schwinger--Dyson Equations) of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] Let $Q\in \PP_d$ and $1\le j\le d$.
    \begin{enumerate}
        \item[(a)]
        If $\bs{X}^N = (X^N_1,\ldots,X^N_d)$ is a $d$-tuple of independent GUE random matrices in $\M_N(\C)$, then 
        \begin{equation}    
            \E\left[\ts_N(X_j^N Q(\bs{X}^N))\right] = \E\left[\ts_N\otimes\ts_N\left((\partial_jQ)(\bs{X}^N)\right)\right],
        \end{equation}
        where we recall $\ts_N$ is the normalized trace. 
        \item[(b)]
        If $\bs{x}=(x_1,\dots, x_d)$ is a $d$-tuple of freely independent semicircular random variables, 
        \begin{equation}    
            \tau(x_j Q(\bs{x})) = \tau\otimes\tau\left((\partial_jQ)(\bs{x})\right).
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:08.956139+00:00","domain":"probability theory","id":"claim_f6e90bddfd812f29996293e97a31dc192bdb2b9c28174a62321f27969fccc5aa","kind":"theorem","schema_version":1,"statement":"[Proposition prop:sample_mean of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let the assumptions of Theorems~(thm:explicit_density of the paper),~(thm:explicit_current_1 of the paper)
and~(thm:explicit_current_2 of the paper) hold, with the corresponding sub-gamma parameters
$\tilde\sigma_A^2$ and $c_A$ established there for $\overline{A}_t \in
\{\overline{\rho}_t(V), \overline{J}_t(U)\}$. Then for every $n \geq 1$, $t>0$, and
$a>0$, the sample mean $\widehat{A}_{n,t}$ satisfies the one-sided bound
\begin{align}
  \mathbb{P}^\nu\left(\widehat{A}_{n,t} - \E^\mu[\overline{A}_t] \geq a\right)
  \leq
  N_\nu^{n}
  \exp\left[-nt\frac{\tilde\sigma_A^2}{c_A^2}
  h\left(\frac{c_A a}{\tilde\sigma_A^2}\right)\right],

\end{align}
and the corresponding two-sided bound
\begin{align}
  \mathbb{P}^\nu\left(\left|\widehat{A}_{n,t} 
  - \E^\mu[\overline{A}_t]\right| \geq a\right)
  \leq
  2 N_\nu^{n}
  \exp\left[-nt\frac{\tilde\sigma_A^2}{c_A^2}
  h\left(\frac{c_A a}{\tilde\sigma_A^2}\right)\right].

\end{align}
Here, $\mathbb{P}^\nu$ now denotes the underlying initial law of the $n$ independent trajectories. 
In particular, $\widehat{A}_{n,t}$ obeys the single-trajectory bounds
($n=1$) of Section~(sec:conc_poincare of the paper)
and also Eq.~(equation eq:uq_general of the paper) by replacing $t \to nt$ and $N_\nu \to N_\nu^n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.343148+00:00","domain":"probability theory","id":"claim_f6f6bbbcdd5f47b8fb6b123bb66a9fec90285b769e4e20fac04c5169e76581ff","kind":"concept","schema_version":1,"statement":"[Proposition 19 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K'$ be a graph over $V$. Then:
