{"assumptions":[],"created_at":"2026-10-26T20:54:34.578271+00:00","domain":"probability theory","id":"claim_f7387e4bcb18ca33c0f91af3c499dd91ed242346bb1a3c4f52a1e9f96acc57d2","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ with $\left\|f\right\|_{\Leb^\infty}\leq 1$, and $1\leq q\leq p\leq 2$,
\begin{equation}
    \frac{\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}/\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^{2})\big]^{kp/2}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-Gaussian}}}(p,q)^k \Wop^{\geq k}(f),
\end{equation}
and further,
\begin{equation}
    \sum_{\kappa\in \Nbb^n:|\kappa|=k}\frac{\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p}}{\big[1+\frac{q}{2k(2-q)} \ln^{+}(\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p}/\left\|\Dop^\kappa f\right\|_{\Leb^q}^{2})\big]^{kp/2}} \geq C^{\text{\rm\ref{thm:high-order-Lp-Lq-Gaussian}}}(p,q)^k \Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Lp-Lq-Gaussian}}}(p,q) = C^{\text{\rm\ref{thm:high-order-Lp-Lq-energy-Boolean}}}(p,q) \gtrsim 2-q$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.829532+00:00","domain":"probability theory","id":"claim_f74c5021a1ca2ea81eccc71d74ffbd5ab5b7913290039645a8ea2ba8aaf1a5e9","kind":"theorem","schema_version":1,"statement":"[Corollary cor:level-two of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Let $c=\beta-\alpha>0$ and
\begin{equation}
\lambda_\infty=\frac{\beta\mu}{c}.
\end{equation}
Then
\begin{align}
\mathbb{E}[N_T]
&=\lambda_\infty T+(\ell-\lambda_\infty)\frac{1-e^{-cT}}{c},
\\
\mathbb{E}\left[\int_0^T t\,\mathrm{d} N_t\right]
&=\frac{\lambda_\infty T^2}{2}
+(\ell-\lambda_\infty)
