    p_t &=  e^{-\frac{c}{2}t}\Bigl[-btq_0 + \Bigl(1-\mfrac{c}{2}t\Bigr)p_0  \Bigr] - \int_0^t e^{- \frac{c}{2} (t-s) }\Bigl[1-\mfrac{c}{2}(t-s)\Bigr] \nabla V(q_s,\tilde q_s) ds \\
    &\qquad + \tilde c\int_0^t e^{- \frac{c}{2} (t-s) }\Bigl[1-\mfrac{c}{2}(t-s)\Bigr] dB_s.
\end{align*}","status":"unverified"}

