{"assumptions":[],"created_at":"2026-10-27T20:01:25.573797+00:00","domain":"probability theory","id":"claim_fbd0a90b73c5f983a6540ac7b773bbc96c7ae0408f653cc09d1ceb34335e8fb1","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] (Quasi-regular weak solutions)\label[definition]{Def-sol-QR-*}
Let $\varepsilon>0,$		    $f_0\in H$    and   $N\in   \mathbb{N}$.   We  say that  $f^\varepsilon_N$  is   quasi-regular weak solution   to  (equation Ito-FP_eps-V2 of the paper)  if  
		$f^\varepsilon_N$    is $(\mathcal{F}_t)_t$-adapted and
		\begin{enumerate}
                \item $f^\varepsilon_N \in L^2(\Omega ;L^2(0, T;V))\cap L^2_{w-*}(\Omega ;L^\infty(0, T;H)) \cap L^2(\Omega;C_w([0,T];H))$.
        \item P-a.s. for any $t\in [0,T]$, it holds  
    	\begin{align*}
                    (f^\varepsilon_N(t), \phi )_H 
        &=(f_0, \phi )_H-\dfrac{1}{\beta}\int_0^t\left(f^\varepsilon_N , \phi \right)_Vds+\alpha_N\int_0^t( f^\varepsilon_N,\Delta_x \phi)_H ds\\&+\sum_{k\in K}\int_0^t\big(f^\varepsilon_N(s),( \sigma_k^N.\nabla_x\phi +(\nabla \sigma_k^Nr).\nabla_r (\varphi_\varepsilon\phi)+(\nabla \sigma_k^Nr).\dfrac{\kappa r}{1-\vert r\vert^2}\varphi_\varepsilon\phi)\big)_HdW^k(s)\notag\\
        & - \dfrac{1}{2}\int_0^t\left(\varphi_\varepsilon^2A^N(r)\nabla_rf^\varepsilon_N,\nabla_r\left(\dfrac{\phi}{\mathbf{M}}\right)\right) ds, \quad \forall \phi\in \mathbb{X}= L^2_{\mathbf{M}} (D;H^2(\mathbb{T}^2)) \cap V. \notag\end{align*}           
			\item (Regularity in Mean) For all    $n\in   \mathbb{N^*}$   and each function   $g\in   G_n$,   the deterministic   function    $V^\varepsilon_N(t,x,r)=\ensuremath{\mathbb{E}}[f^\varepsilon_N(t,x,r)e_g(t)]$ is  a   measurable  function,   which   belongs to  $ L^\infty(0, T;H)\cap    C_w([0, T];H)\cap L^2(0, T;V)$    and  for any $t\in[0,T],$    it  holds    (see    (prop-exisence-mean of the paper)) 
			\begin{align*}
				&( V^\varepsilon_N(t),\phi)_H=(f_0,\phi)_H+\int_0^t \left(V^\varepsilon_N(s), h_n\cdot \nabla_x \phi + y_n \cdot\nabla_r (\phi\varphi_\varepsilon)+y_n \cdot \dfrac{\kappa r}{1-\vert r\vert^2} (\phi\varphi_\varepsilon) \right)_Hds \\
				&        -\dfrac{1}{\beta}\int_0^t(V_N^\varepsilon, \phi)_V ds+\alpha_N\int_0^t( V^\varepsilon_N,\Delta_x \phi)_H ds- \dfrac{1}{2}\int_0^t\big(\varphi_\varepsilon^2 A^N(r) \nabla_rV^\varepsilon_N,\nabla_r\left(\dfrac{\phi}{\mathbf{M}}\right)\big) ds, \quad \forall \phi\in \mathbb{X},
			\end{align*}
       where   $K_n=\{k\in K: \min(n,N) \leq    \vert   k\vert  \leq    \max(2N,n)\}$ and 
			\begin{align*}
			h_n:=\sum_{k\in K_n}g_k\sigma_k^N   \text{  and } y_n:=\sum_{k\in K_n}g_k(\nabla \sigma_k^N r). 
			\end{align*}

		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.754002+00:00","domain":"probability theory","id":"claim_fbd6ae8695e1054fe67c419e41b8977ce25bd69caf4f59888331b851ad33e2d7","kind":"theorem","schema_version":1,"statement":"[Prop 1stOrderPDE of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $\mathsf{c}\in \mathbb{R}$. Suppose $\mathfrak{D}_{0;N} \overset{N \to \infty}{\longrightarrow} \mathfrak{D}_0 \in \mathfrak{LP}$. Then, as $N \to \infty$, $\mathfrak{D}_{\bullet;N} \overset{\mathrm{d}}{\longrightarrow}\mathfrak{D}_{\bullet}$ in $\mathrm{C}(\mathbb{R}_+;\mathfrak{LP})$ with the (deterministic) evolution $t\mapsto\mathfrak{D}_t$ solving the equation
\begin{equation}
\partial_t \mathfrak{D}_t(z)=-\frac{z^2}{2}\mathfrak{D}_t(z)-\mathsf{c}z\partial_z\mathfrak{D}_t(z).
\end{equation}
Moreover, for $\mathfrak{D}_0\in \mathfrak{LP}$, the unique solution to this equation is given by,
    \begin{align*}
        \mathfrak{D}_t(z)
        =\mathfrak{D}_0\left(z\mathrm{e}^{-\mathsf{c}t}\right)
        \exp\left(\frac{-z^2}{4\mathsf{c}}
        \left(1-\mathrm{e}^{-2\mathsf{c}t}\right)\right),
    \end{align*}
which for $\mathsf{c}=0$ simplifies to $\mathfrak{D}_t(z)=\mathfrak{D}_0(z)\mathrm{e}^{-tz^2/2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.788904+00:00","domain":"probability theory","id":"claim_fbdb080ebbd1c9fc22ba9bec8864074710fd6e92b8518bdc5bd55f7cbd63091c","kind":"concept","schema_version":1,"statement":"[Theo 17 of arXiv:2609.02261, 'Quantization and process'] Let $(\nu_h)\in {\cal M} ( \gamma , \R^{2n} )$  with $\gamma <0$. Suppose that  the function 
  $\varphi $ in  (\ref{Four-mes}) is a quadratic form, namely,

   \be \varphi (u) = - \frac  {1}  {2} 
     \sum _{jk} a_{jk} u_j u_k = - \frac  {1}  {2}  (Au ) \cdot  u , \ee 

  where   $A=(a_{ij})$ is a symmetric  matrix with a   definite positive 
  real part.   Then, 


  i) We have for every  $F$ and  $G$ in  $ D_{\lambda h}(\R^{2n})$ 
