{"assumptions":[],"created_at":"2026-10-27T16:53:30.674053+00:00","domain":"probability theory","id":"claim_fca003a548a9fdbf5fe11b52f5c06bcb74570cfedaa6c7f397546bf6a3eb1d5d","kind":"concept","schema_version":1,"statement":"[Prop DiffBregDist of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] Assume that $F$ is twice differentiable on $U$ and that $P$ satisfies the  moment  assumption~(equation eq:Integrabilite of the paper), and assigns no weight to hyperplanes.

\medskip
\noindent $(a)$ {\em Case $r=2$}. Then $G_n$ is differentiable at every  $x\!\in U^n$ having pairwise distinct components and 
\begin{equation}
 \nabla G_n (x)= \left[\frac{\partial G_n}{\partial x_i}(x)\right]_{i=1,\ldots,n}={\rm Diag}\big(\nabla^2 F(x_i)\big)_{i=1,\ldots,n} \Big[\int_{C_i(x)}(x_i-\xi)P(\mathrm{d}\xi) \Big]_{i=1,\ldots,n}
\end{equation}
for any Bregman--Voronoi partition $(C_i(x))_{i=1,\ldots,n}$ of $U$ induced by $x$ where ${\rm Diag}\big(\nabla^2 F(x_i)\big)_{i=1,\ldots,n} $ denotes the $dn\times dn$ block diagonal matrix made up with the Hessians of $F$ at the points $x_i$. 

\medskip
\noindent $(b)$ {\em Case $r>2$}. Then $G^F_{r,n}$ is differentiable at every  $x\!\in U^n$ having pairwise distinct components and 
\begin{align}
\nonumber \nabla G^F_{r,n} (x)&= \left[\frac{\partial G^F_{r,n}}{\partial x_i}(x)\right]_{i=1,\ldots,n}\\
 &=\tfrac r2 \big({\rm Diag}\nabla^2 F(x_i)\big)_{i=1,\ldots,n} \left[\int_{C_i(x)}(x_i-\xi)\phi_{_F}(\xi,x_i)^{\frac r2-1}P(\mathrm{d}\xi) \right]_{i=1,\ldots,n}.
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.251488+00:00","domain":"probability theory","id":"claim_fca0a08489c477ff58ceb88cd6a52f75a95e76a262226df7d4b7a922bd15aee4","kind":"concept","schema_version":1,"statement":"[Theorem thm: Gaussian Wasserstein-$p$ upper bound for M/M/1+M of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] Consider SSQ in heavily overloaded regime (ass:heavy_overload of the paper) and $\gamma\leq \gamma_0$, (equation eq: gamma assumption for SSQ W-p of the paper), the Wasserstein-$p$ distance, between law $\mathcal{L}(\tilde{q})$ and standard normal distribution $\mathcal{L}(Z):=\mathcal{N}(0,1)$ satisfies:

\begin{subnumcases}{\mathcal{W}_p(\mathcal{L}(\tilde{q}), \mathcal{L}(Z)) \leq}
    D_{1,\lambda,\mu} \cdot p\sqrt{\gamma} & $p \in [1, 1/\gamma^{1-2\alpha-2\epsilon}]$ \\
    D_{2,\lambda,\mu} \cdot \sqrt{p} & $p \in (1/\gamma^{1-2\alpha}, D_{4,\lambda,\mu}/\gamma)$ \\
    D_{3,\lambda,\mu} \cdot \frac{p\sqrt{ \gamma}}{\log(1+\gamma p/\lambda)} & $p \in [D_{4,\lambda,\mu}/\gamma, \infty)$ 
\end{subnumcases}
\begin{subnumcases}{\mathcal{W}_p(\mathcal{L}(\tilde{q}), \mathcal{L}(Z)) \geq}
    C'_{7, \lambda, \mu} \cdot \gamma \exp\left(-\frac{\lambda/\mu - \ln(\lambda/\mu) -1 }{p\gamma/\mu}\right) & $p \in [1, D_{5,\lambda,\mu}
    /\gamma)$ \\
    D_{4,\lambda,\mu}' \cdot \frac{p\sqrt{\gamma}}{\log(1+\gamma p/\lambda)} & $p \in [D_{5,\lambda,\mu}/\gamma, \infty)$
\end{subnumcases}

Where $\epsilon \in (0,1/2-\alpha)$ is any constants. All other constants involved are defined explicitly in (equation eq: constants for SSQ Wasserstein-$p$ bounds of the paper), (equation eq: Wasserstein-$p$ bound, first regime of the paper), (equation eq: Wasserstein-$p$ bound, second regime of the paper), (equation eq: Wasserstein-$p$ bound, third regime of the paper) and (equation eq: D_4, lambda, mu SSQ of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

