		\left| \comdersmall^{[1,N+1];1} \LogDensity \right| & \lesssim \left| \comdersmall^{[1,N+1];1} \velocityarray\right| + \upmu \left| \tander^{[1,N+1]}\velocityarray\right| +  \left|\tander^{\le N} (\vortrenormalized,\GradEnt)\right| + \fundbootsmall \left| \tandersmall^{[1,N]} \badcontrolvars\right|   \\		
		\left| \comdersmall^{[1,N+1]; 2} \LogDensity \right| & \lesssim \left|\comdersmall^{[1,N+1]; 2}\velocityarray\right| + \upmu \left| \comdersmall^{[1,N+1];\le 1} \velocityarray\right| + \upmu  \left|\tander^{\le N} (\vortrenormalized,\GradEnt)\right| + \fundbootsmall \left|\comderdoublesmall^{[1,N];\le 1} \badcontrolvars\right|
