{"assumptions":[],"created_at":"2026-10-27T21:41:19.332509+00:00","domain":"probability theory","id":"claim_fd054aee2323ed883b83a3210619910a463cc836a3c53eb2331a095292c974a9","kind":"definition","schema_version":1,"statement":"[Definition def:weak_axioms of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] We define a \emph{weak geodesic CLE$_4$ metric coupling} to be a family of couplings
	\begin{equation*}
		D= \left\{(\Gamma_U, D_{\Gamma_U}^U)\right\}_U
	\end{equation*}
	where $U \subsetneq \BC$ ranges over all simply connected domains, and for each $U$, $\Gamma_U$ is a non-nested CLE$_4$ in $U$, such that the following conditions are satisfied for every such $U$ and all deterministic choices of the auxiliary data ($V$, $I$, $\phi$, arcs) below:
	\begin{enumerate}[label=(\Roman*), ref=\Roman*]
		\item {\bfseries (Weak geodesic metric)} $D_{\Gamma_U}^U$ is a.s.\ a metric on $\Gamma_U$ satisfying the following conditions:
		\begin{enumerate}[label=(\roman*), ref=\roman*]
			\item Let $\SCL \in \Gamma_U$ and $t \ge 0$. Then the metric ball $\SCB_t(\SCL; D_{\Gamma_U}^U)$ is connected.
			\item Let $\SCL \in \Gamma_U$ and $t \ge 0$. Let $\phi\colon U \to \BD$ be a conformal mapping. Then
			\begin{equation*}
				\lim_{t^\prime \downarrow t} \phi (\SCB_{t^\prime}(\SCL; D_{\Gamma_U}^U) )= \phi (\SCB_t(\SCL; D_{\Gamma_U}^U)) \quad \text{and} \quad \lim_{t^\prime \uparrow t} \phi (\SCB_{t^\prime}(\SCL; D_{\Gamma_U}^U)) = \phi (\SCB_t^-(\SCL; D_{\Gamma_U}^U))
			\end{equation*}
			with respect to the Hausdorff metric, the second limit being required only for $t > 0$; see (subsec:setup of the paper) for the convention used when a ball is empty.
			\item Let $\SCL_1, \SCL_2 \in \Gamma_U$ and $t \ge 0$. Suppose that $\SCB_t(\SCL_1; D_{\Gamma_U}^U) \cap \SCL_2 = \emptyset$. Then
			\begin{equation*}
				D_{\Gamma_U}^U(\SCL_1, \SCL_2) = t + D_{\Gamma_U}^U(\SCB_t(\SCL_1; D_{\Gamma_U}^U), \SCL_2). 
			\end{equation*}
			\item Let $\SCL_1, \SCL_2 \in \Gamma_U$. Then the closed set $K_{\SCL_1, \SCL_2}$ defined as the closure of $\{ z \in \overline U : D_{\Gamma_U}^U(\SCL_1, z)+ D_{\Gamma_U}^U(\SCL_2,z)= D_{\Gamma_U}^U(\SCL_1, \SCL_2) \}$ has a connected component containing $\SCL_1 \cup \SCL_2$.
		\end{enumerate}
		Items~(equation it:weak_axiom_geodesic_0 of the paper)--(equation it:weak_axiom_geodesic_4 of the paper) are also required with a deterministic connected arc (resp.\ two disjoint such arcs) of $\partial U$ in place of $\SCL$ or $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
		\item {\bfseries (Locality)}
		Let $V \subset U$ be a deterministic simply connected subdomain. Let $I \subset \partial U$ be a deterministic connected arc. Let $\{V_j\}_j$ be the connected components of $V^\star$. Then there exists a coupling $(\Gamma_U, D_{\Gamma_U}^U, \{D_{\Gamma_U|_{V_j}}^{V_j}\}_j)$ such that the following hold: 
			\begin{itemize}
				\item Conditionally on the $\sigma$-algebra generated by
				\begin{multline}
					\bigl\{\SCL \in \Gamma_U : \SCL \not\subset V\bigr\}, \quad \bigl\{\SCB_t(\SCL; D_{\Gamma_U}^U) : \SCL \in \Gamma_U, \ \SCL \not\subset V, \ t \in [0, D_{\Gamma_U}^U(\SCL, \partial V^\star)]\bigr\}, \\
					\text{and} \quad \bigl\{\SCB_t(I; D_{\Gamma_U}^U) : t \in [0, D_{\Gamma_U}^U(I, \partial V^\star)]\bigr\}
				\end{multline}
				the $(\Gamma_U|_{V_j}, D_{\Gamma_U|_{V_j}}^{V_j})$'s are independent and their conditional laws are those of $(\Gamma_{V_j}, D_{\Gamma_{V_j}}^{V_j})$, respectively. 
				\item For all $j$, for all $\SCL_1, \SCL_2 \in \Gamma_U|_{V_j}$, we have $D_{\Gamma_U}^U(\SCL_1, \SCL_2)\le D_{\Gamma_U|_{V_j}}^{V_j}(\SCL_1, \SCL_2)$.
				\item For all $j$, for all $\SCL \in \Gamma_U|_{V_j}, \ t \in [0, D_{\Gamma_U}^U(\SCL, \partial V_j)]$, we have $\SCB_t(\SCL; D_{\Gamma_U}^U) = \SCB_t(\SCL; D_{\Gamma_U|_{V_j}}^{V_j})$.
		\end{itemize} 
		\item {\bfseries (Conformal invariance)} Let $\phi \colon U \to \phi(U)$ be a deterministic conformal mapping. Then,
		\begin{equation*}
				\left(\phi(\Gamma_U), \left( D_{\Gamma_U}^U\left(\phi^{-1}(\SCL_1), \phi^{-1}(\SCL_2) \right) \right)_{\SCL_1, \SCL_2 \in \phi(\Gamma_U)} \right)
