{"assumptions":[],"created_at":"2026-10-26T19:32:58.363334+00:00","domain":"probability theory","id":"claim_ffa6df470fa637ffd81bb35ec6964babef6b7e7f7e55c86ba221050ce066d5ad","kind":"theorem","schema_version":1,"statement":"[Proposition 1 of arXiv:2506.19273, 'A large deviation view of \emph{stationarized} fully lifted blirp interpolation'] Let vectors $\m = [\m_1 ]$, $\p=[\p_0,\p_1,\p_2]$,  and $\q=[\q_0,\q_1,\q_2]$ be such that  $\p_0\geq \p_1\geq \p_2=0$ and $\q_0\geq \q_1\geq \q_2=0$. For $k\in\{1,2\}$  let the elements of $G\in\mR^{m \times n},u^{(4,k)}\in\mR^1,\u^{(2,k)}\in\mR^{m\times 1}$, and $\h^{(k)}\in\mR^{n\times 1}$ be independent standard normals. Set $a_k=\sqrt{\p_{k-1}\q_{k-1}-\p_k\q_k}$, $b_k=\sqrt{\p_{k-1}-\p_k}$, $c_k=\sqrt{\q_{k-1}-\q_k}$, and  ${\mathcal U}_k=[u^{(4,k)},\u^{(2,k)},\h^{(k)}]$. Let sets ${\mathcal X}=\{\x^{(1)},\x^{(2)},\dots,\x^{(l)}\}$, $\bar{{\mathcal X}}=\{\bar{\x}^{(1)},\bar{\x}^{(2)},\dots,\bar{\x}^{(l)}\}$, and ${\mathcal Y}=\{\y^{(1)},\y^{(2)},\dots,\y^{(l)}\}$  (with $\x^{(i)},\bar{\x}^{(i)}\in \mR^{n}$ and $\y^{(i)}\in \mR^{m}$), real scalars $\beta$, $p$, and $s$ (with $\beta,p\geq 0$), and function $f_{\bar{\x}^{(i_3)}} (\cdot): \mR^n\rightarrow \mR$ be given. One then has for function
\begin{equation}
\psi( t)  =  \mE_{G,{\mathcal U}_2} \frac{1}{p|s|\sqrt{n}\m_1}
\log \lp  \sum_{i_3=1}^{l}  \lp  \mE_{{\mathcal U}_1} \lp \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3 )}} \rp^{s}\rp^{\m_1} \rp^p \rp,
\end{equation}
with
\begin{eqnarray}
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T(b_2\u^{(2,1)}+b_2\u^{(2,2)})\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(a_1u^{(4,1)}+a_2u^{(4,2)}) +\sqrt{1-t}\|\y^{(i_2)}\|_2(c_1\h^{(1)}+c_2\h^{(2)})^T\x^{(i)}
\nonumber \\
& &
   + f_{\bar{\x}^{(i_3)}  } (\x^{(i_1)}) ,
 \end{eqnarray}
that
\begin{eqnarray}
\frac{d\psi(t)}{d\p_1}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \phi^{(1,\p)}\nonumber \\
\frac{d\psi(t)}{d\q_1}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \phi^{(1,\q)},
 \end{eqnarray}
where $\phi$'s are as in (\ref{eq:cpt8}).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:29:35.087012+00:00","domain":"probability theory","id":"claim_ffac71c8223bba51feef1494a59b324456b1638cf4f4bf2f1e03096bff3d8dbb","kind":"concept","schema_version":1,"statement":"[Thm 12 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that hypotheses \ref{H0}, \ref{H1}, \ref{H2b}, \ref{H3} hold and 
