\begin{align}
&\sup_{t\in[0,T]}\norm{u_{n,k}^{(i)}(t,\cdot)}_{C^{1+\theta}_{b,\mathcal{V}_n}(H_n)}\leq  \mathfrak{C}_0\sup_{t\in[0,T]}\norm{g(t,\cdot)}_{C^{\theta}_b(H_n)},\\
&\mathfrak{C}_0=\frac{4(2+\varepsilon^{-\gamma_2})M_0}{(\varepsilon\mathfrak c)^{1-\gamma_2}(1-\gamma_2)}\left(1+\sup_{t\geq 0}\|C(t,\cdot)\|_{C^\theta_b(H;U)}\right),
\end{align}
where $M_0\geq 1$ and $0<\gamma_2<1$ are the constants given by Lemma \ref{lemma:stima_ind_n} and $\varepsilon\in (0,1]$ is given by \eqref{r-eps}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.356969+00:00","domain":"probability theory","id":"claim_ffb28ee8828bf7599c1763cfba235420f28a9a6559d4036617aa87907bf04c86","kind":"theorem","schema_version":1,"statement":"[Proposition 6 of arXiv:2506.18558, '2506.18558'] Suppose that  Assumption {\rm\ref{A2}} holds. Then the class of measures $\{\mu^x_{t}\}_{t\in\RR}$ given in Lemma $\ref{Le3.3}$ is an evolution system of measures for $\{P^x_{s,t}\}_{t\ge s}$. Moreover, for any Lipschitz continuous function $\phi$ on $\RR^m$, $t\ge s$ and $x\in \RR^m$,
\begin{align}
\left|P^x_{s,t} \phi(y)-\int_{\RR^m}\phi(z)\,\mu^x_t(dz)\right|\le  C {\rm Lip(\phi)} (1+|x|+|y|)e^{-\beta(t-s)}.
\end{align}
Furthermore, if $\{\nu^x_{t}\}_{t\in\RR}$ is another evolution system of measures for $\{P^x_{s,t}\}_{t\ge s}$ that satisfies
$$
\sup_{t\in\RR}\int_{\RR^m}|y|\nu^x_t(dy)<\infty,\quad   x\in\RR^n,
$$
then $\nu^x_t=\mu^x_t$ for all $t\in\RR$ and $x\in\RR^n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:09:23.970816+00:00","domain":"probability theory","id":"claim_ffb7c836c333c8360fc41054fe5c445a2cc7883e821ee6ac93e88a27560c415e","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2607.22438, 'A deterministic scalar reduction for the phase transition in two interacting urns'] For each \(z\in(1/2,3/4)\), the equation
\begin{equation*}
 \widetilde F_p(t,z)=0
\end{equation*}
has a unique solution \(q_p(z)\) in \((1/2,1)\). This solution lies on the decreasing part of the graph \(t\mapsto\widetilde F_p(t,z)\), and this solution satisfies \(q_p(z)>z\). Moreover,
\begin{equation}
 D_p(z):=\frac{\partial}{\partial t}\widetilde F_p(q_p(z),z)
 =-1+(1-p)h'(q_p(z))<0.
\end{equation}
The function \(q_p\) is analytic on \((1/2,1)\) and extends analytically to a neighborhood of \(z=1/2\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:43:55.604136+00:00","domain":"probability theory","id":"claim_ffb7fb71b84c8767653a2a071d4a93c01e372e4d5b72fd1135baef5bf8b2cc16","kind":"concept","schema_version":1,"statement":"[Corollary c:act of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] If $T \colon \mathscr{P}(S) \to \mathscr{P}(S)$ is order-preserving, then the following statements are equivalent:

